end
local function getHWID()
local h = nil
pcall(function()if gethwid then h = tostring(gethwid())end end)
if h and h ~= "" then return h end
pcall(function()
local id = game:GetService("RbxAnalyticsService"):GetClientId()
if id then h = tostring(id)end
end)
if h and h ~= "" then return h end
