end
local function saveKeyLocal(key)
pcall(function()if writefile then writefile(KEY_SAVE_FILE,tostring(key))end end)
end
local function loadKeyLocal()
local k = nil
pcall(function()
if isfile and isfile(KEY_SAVE_FILE)and readfile then k = readfile(KEY_SAVE_FILE)end
end)
if type(k)== "string" then
k = k:gsub("%s+","")
if k ~= "" then return k end
end
return nil
end
local function verifyKey(key)
key = tostring(key or ""):gsub("%s+","")
if key == "" then return false,"empty" end
local req = getRequest()
if not req then return false,"no_request" end
local ok,res = pcall(function()
return req({
Url = tostring(KEY_API_URL):gsub("/+$",""),
Method = "POST",
Headers ={["Content-Type"] = "application/json"},
Body = HttpService:JSONEncode({key = key,hwid = getHWID(),version = "2.4.0"}),
})
end)
if not ok or not res then return false,"request_failed" end
local body = res.Body or res.body
if type(body)~= "string" then return false,"bad_body" end
local decOk,data = pcall(function()return HttpService:JSONDecode(body)end)
if not decOk or type(data)~= "table" then return false,"bad_json" end
local statusText = tostring(data.status or data.message or data.error or "")
local allText = table.concat({tostring(data.status or ""),tostring(data.message or ""),tostring(data.error or "")}," "):lower()
local accepted = allText:find("licence valid",1,true)or allText:find("license valid",1,true)
local validFlag = data.ok == true or data.valid == true or tostring(data.valid):lower()== "true"
if validFlag or accepted then
saveKeyLocal(key)
return true,statusText ~= "" and statusText or "valid"
end
return false,tostring(data.error or data.message or data.status or "invalid")
end
