local function tryActivate(key,fromSaved)
if busy then return end
busy = true
btnLabel.Text = "VERIFICANDO…"
setStatus(fromSaved and "Key salva encontrada, validando…" or "Verificando…","warn")
task.spawn(function()
local okFlag,info = verifyKey(key)
busy = false
if okFlag then
btnLabel.Text = "PRONTO"
setStatus("Key válida — carregando o hub","ok")
keyVerified = true
task.wait(0.45)
close()
else
btnLabel.Text = "ATIVAR"
setStatus((fromSaved and "Key salva falhou: " or "")..(errors[info] or("Erro: " .. tostring(info))),"err")
local base = card.Position
tween(card,{Position = base + UDim2.fromOffset(6,0)},0.05)
task.delay(0.06,function()tween(card,{Position = base},0.25)end)
end
end)
end
