local function TrackConn(signal,handler)
local conn = signal:Connect(handler)
table.insert(genv.AutoCornerV25Connections,conn)
return conn
end
local function IsFiniteNumber(markerError)
return type(markerError)== "number" and markerError == markerError and markerError ~= math.huge and markerError ~= -math.huge
end
local function Clamp(ratio,delta,MaxCharge)
return math.clamp(ratio,delta,MaxCharge)
end
local function Lerp(evalLinearModel,evalLinearModel2,ratio)
return evalLinearModel +(evalLinearModel2 - evalLinearModel)* ratio
end
local function Flatten(vec)
return Vector3.new(vec.X,0,vec.Z)
end
local function GetMagnitude(vec,vec2)
return Vector3.new(vec2.X - vec.X,0,vec2.Z - vec.Z).Magnitude
end
local function GetPosition(part)
if not part then
return nil
end
if part:IsA("BasePart")then
return part.Position
end
if part:IsA("Model")then
return part:GetPivot().Position
end
return nil
end
local function GetPart(part)
if not part then
return nil
end
if part:IsA("BasePart")then
return part
end
local BoundingBox = part:FindFirstChild("BoundingBox",true)
if BoundingBox and BoundingBox:IsA("BasePart")then
return BoundingBox
end
if part:IsA("Model")and part.PrimaryPart then
return part.PrimaryPart
end
return part:FindFirstChildWhichIsA("BasePart",true)
end
local function GetMultiplier(arg1,ModuleSpikePower)
local ok,result = pcall(function()
return State.get(LocalPlayer,State.Id.Multiplier,arg1,ModuleSpikePower)
end)
if ok and IsFiniteNumber(result)then
return result
end
result = LocalPlayer:GetAttribute("Multiplier_" .. arg1)
if IsFiniteNumber(result)then
return result
end
local Character = LocalPlayer.Character
if Character then
result = Character:GetAttribute("Multiplier_" .. arg1)
if IsFiniteNumber(result)then
return result
end
end
return ModuleSpikePower
end
