local function NormalizeStyleName(Gameplay_Style)
local v = map2[string.lower(tostring(Gameplay_Style or "Unknown"))]
return v or tostring(Gameplay_Style or "Unknown")
end
genv.AutoCornerV25Profiles = AutoCornerV25Profiles
local function GetLocalStyle()
local Character = LocalPlayer.Character
return NormalizeStyleName(LocalPlayer:GetAttribute("Gameplay_Style")or Character and Character:GetAttribute("Gameplay_Style")or "Unknown")
end
local map3 ={}
local function OriginalStyleInfo(id)
id = NormalizeStyleName(id)
if map3[id] then
return map3[id]
end
local autoCornerV25Profile = AutoCornerV25Profiles[id]
local tbl ={
Id = id,
StaticProfile = autoCornerV25Profile,
DisplayName = autoCornerV25Profile and autoCornerV25Profile.DisplayName or id,
ProfileSource = autoCornerV25Profile and "SUPPLIED_STYLE_MODULES_V25" or "RUNTIME_REQUIRE",
ModuleSpikePower = autoCornerV25Profile and autoCornerV25Profile.SpikePower or 1,
ModuleTiltPower = autoCornerV25Profile and autoCornerV25Profile.TiltPower or 1,
ModuleJumpPower = autoCornerV25Profile and autoCornerV25Profile.JumpPower or 1,
BacktiltInfluence = autoCornerV25Profile and autoCornerV25Profile.BacktiltInfluence or 0,
TiltInfluence = autoCornerV25Profile and autoCornerV25Profile.TiltInfluence or 0,
HasSpecial = autoCornerV25Profile and autoCornerV25Profile.HasSpecial or false,
DoubleTiltSpecial = autoCornerV25Profile and autoCornerV25Profile.DoubleTiltSpecial or false,
SpecialPower = 0,
}
local Special = autoCornerV25Profile and autoCornerV25Profile.Special or{}
local v = Style:FindFirstChild(id)
if v then
local ok,module = pcall(require,v)
if ok and type(module)== "table" then
tbl.Raw,tbl.ProfileSource = module,"RUNTIME_MODULE"
local Multipliers = module.Multipliers or{}
tbl.ModuleSpikePower = tonumber(Multipliers.SpikePower)or tbl.ModuleSpikePower
tbl.ModuleTiltPower = tonumber(Multipliers.TiltPower)or tbl.ModuleTiltPower
tbl.ModuleJumpPower = tonumber(Multipliers.JumpPower)or tbl.ModuleJumpPower
local Metadata = module.Metadata or{}
tbl.BacktiltInfluence = tonumber(Metadata.BacktiltInfluence)or tbl.BacktiltInfluence
tbl.TiltInfluence = tonumber(Metadata.TiltInfluence)or tbl.TiltInfluence
Special = Metadata.Special or Special
end
end
tbl.SpecialId,tbl.SpecialMove,tbl.SpecialType = Special.Id,Special.Move,Special.Type
tbl.SpecialActionMove = Special.ActionMove
local Metadata2 = Special.Metadata or Special
tbl.SpecialPower = tonumber(Metadata2.Power)or 0
local str = string.lower(id)
tbl.IsKijo = string.find(str,"kijo",1,true)~= nil
tbl.IsTimeskip = string.find(str,"timeskipshoyo",1,true)~= nil
tbl.IsKazana = string.find(str,"kazana",1,true)~= nil
tbl.IsFeiko = string.find(str,"feiko",1,true)~= nil
tbl.IsCurvePassive = string.find(str,"jester",1,true)~= nil
tbl.SuppressSpikeSpecial = not tbl.IsCurvePassive and(tbl.SpecialMove == "Spike" or tbl.SpecialActionMove == "Spike")
tbl.Advanced = tbl.ModuleSpikePower > 1.25 or tbl.ModuleTiltPower > 1.05 or tbl.BacktiltInfluence > 0 or tbl.TiltInfluence > 0 or tbl.HasSpecial
map3[id] = tbl
return tbl
end
local function GetSpecialCharge(arg)
local StyleInfo = arg.StyleInfo
if StyleInfo.IsKijo then
return 0
end
if StyleInfo.IsTimeskip then
return 0
end
if StyleInfo.IsKazana then
return 3
end
if arg.SpikePower >= 1.45 then
return 3.5
end
if arg.SpikePower >= 1.3 then
return 2.5
end
if arg.Advanced then
return 1.75
end
return 0
end
local function GetNormalizedSpecials(StyleInfo)
if not normalizeSpecials or not StyleInfo then
return nil,nil
end
if StyleInfo.IsKijo then
return GetKijoCharge(),GetKijoLateral()
end
if StyleInfo.SuppressSpikeSpecial then
return 0,0
end
return nil,nil
end
local function ApplySpecialNormalization(arg1,StyleInfo)
if type(arg1)~= "table" then
return
end
local specialCharge,lateralInfluence = GetNormalizedSpecials(StyleInfo)
if specialCharge == nil then
return
end
arg1.Metadata = arg1.Metadata or{}
arg1.Metadata.SpecialCharge = specialCharge
arg1.SpecialCharge = specialCharge
if StyleInfo.SuppressSpikeSpecial then
arg1.ClientCanRunSpecial,arg1.CanSpecialRun = false,false
end
pcall(function()
if arg1.State and arg1.State.Custom then
if StyleInfo.IsKijo then
arg1.State.Custom.LateralInfluence = lateralInfluence
end
if StyleInfo.SuppressSpikeSpecial then
arg1.State.Custom.SpecialChargeConstant = 0
end
end
end)
end
local function ProcessHitboxPatched(list,cframe,StyleInfo)
ApplySpecialNormalization(cframe,StyleInfo)
return table.pack(processHitboxCollision(table.unpack(list,1,list.n)))
end
local function ChargeCurve(ratio)
ratio = Clamp(ratio,0,1)
if ratio <= 0.8 then
return ratio / 0.8 * 0.5
end
if ratio <= 0.9 then
return Lerp(0.5,0.7,(ratio - 0.8)/ 0.1)
end
return Lerp(0.7,0.8,(ratio - 0.9)/ 0.1)
end
local function ChargePowerMultiplier(ratio)
return 1 + ChargeCurve(ratio)
end
local function GetRootPart()
local Character = LocalPlayer.Character
if not Character then
return nil
end
local HumanoidRootPart = Character:FindFirstChild("HumanoidRootPart")
if not HumanoidRootPart then
return nil
end
local inst2 = nil
local huge = math.huge
for _,inst in ipairs(CollectionService:GetTagged("Ball"))do
if inst:IsDescendantOf(Workspace)then
local position = GetPosition(inst)
if position then
local Magnitude =(position - HumanoidRootPart.Position).Magnitude
if Magnitude < huge then
huge = Magnitude
inst2 = inst
end
end
end
end
if inst2 then
return inst2
end
for _,child in ipairs(Workspace:GetChildren())do
if string.match(child.Name,"^CLIENT_BALL_")then
local position2 = GetPosition(child)
if position2 then
local Magnitude2 =(position2 - HumanoidRootPart.Position).Magnitude
if Magnitude2 < huge then
huge = Magnitude2
inst2 = child
end
end
end
end
return inst2
end
local function GetNet()
local Map = Workspace:FindFirstChild("Map")
if not Map then
return nil
end
local BallCollideOnly = Map:FindFirstChild("BallCollideOnly")
if not BallCollideOnly then
return nil
end
return BallCollideOnly:FindFirstChild("Net")
end
local inst ={Ball = nil,Position = nil,Time = nil,Velocity = Vector3.zero}
TrackConn(RunService.Heartbeat,function()
if not genv.AutoCornerV25Enabled then
if inst.Ball then
inst.Ball,inst.Position,inst.Time,inst.Velocity = nil,nil,nil,Vector3.zero
end
return
end
local rootPart = GetRootPart()
if not rootPart then
inst.Ball = nil
inst.Position = nil
inst.Time = nil
inst.Velocity = Vector3.zero
return
end
local position = GetPosition(rootPart)
if not position then
return
end
local now = os.clock()
if inst.Ball ~= rootPart then
inst.Ball = rootPart
inst.Position = position
inst.Time = now
inst.Velocity = Vector3.zero
return
end
if inst.Position and inst.Time then
local delta = now - inst.Time
if delta > 0.001 and delta < 0.08 then
local ratio =(position - inst.Position)/ delta
if ratio.Magnitude < 450 then
inst.Velocity = inst.Velocity:Lerp(ratio,0.45)
end
end
end
inst.Position = position
inst.Time = now
end)
local function GetPendingVelocity(AutoCornerV25PendingBall)
if inst.Ball == AutoCornerV25PendingBall then
return inst.Velocity
end
return Vector3.zero
end
local function GetFloorY(vec)
local surfaceY = nil
pcall(function()
surfaceY = Physics.calculateFloorHeight(vec)
end)
if not IsFiniteNumber(surfaceY)then
local surfaceY2 = Geo.SurfaceY(tbl.Current())
local Map = Workspace:FindFirstChild("Map")
local Court = Map and Map:FindFirstChild("Court")
if surfaceY2 then
surfaceY = surfaceY2
elseif Court and Court:IsA("BasePart")then
surfaceY = Court.Position.Y + Court.Size.Y * 0.5
else
surfaceY = tbl2.TargetPosition and tbl2.TargetPosition.Y or 0
end
end
return vec.Y - surfaceY,surfaceY
end
local Geometry ={}
function Geometry.Bounds()
local current = tbl.Current()
if not current then
return nil
end
local tbl3 ={
Frame = current.CFrame,
MinX = math.huge,
MaxX = -math.huge,
MinZ = math.huge,
MaxZ = -math.huge,
}
for _,def in ipairs(tbl2.Defs)do
local value,value2 = tbl.CornerLocal(current,def)
tbl3.MinX,tbl3.MaxX = math.min(tbl3.MinX,value),math.max(tbl3.MaxX,value)
tbl3.MinZ,tbl3.MaxZ = math.min(tbl3.MinZ,value2),math.max(tbl3.MaxZ,value2)
end
if tbl3.MaxX - tbl3.MinX < 0.1 or tbl3.MaxZ - tbl3.MinZ < 0.1 then
return nil
end
return tbl3
end
function Geometry.Aim(Position,_)
return Position
end
function Geometry.Inside(CourtBounds,PredictedLandingPosition,arg3)
if not CourtBounds then
return nil
end
local localPoint = CourtBounds.Frame:PointToObjectSpace(PredictedLandingPosition)
local value = arg3 or 0
return localPoint.X >= CourtBounds.MinX + value - 1e-06 and localPoint.X <= CourtBounds.MaxX - value + 1e-06 and localPoint.Z >= CourtBounds.MinZ + value - 1e-06 and localPoint.Z <= CourtBounds.MaxZ - value + 1e-06
end
function Geometry.RangeInterval(arg)
local CourtBounds = arg.CourtBounds
if not CourtBounds or not arg.BallPosition then
return nil
end
local Vector32 = Vector3.new(arg.BallPosition.X,arg.GroundY,arg.BallPosition.Z)
local localPoint = CourtBounds.Frame:PointToObjectSpace(Vector32)
local delta = CourtBounds.Frame:PointToObjectSpace(Vector32 + arg.Direction)- localPoint
local value,huge = 0,math.huge
local function SlabOverlap(X,X2,value2,delta)
if math.abs(X2)< 1e-08 then
return X >= value2 and X <= delta
end
local value3,value4 =(value2 - X)/ X2,(delta - X)/ X2
if value3 > value4 then
value3,value4 = value4,value3
end
value,huge = math.max(value,value3),math.min(huge,value4)
return value <= huge
end
if not SlabOverlap(localPoint.X,delta.X,CourtBounds.MinX + 0.05,CourtBounds.MaxX - 0.05)or not SlabOverlap(localPoint.Z,delta.Z,CourtBounds.MinZ + 0.05,CourtBounds.MaxZ - 0.05)then
return 0,-1
end
return value,huge
end
tbl2.Geometry = Geometry
local function OriginalContext(arg1,arg2)
local Character = LocalPlayer.Character
