if not HumanoidRootPart then
return nil
end
local position = GetPosition(AutoCornerV25PendingBall)
if not position then
return nil
end
if type(arg1)== "table" then
pcall(function()
local Position = arg1.State.Ball.Position
if typeof(Position)== "Vector3" and(Position - position).Magnitude < 14 then
position = Position
end
end)
end
local AutoCornerV25PendingTarget = genv.AutoCornerV25PendingTarget
local Position = AutoCornerV25PendingTarget and AutoCornerV25PendingTarget.Position or tbl2.TargetPosition
if not Position then
return nil
end
local bounds = Geometry.Bounds()
local aim = Geometry.Aim(Position,bounds)
local Vector32 = Vector3.new(aim.X - position.X,0,aim.Z - position.Z)
if Vector32.Magnitude < 0.001 then
return nil
end
local Vector33 = Vector3.new(Position.X - position.X,0,Position.Z - position.Z)
if Vector33.Magnitude < 0.001 then
return nil
end
local Unit = Vector32.Unit
if not arg2 and math.abs(Unit.Z)< 0.0001 then
return nil
end
local height,groundY = GetFloorY(position)
local Position2 = HumanoidRootPart.Position
local delta = Position2.Y - groundY
local delta2 = position.Y - Position2.Y
local characterVY = 0
pcall(function()
characterVY = HumanoidRootPart.AssemblyLinearVelocity.Y
end)
local pendingVelocity = GetPendingVelocity(AutoCornerV25PendingBall)
if type(arg1)== "table" then
pcall(function()
local Velocity = arg1.State.Ball.Velocity
if typeof(Velocity)== "Vector3" and Velocity.Magnitude < 450 then
pendingVelocity = Velocity
end
end)
end
local dot = Flatten(pendingVelocity):Dot(Unit)
