local function GetUnit(arg)
return Vector3.new(arg.Direction.X,0,arg.Direction.Z).Unit
end
local function TiltFromDirection(vec,vec2)
if not Utility then
return nil,nil
end
local Vector32 = Vector3.new(vec.X,0,vec.Z)
if Vector32.Magnitude < 0.001 or vec2.Magnitude < 0.001 then
return nil,nil
end
local lookAt = CFrame.lookAt(Vector3.zero,Vector32.Unit,Vector3.yAxis)
local dot = lookAt.RightVector:Dot(vec2.Unit)
local normalizeDotToTilt = nil
pcall(function()
if type(Utility.normalizeDotToTilt)== "function" then
normalizeDotToTilt = Utility.normalizeDotToTilt(dot)
end
end)
return dot,normalizeDotToTilt
end
local function TiltToSlope(raw)
local value = math.abs(raw)
if value < value8 then
return 0
end
value = Clamp(value,0,0.97)
return value / math.sqrt(math.max(1 - value * value,0.0025))
end
local function ComputeTiltDirection(arg1,raw)
raw = math.min(tonumber(raw)or 0,0)
if math.abs(raw)< value8 then
return Vector3.new(0,1,0),0,0
end
local tiltToSlope = TiltToSlope(raw)
local vec
if raw < 0 then
vec = -arg1.Direction
else
vec = arg1.Direction
end
return Vector3.new(vec.X * tiltToSlope,1,vec.Z * tiltToSlope),raw,tiltToSlope
end
local function ClassifyTilt(value)
if value < -value8 then
return "LONG"
end
if value > value8 then
return "SHORT"
end
return "NEUTRAL"
end
local function ComputeLaunchVelocity(arg1,ratio,value)
local chargePowerMultiplier = ChargePowerMultiplier(ratio)
local delta = 1 - value * value11 * arg1.TiltPower
delta = Clamp(delta,0.72,1.3)
local value2 = value4 * arg1.SpikePower * chargePowerMultiplier * delta + arg1.IncomingAlong * value12
local value3 = 1 + value * 0.4 * arg1.TiltPower
value3 = Clamp(value3,0.3,1.7)
local v = -value4 * value3 + arg1.IncomingVY * value13
return math.max(value2,1),v,value3
end
local function SolveFlightTime(value,value2)
local value4 = value2 * value2 + 2 * value3 * value
if value4 < 0 then
return nil
end
local ratio =(value2 + math.sqrt(value4))/ value3
if ratio <= 0 then
return nil
end
return ratio
end
local function BallisticDistance(Height,baseVH,baseVY)
local value = SolveFlightTime(Height,baseVY)
if not value then
return nil,nil
end
return baseVH * value,value
end
local function HeightAtDistance(arg1,value,value2,value4)
if value <= 0 then
return -math.huge,nil
end
local ratio = value4 / value
local delta = arg1.Height + value2 * ratio - 0.5 * value3 * ratio * ratio
return delta,ratio
end
local function BuildModelKey(arg1,arg2)
