local v = CharacterHeight > 5.5 and "AIR" or "FLOOR"
return string.format("V25|%s|%s|S%.4f|T%.4f|%s|%s",arg1.Style,normalizeSpecials and "NORMALIZED" or "NATIVE",arg1.SpikePower,arg1.TiltPower,ClassifyTilt(arg2),v)
end
