end
local function SampleDistance(arg1,value,value2,arg4)
return math.abs(value - arg4.Charge)/ 0.18 + math.abs(value2 - arg4.TiltDot)/ 0.25 + math.abs(arg1.Height - arg4.Height)/ 3 + math.abs(arg1.IncomingVY -(arg4.IncomingVY or 0))/ 24 + math.abs(arg1.IncomingAlong -(arg4.IncomingAlong or 0))/ 50 + math.abs(arg1.BallAboveCharacter -(arg4.BallAboveCharacter or arg1.BallAboveCharacter))/ 6 + math.abs(arg1.CharacterVY -(arg4.CharacterVY or arg1.CharacterVY))/ 20
end
local function Median(list)
if #list == 0 then
return 0
end
table.sort(list)
local value = #list
if value % 2 == 1 then
return list[(value + 1)/ 2]
end
return(list[value / 2] + list[value / 2 + 1])/ 2
end
local function NoCorrection(arg1,_,arg3)
return 0,0,0,0,math.huge,BuildModelKey(arg1,arg3),0,0
end
