local function RikuVelocityCorrection(arg1,_,_)
if string.lower(arg1.Style or "")~= "riku" then
return nil,0
end
local list ={}
for _,value in ipairs(list5)do
local d = math.abs(arg1.Height - value.H)/ 3 + math.abs(arg1.BallAboveCharacter - value.A)/ 3 + math.abs(arg1.CharacterVY - value.CVY)/ 10 + math.abs(arg1.IncomingVY - value.IVY)/ 10 + math.abs(arg1.TargetDistance - value.T)/ 12 + math.abs(arg1.NetPath - value.N)/ 10
table.insert(list,{D = d,R = value.R})
end
table.sort(list,function(a,b)
return a.D < b.D
end)
while #list > 5 do
table.remove(list)
end
if #list == 0 then
return 0,0
end
local list2 ={}
for _,v in ipairs(list)do
table.insert(list2,v.R)
end
local median = Median(list2)
local value3 = 0
local value4 = 0
for _,value2 in ipairs(list)do
local clamp = Clamp(value2.R,median - 7,median + 7)
local ratio = 1 /(0.35 + value2.D)^ 2
value3 = value3 + clamp * ratio
value4 = value4 + ratio
end
local v2 = value4 > 0 and value3 / value4 or median
v2 = Clamp(v2,-7,18)
local D = list[1].D
local clamp2 = Clamp(0.88 /(1 + D * 0.32),0.35,0.88)
return v2,clamp2
end
