if arg1.BallAboveCharacter >= 7 and value <= 0.58 then
value7 = math.min(value7,1.75)
end
local D = list[1].D
local clamp2 = Clamp(0.95 /(1 + D * 0.24),0.48,0.95)
return value7,clamp2,D
end
