local function RintaroCorrection(arg1,value,value2)
local kind = string.lower(arg1.Style or "")
if kind ~= "rintaro" and kind ~= "sanju" then
return 0,0,math.huge,0
end
local list ={}
for _,v in ipairs(list7)do
local d = math.abs(arg1.Height - v.H)/ 0.9 + math.abs(arg1.BallAboveCharacter - v.A)/ 5 + math.abs(arg1.CharacterVY - v.CVY)/ 17 + math.abs(arg1.IncomingVY - v.IVY)/ 18 + math.abs(arg1.TargetDistance - v.T)/ 8 + math.abs(arg1.NetPath - v.N)/ 12 + math.abs(value - v.C)/ 0.24 + math.abs(value2 - v.D)/ 0.18
table.insert(list,{D = d,R = v.R})
end
table.sort(list,function(a,b)
return a.D < b.D
end)
while #list > 3 do
table.remove(list)
end
if #list == 0 then
return 0,0,math.huge,0
end
local list2 ={}
for _,value3 in ipairs(list)do
table.insert(list2,value3.R)
end
local median = Median(list2)
local value5 = 0
local value6 = 0
for _,value4 in ipairs(list)do
local clamp = Clamp(value4.R,median - 4.5,median + 4.5)
local ratio = 1 /(0.25 + value4.D)^ 1.72
value5 = value5 + clamp * ratio
value6 = value6 + ratio
end
local value7 = value6 > 0 and value5 / value6 or median
value7 = Clamp(value7,-7,9)
local D = list[1].D
local clamp2 = Clamp(1.08 - D * 0.11,0.22,0.96)
local scaled = clamp2 * 0.55
if value7 < 0 then
scaled = scaled * 0.72
end
local scaled2 = value7 * scaled
return value7,clamp2,D,scaled2
end
