local function InsertSorted(list,arg2,value)
local item = #list + 1
for i = 1,#list do
if arg2.D < list[i].D then
item = i
break
end
end
table.insert(list,item,arg2)
if #list > value then
table.remove(list)
end
end
local function RintaroDistanceCorrection(arg)
local kind = string.lower(arg.Style or "")
if kind ~= "rintaro" and kind ~= "sanju" then
return 0,0,math.huge,0
end
local list ={}
for _,value in ipairs(list8)do
local d = math.abs(arg.Height - value.H)/ 1 + math.abs(arg.TargetDistance - value.T)/ 8 + math.abs(arg.BallAboveCharacter - value.A)/ 8 + math.abs(arg.CharacterVY - value.CVY)/ 18
InsertSorted(list,{D = d,R = value.R},5)
end
if #list == 0 then
return 0,0,math.huge,0
end
local list2 ={}
for _,v in ipairs(list)do
table.insert(list2,v.R)
end
local median = Median(list2)
local value3 = 0
local value4 = 0
for _,value2 in ipairs(list)do
local clamp = Clamp(value2.R,median - 5,median + 5)
local ratio = 1 /(0.3 + value2.D)^ 1.7
value3 = value3 + clamp * ratio
value4 = value4 + ratio
end
local value5 = value4 > 0 and value3 / value4 or median
value5 = Clamp(value5,-7.5,8.5)
local D = list[1].D
local clamp2 = Clamp(1.05 - D * 0.1,0.3,0.95)
local clamp3 = clamp2
if value5 < 0 then
clamp3 = clamp3 * 0.82
end
return value5,clamp2,D,value5 * clamp3
end
local function PredictWithCorrections(arg1,ratio,arg3)
local baseVH,baseVY,tiltFactor = ComputeLaunchVelocity(arg1,ratio,arg3)
local deltaVH,deltaVY,velocityConfidence,trajectoryCorrection,nearest,modelKey,localSamples,landingConfidence = NoCorrection(arg1,ratio,arg3,baseVH,baseVY)
local vH = math.max(baseVH + deltaVH,1)
local vY = baseVY + deltaVY
local ballisticDistance,flightTime = BallisticDistance(arg1.Height,vH,vY)
if not ballisticDistance then
return nil
end
local specialCharge = GetSpecialCharge(arg1)
local delta = 1 - Clamp(math.max(velocityConfidence,landingConfidence),0,1)
local scaled = specialCharge * delta
local heightDistancePrior,heightDistancePriorConfidence = RikuVelocityCorrection(arg1,ratio,arg3)
local heightDistancePriorWeight = 0
if string.lower(arg1.Style or "")== "riku" then
trajectoryCorrection = Clamp(trajectoryCorrection,-6,16)
end
if IsFiniteNumber(heightDistancePrior)then
heightDistancePriorWeight = Clamp(heightDistancePriorConfidence *(1 - 0.65 * landingConfidence),0.2,0.78)
trajectoryCorrection = trajectoryCorrection *(1 - heightDistancePriorWeight)+ heightDistancePrior * heightDistancePriorWeight
end
local predictedDistance = ballisticDistance + scaled + trajectoryCorrection
local rikuPredictionBias = 0
local rikuPredictionBiasConfidence = 0
local huge = math.huge
local rikuPredictionBiasApplied = 0
if string.lower(arg1.Style or "")== "riku" then
rikuPredictionBias,rikuPredictionBiasConfidence,huge = RikuBiasCorrection(arg1,ratio,arg3)
rikuPredictionBiasApplied = rikuPredictionBias * rikuPredictionBiasConfidence
predictedDistance = predictedDistance + rikuPredictionBiasApplied
end
local styleResidualBias,styleResidualBiasConfidence,styleResidualBiasNearest,styleResidualBiasModel,styleResidualBiasApplied = GetStyleSamples(arg1,ratio,arg3)
predictedDistance = predictedDistance + styleResidualBiasApplied
local sanjuObservedResidual = 0
local sanjuObservedResidualConfidence = 0
local huge2 = math.huge
local sanjuObservedResidualApplied = 0
sanjuObservedResidual,sanjuObservedResidualConfidence,huge2,sanjuObservedResidualApplied = RintaroCorrection(arg1,ratio,arg3)
predictedDistance = predictedDistance + sanjuObservedResidualApplied
local sanjuHeightBias = 0
local sanjuHeightBiasConfidence = 0
local huge3 = math.huge
local sanjuHeightBiasApplied = 0
sanjuHeightBias,sanjuHeightBiasConfidence,huge3,sanjuHeightBiasApplied = RintaroDistanceCorrection(arg1)
predictedDistance = predictedDistance + sanjuHeightBiasApplied
local value
if arg1.Advanced then
value = 2.2
else
value = 0.85
end
if arg1.StyleInfo.IsKijo then
value = 3.2
elseif arg1.StyleInfo.IsTimeskip then
value = 1.45
end
local scaled2 = value *(1 - 0.7 * math.max(velocityConfidence,landingConfidence))
if nearest ~= math.huge then
scaled2 = scaled2 + math.max(nearest - 1,0)* 0.2
end
scaled2 = Clamp(scaled2,0.55,4.5)
return{
BaseVH = baseVH,
BaseVY = baseVY,
DeltaVH = deltaVH,
DeltaVY = deltaVY,
VH = vH,
VY = vY,
TiltFactor = tiltFactor,
BallisticDistance = ballisticDistance,
RangePrior = scaled,
TrajectoryCorrection = trajectoryCorrection,
HeightDistancePrior = heightDistancePrior,
HeightDistancePriorConfidence = heightDistancePriorConfidence,
HeightDistancePriorWeight = heightDistancePriorWeight,
RikuPredictionBias = rikuPredictionBias,
RikuPredictionBiasConfidence = rikuPredictionBiasConfidence,
RikuPredictionBiasNearest = huge,
RikuPredictionBiasApplied = rikuPredictionBiasApplied,
StyleResidualBias = styleResidualBias,
StyleResidualBiasConfidence = styleResidualBiasConfidence,
StyleResidualBiasNearest = styleResidualBiasNearest,
StyleResidualBiasModel = styleResidualBiasModel,
StyleResidualBiasApplied = styleResidualBiasApplied,
SanjuObservedResidual = sanjuObservedResidual,
SanjuObservedResidualConfidence = sanjuObservedResidualConfidence,
SanjuObservedResidualNearest = huge2,
SanjuObservedResidualApplied = sanjuObservedResidualApplied,
SanjuHeightBias = sanjuHeightBias,
SanjuHeightBiasConfidence = sanjuHeightBiasConfidence,
SanjuHeightBiasNearest = huge3,
SanjuHeightBiasApplied = sanjuHeightBiasApplied,
PredictedDistance = predictedDistance,
FlightTime = flightTime,
VelocityConfidence = velocityConfidence,
LandingConfidence = landingConfidence,
Uncertainty = scaled2,
Nearest = nearest,
ModelKey = modelKey,
LocalSamples = localSamples,
}
end
