local function EvalLinearModel(GLOBAL,arg2,ratio,value)
local value2 = GLOBAL.UseChargePower and ChargePowerMultiplier(ratio)or ratio
return GLOBAL.Intercept + GLOBAL.H * arg2.Height + GLOBAL.IVY * arg2.IncomingVY + GLOBAL.N * arg2.NetPath + GLOBAL.T * arg2.TargetDistance + GLOBAL.C * value2 + GLOBAL.D * value
end
local function BlendModels(GLOBAL,GLOBAL2,ratio,arg4,ratio2,arg6)
local evalLinearModel = EvalLinearModel(GLOBAL,arg4,ratio2,arg6)
local evalLinearModel2 = EvalLinearModel(GLOBAL2,arg4,ratio2,arg6)
return Lerp(evalLinearModel,evalLinearModel2,ratio),Lerp(GLOBAL.Uncertainty,GLOBAL2.Uncertainty,ratio),GLOBAL.Name .. "->" .. GLOBAL2.Name,math.floor(Lerp(GLOBAL.Samples,GLOBAL2.Samples,ratio)+ 0.5)
end
local function HeightModelDistance(arg1,ratio,arg3)
local Height = arg1.Height
if Height <= 14.5 then
local GLOBAL = tbl5.GLOBAL
return EvalLinearModel(GLOBAL,arg1,ratio,arg3),GLOBAL.Uncertainty,GLOBAL.Name,GLOBAL.Samples
end
if Height < 15.5 then
return BlendModels(tbl5.GLOBAL,tbl5.MID,Height - 14.5,arg1,ratio,arg3)
end
if Height <= 18.5 then
local MID = tbl5.MID
return EvalLinearModel(MID,arg1,ratio,arg3),MID.Uncertainty,MID.Name,MID.Samples
end
if Height < 19.5 then
return BlendModels(tbl5.MID,tbl5.HIGH,Height - 18.5,arg1,ratio,arg3)
end
local HIGH = tbl5.HIGH
return EvalLinearModel(HIGH,arg1,ratio,arg3),HIGH.Uncertainty,HIGH.Name,HIGH.Samples
end
local function KijoResidual(arg1,heightModel)
local TargetDistance = arg1.TargetDistance
local IncomingVY = arg1.IncomingVY
local value
if string.find(heightModel,"HIGH",1,true)then
value = -5.975399742451817 + 0.03617341190508409 * TargetDistance + 0.06034451840919459 * IncomingVY
value = Clamp(value,-4.35,-1.4)
elseif heightModel == "MID" then
value = -3.1
elseif heightModel == "GLOBAL->MID" then
value = -3.35
elseif heightModel == "MID->HIGH" then
value = -3.35
elseif heightModel == "GLOBAL" then
value = -2.35
else
value = -2.8
end
if TargetDistance > 84 then
local clamp = Clamp((TargetDistance - 84)/ 12,0,1)
value = Lerp(value,math.max(value,-1.75),clamp)
end
return value
end
local function PredictKijo(arg1,ratio,arg3)
local baseVH,baseVY,tiltFactor = ComputeLaunchVelocity(arg1,ratio,arg3)
local ballisticDistance,flightTime = BallisticDistance(arg1.Height,baseVH,baseVY)
if not ballisticDistance then
return nil
end
local heightRawDistance,value,heightModel,localSamples = HeightModelDistance(arg1,ratio,arg3)
local kijoResidual = KijoResidual(arg1,heightModel)
local predictedDistance = heightRawDistance + kijoResidual
local value2 = 0
if arg1.Height >= 19 then
value2 = math.max(0,0.55 - ratio)* 0.65
elseif arg1.Height >= 15 then
value2 = math.max(0,0.6 - ratio)* 0.9
else
value2 = math.max(0,0.65 - ratio)* 1.1
end
local clamp = Clamp(value + value2,0.85,2.8)
return{
BaseVH = baseVH,
BaseVY = baseVY,
DeltaVH = 0,
DeltaVY = 0,
VH = baseVH,
VY = baseVY,
TiltFactor = tiltFactor,
BallisticDistance = ballisticDistance,
RangePrior = predictedDistance - ballisticDistance,
TrajectoryCorrection = 0,
PredictedDistance = predictedDistance,
FlightTime = flightTime,
VelocityConfidence = 0,
LandingConfidence = 0.95,
Uncertainty = clamp,
Nearest = 0,
ModelKey = "Kijo2|HEIGHT_" .. heightModel,
LocalSamples = localSamples,
HeightModel = heightModel,
HeightRawDistance = heightRawDistance,
HeightCorrectedDistance = predictedDistance,
KijoSystematicResidual = kijoResidual,
}
end
local function NetZCurve(RawNetZ)
local value = RawNetZ
if value <= 10 then
return Lerp(-8,0.5,Clamp(value / 10,0,1))
elseif value <= 20 then
return Lerp(0.5,10,(value - 10)/ 10)
elseif value <= 30 then
return Lerp(10,26,(value - 20)/ 10)
elseif value <= 40 then
return Lerp(26,39,(value - 30)/ 10)
elseif value <= 50 then
return Lerp(39,58,(value - 40)/ 10)
else
return Lerp(58,84,Clamp((value - 50)/ 10,0,1))
end
end
local function TimeskipTiltBase(arg)
local RawNetZ = arg.RawNetZ
local value
if RawNetZ <= 18 then
value = -0.95
elseif RawNetZ <= 28 then
value = Lerp(-0.95,-0.88,(RawNetZ - 18)/ 10)
elseif RawNetZ <= 38 then
value = Lerp(-0.88,-0.78,(RawNetZ - 28)/ 10)
elseif RawNetZ <= 48 then
value = Lerp(-0.78,-0.68,(RawNetZ - 38)/ 10)
else
value = Lerp(-0.68,-0.57,Clamp((RawNetZ - 48)/ 12,0,1))
end
if arg.Height > 20 then
value = value + Clamp((arg.Height - 20)* 0.018,0,0.06)
elseif arg.Height < 15 then
value = value + Clamp((15 - arg.Height)* 0.012,0,0.045)
end
return Clamp(value,v25,v26)
end
local function TimeskipResidual(arg1,value,_)
local RawNetZ = arg1.RawNetZ
if RawNetZ < 20 then
local ratio =(arg1.Height - 18)/ 4
local ratio2 =(RawNetZ - 12)/ 7
local ratio3 =(value - 0.8)/ 0.2
local ratio4 =(arg1.IncomingVY - 14)/ 10
local v = 3.4 + 5 * ratio2 - 1.4 * ratio3 + 1.5 * ratio + 1 * ratio4
return Clamp(v,-16,14)
end
local netZCurve = NetZCurve(RawNetZ)
local Height = arg1.Height
if RawNetZ < 30 then
netZCurve = netZCurve + Clamp((Height - 18.5)* 0.9,-5,5)
else
netZCurve = netZCurve + math.min(4,math.abs(Height - 18.5)* 0.65)
end
if RawNetZ >= 45 and Height < 16 then
netZCurve = netZCurve +(16 - Height)* 2.5
end
if IsFiniteNumber(arg1.CharacterHeight)then
if arg1.CharacterHeight < 14 then
netZCurve = netZCurve + 1
end
if arg1.BallAboveCharacter and arg1.BallAboveCharacter > 7 then
netZCurve = netZCurve + 0.8
end
end
return Clamp(netZCurve,-16,92)
end
local function TimeskipSafetyBuffer(arg)
local RawNetZ = arg.RawNetZ
local value = 1.25
if RawNetZ >= 30 then
value = 1.75
end
if RawNetZ >= 40 then
value = 2.25
end
if RawNetZ >= 50 then
value = 2.75
end
if arg.Height < 14 or arg.Height > 22 then
value = value + 0.55
end
return value
end
local function PredictTimeskipLong(arg1,ratio)
local baseVH,baseVY,tiltFactor = ComputeLaunchVelocity(arg1,ratio,0)
local ballisticDistance,flightTime = BallisticDistance(arg1.Height,baseVH,baseVY)
if not ballisticDistance then
return nil
