log.NativeOriginSource = snapshot.Context.OriginSource
log.NativeNetAngle = math.abs(snapshot.Context.Direction:Dot(snapshot.Context.NetNormal))
log.NativeLaunchModelSource = snapshot.LaunchModelSource
log.NativeSendObserverBound = AutoCornerV30Native.InteractBound == true
log.NativeAttemptIndex = tbl.Attempt and tbl.Attempt.Index
AutoCornerV30Native.Scopes[Main] = tbl
data.ForceInteractBall = AutoCornerV30Native.ClosestBound == true
local ok,result = pcall(fn)
AutoCornerV30Native.Scopes[Main] = scope
if not ok then
error(result,0)
end
if not log.NativeSentClock and tbl.Attempt then
tbl.Attempt.Status = AutoCornerV30Native.InteractBound and "NO_NATIVE_CONTACT" or "NATIVE_SEND_UNOBSERVED"
tbl.Attempt.Reason = log.NativeSendRejected or log.NativeLocalRejection or "NO_OBSERVED_NATIVE_INTERACT"
end
return result
end
function AutoCornerV30Native.Stop()
if AutoCornerV30Native.Stopped then
return
end
AutoCornerV30Native.Stopped = true
for i = #AutoCornerV30Native.Hooks,1,-1 do
local hook = AutoCornerV30Native.Hooks[i]
pcall(function()
if hook.Owner[hook.Key] == hook.Wrapper then
hook.Owner[hook.Key] = hook.Original
end
end)
end
end
