local function SafePredict(arg1,ratio,raw)
local ok,result = pcall(OriginalPredict,arg1,ratio,raw)
if ok and result then
return result
end
local baseVH,baseVY,tiltFactor = ComputeLaunchVelocity(arg1,ratio,raw)
local ballisticDistance,flightTime = BallisticDistance(arg1.Height,baseVH,baseVY)
if not ballisticDistance then
return nil
end
return{
BaseVH = baseVH,
BaseVY = baseVY,
VH = baseVH,
VY = baseVY,
TiltFactor = tiltFactor,
BallisticDistance = ballisticDistance,
PredictedDistance = ballisticDistance,
PredictionBaseDistance = ballisticDistance,
FlightTime = flightTime,
Uncertainty = 2,
CalibrationCount = 0,
CalibrationOutsideData = true,
}
end
local function PowerFactor(arg)
return Clamp((math.max(arg.SpikePower or 1.15,0.05)/ 1.15)^ 0.9,0.7,1.45)
end
local function EffectiveTilt(arg1,lerp)
if math.abs(lerp)< value8 then
return 0
end
return Clamp(lerp * math.max(arg1.TiltPower or 1,0.05),-0.95,-value8)
end
local function RoninZeroModel(arg)
return tbl9.Intercept + tbl9.H * arg.Height + tbl9.N * arg.NetPath + tbl9.IVY *(arg.IncomingVY or 0)+ tbl9.CVY *(arg.CharacterVY or 0)
end
local function RoninTiltModel(arg)
return tbl10.Intercept + tbl10.H * arg.Height + tbl10.N * arg.NetPath + tbl10.IVY *(arg.IncomingVY or 0)+ tbl10.CVY *(arg.CharacterVY or 0)
end
local function RoninPredict(arg1,raw,lerp)
local styleBias = GetStyleBias(arg1)
local powerFactor = PowerFactor(arg1)
if math.abs(lerp)< value8 then
local value = RoninZeroModel(arg1)+ tbl9.Q * raw
return value * powerFactor +(styleBias.Zero or 0),0.72,"ZERO_TILT"
end
local effectiveTilt = EffectiveTilt(arg1,lerp)
local value2 = RoninTiltModel(arg1)+ tbl10.Q * raw + tbl10.D * effectiveTilt
return value2 * powerFactor +(styleBias.Back or 0),0.72,"NEGATIVE_TILT"
end
local function FallbackPredict(arg1,raw,lerp)
local Height = arg1.Height
local NetPath = arg1.NetPath
local IncomingVY = arg1.IncomingVY or 0
local CharacterVY = arg1.CharacterVY or 0
local value
local v
if math.abs(lerp)< value8 then
value = tbl11.VH0 + tbl11.VHH * Height + tbl11.VHN * NetPath + tbl11.VHIVY * IncomingVY + tbl11.VHCVY * CharacterVY + tbl11.VHQ * raw
v = tbl11.VY0 + tbl11.VYH * Height + tbl11.VYN * NetPath + tbl11.VYIVY * IncomingVY + tbl11.VYCVY * CharacterVY + tbl11.VYQ * raw
else
local effectiveTilt = EffectiveTilt(arg1,lerp)
value = tbl12.VH0 + tbl12.VHH * Height + tbl12.VHN * NetPath + tbl12.VHIVY * IncomingVY + tbl12.VHCVY * CharacterVY + tbl12.VHQ * raw + tbl12.VHD * effectiveTilt
v = tbl12.VY0 + tbl12.VYH * Height + tbl12.VYN * NetPath + tbl12.VYIVY * IncomingVY + tbl12.VYCVY * CharacterVY + tbl12.VYQ * raw + tbl12.VYD * effectiveTilt
end
value = value * PowerFactor(arg1)
return value,v
end
local function PredictForCharge(arg1,raw,raw2)
raw = Clamp(tonumber(raw)or tbl7.MinCharge,tbl7.MinCharge,tbl7.MaxCharge)
raw2 = math.min(tonumber(raw2)or 0,0)
local v = SafePredict(arg1,raw,raw2)
if not v then
return nil
end
local family = tbl6.Family(arg1.Style)
local v2 = ShallowCopy(v)
if family == "Ronin" then
local predictedDistance,uncertainty,empiricalSurface = RoninPredict(arg1,raw,raw2)
if not IsFiniteNumber(predictedDistance)or predictedDistance <= 0 then
return nil
end
local baseVH,baseVY = FallbackPredict(arg1,raw,raw2)
v2.BaseVH = baseVH
v2.BaseVY = baseVY
v2.VH = baseVH
v2.VY = baseVY
v2.PredictedDistance = predictedDistance
v2.PredictionBaseDistance = predictedDistance
v2.EmpiricalRange = predictedDistance
v2.EmpiricalSurface = empiricalSurface
v2.Uncertainty = uncertainty
v2.CalibrationMode = "V36_RONIN_CENTER_MODEL"
v2.LaunchModelSource = "V36_EMPIRICAL_CENTER_MODEL"
return v2
end
v2.LaunchModelSource = "V36_GENERIC_DYNAMIC"
v2.EmpiricalSurface = math.abs(raw2)< value8 and "ZERO_TILT" or "NEGATIVE_TILT"
return v2
end
local function EvaluateShot(arg1,charge,raw)
charge = Clamp(tonumber(charge)or tbl7.MinCharge,tbl7.MinCharge,tbl7.MaxCharge)
raw = math.min(tonumber(raw)or 0,0)
local tiltDirection,tiltDot,tiltStrength = ComputeTiltDirection(arg1,raw)
local predictForCharge = PredictForCharge(arg1,charge,tiltDot)
if not predictForCharge or not IsFiniteNumber(predictForCharge.PredictedDistance)then
return nil
end
local netHeight = AutoCornerV30Native.NetHeight(arg1,predictForCharge.VH,predictForCharge.VY)
local predictedNetClearance = netHeight and netHeight - arg1.NetTopHeight or -math.huge
local cframe ={}
for key,value in pairs(predictForCharge)do
cframe[key] = value
end
cframe.Charge = charge
cframe.TiltDot = tiltDot
cframe.TiltStrength = tiltStrength
cframe.TiltDirection = tiltDirection
cframe.LookVector = GetUnit(arg1)
cframe.Branch = "DYNAMIC_CENTER"
cframe.PredictedError = predictForCharge.PredictedDistance - arg1.TargetDistance
cframe.CenterSignedError = cframe.PredictedError
cframe.PredictedVH = predictForCharge.VH
cframe.PredictedVY = predictForCharge.VY
cframe.PredictedNetClearance = predictedNetClearance
cframe.BallisticNetClearance = predictedNetClearance
cframe.NetSafe = IsFiniteNumber(predictedNetClearance)and predictedNetClearance >= tbl7.MinClearance
local v,contactReason = tbl6.ContactSafe(arg1)
cframe.ContactSafe = v ~= false
cframe.ContactReason = contactReason
local vec = arg1.BallPosition + arg1.Direction * predictForCharge.PredictedDistance
cframe.PredictedLandingPosition = Vector3.new(vec.X,arg1.GroundY,vec.Z)
cframe.MarkerPredictedError = Flatten(cframe.PredictedLandingPosition - arg1.TargetPosition).Magnitude
cframe.TargetMiss = cframe.MarkerPredictedError
cframe.CourtSafe = true
cframe.CourtHardSafe = true
if arg1.CourtBounds then
cframe.CourtSafe = Geometry.Inside(arg1.CourtBounds,cframe.PredictedLandingPosition,-value6)
cframe.CourtHardSafe = Geometry.Inside(arg1.CourtBounds,cframe.PredictedLandingPosition,-value5)
cframe.CourtMinRange,cframe.CourtMaxRange = Geometry.RangeInterval(arg1)
end
local value2 = cframe.NetSafe and 0 or 100
local value3 = cframe.ContactSafe and 0 or 100
local value4 = cframe.CourtHardSafe and 0 or 0.2
cframe.Score = cframe.TargetMiss + value2 + value3 + value4 +(predictForCharge.Uncertainty or 1)* 0.05
cframe.WithinTarget = cframe.NetSafe and cframe.ContactSafe and cframe.TargetMiss <= genv.AutoCornerV25Accuracy
cframe.Reachable = cframe.WithinTarget
cframe.UpperDistance = predictForCharge.PredictedDistance +(predictForCharge.Uncertainty or 1)
cframe.UpperError = cframe.UpperDistance - arg1.TargetDistance
return cframe
end
local function Better(evaluateShot,evaluateShot2)
if not evaluateShot then
return false
end
if not evaluateShot2 then
return true
end
if evaluateShot.ContactSafe ~= evaluateShot2.ContactSafe then
return evaluateShot.ContactSafe
end
if evaluateShot.NetSafe ~= evaluateShot2.NetSafe then
return evaluateShot.NetSafe
end
local delta = evaluateShot.TargetMiss - evaluateShot2.TargetMiss
if math.abs(delta)> tbl7.CenterTie then
return evaluateShot.TargetMiss < evaluateShot2.TargetMiss
end
if evaluateShot.CourtHardSafe ~= evaluateShot2.CourtHardSafe then
return evaluateShot.CourtHardSafe
end
if math.abs((evaluateShot.Uncertainty or 9)-(evaluateShot2.Uncertainty or 9))> 0.05 then
return(evaluateShot.Uncertainty or 9)<(evaluateShot2.Uncertainty or 9)
end
if math.abs(math.abs(evaluateShot.TiltDot)- math.abs(evaluateShot2.TiltDot))> 0.0001 then
return math.abs(evaluateShot.TiltDot)< math.abs(evaluateShot2.TiltDot)
end
return evaluateShot.Charge > evaluateShot2.Charge
end
tbl6.Better = Better
local function SolveRonin(arg)
local now = os.clock()
local solverEvaluations = 0
local evaluateShot = nil
local styleBias = GetStyleBias(arg)
local powerFactor = PowerFactor(arg)
local function Evaluate(charge,raw)
solverEvaluations = solverEvaluations + 1
local evaluateShot2 = EvaluateShot(arg,charge,raw)
if Better(evaluateShot2,evaluateShot)then
evaluateShot = evaluateShot2
end
return evaluateShot2
end
local LowHeightMaxCharge = arg.Height < tbl7.LowHeightGuard and tbl7.LowHeightMaxCharge or tbl7.MaxCharge
local roninZeroModel = RoninZeroModel(arg)
local delta = arg.TargetDistance -(styleBias.Zero or 0)
local ratio =(delta / powerFactor - roninZeroModel)/ tbl9.Q
ratio = Clamp(ratio,tbl7.MinCharge,LowHeightMaxCharge)
Evaluate(ratio,0)
Evaluate(tbl7.MinCharge,0)
Evaluate(LowHeightMaxCharge,0)
Evaluate(Clamp(ratio - 0.04,tbl7.MinCharge,LowHeightMaxCharge),0)
Evaluate(Clamp(ratio + 0.04,tbl7.MinCharge,LowHeightMaxCharge),0)
if arg.Height >= tbl7.LowHeightGuard then
local roninTiltModel = RoninTiltModel(arg)
local delta2 = arg.TargetDistance -(styleBias.Back or 0)
local BackTiltSamples = tbl7.BackTiltSamples
for i = 0,BackTiltSamples do
local ratio2 = i / BackTiltSamples
local lerp = Lerp(tbl7.BackTiltStart,tbl7.BackTiltEnd,ratio2)
local effectiveTilt = EffectiveTilt(arg,lerp)
local ratio3 =(delta2 / powerFactor - roninTiltModel - tbl10.D * effectiveTilt)/ tbl10.Q
ratio3 = Clamp(ratio3,tbl7.MinCharge,tbl7.MaxCharge)
Evaluate(ratio3,lerp)
end
Evaluate(tbl7.MinCharge,tbl7.BackTiltStart)
Evaluate(tbl7.MinCharge,tbl7.BackTiltEnd)
Evaluate(tbl7.MaxCharge,tbl7.BackTiltStart)
Evaluate(tbl7.MaxCharge,tbl7.BackTiltEnd)
end
if evaluateShot then
evaluateShot.SolverEvaluations = solverEvaluations
evaluateShot.SolverMilliseconds =(os.clock()- now)* 1000
evaluateShot.SelectionReason = "CENTER_FIRST_ANALYTIC_X"
evaluateShot.Reachable = evaluateShot.WithinTarget
evaluateShot.DynamicBallHeight = arg.Height
evaluateShot.DynamicSpikePower = arg.SpikePower
evaluateShot.DynamicTiltPower = arg.TiltPower
evaluateShot.DynamicTargetDistance = arg.TargetDistance
evaluateShot.DynamicNetPath = arg.NetPath
evaluateShot.DynamicIncomingVY = arg.IncomingVY
evaluateShot.DynamicCharacterVY = arg.CharacterVY
evaluateShot.LowHeightGuard = arg.Height < tbl7.LowHeightGuard
evaluateShot.CenterGap = evaluateShot.TargetMiss > genv.AutoCornerV25Accuracy
genv.AutoCornerV25LastSolution[arg.Style] ={
TargetDistance = arg.TargetDistance,
Height = arg.Height,
SpikePower = arg.SpikePower,
TiltPower = arg.TiltPower,
NetPath = arg.NetPath,
IncomingVY = arg.IncomingVY,
CharacterVY = arg.CharacterVY,
Charge = evaluateShot.Charge,
TiltDot = evaluateShot.TiltDot,
PredictedDistance = evaluateShot.PredictedDistance,
MarkerPredictedError = evaluateShot.MarkerPredictedError,
CenterSignedError = evaluateShot.CenterSignedError,
EmpiricalSurface = evaluateShot.EmpiricalSurface,
SelectionReason = evaluateShot.SelectionReason,
LowHeightGuard = evaluateShot.LowHeightGuard,
}
end
return evaluateShot
end
local function SolveGeneric(arg)
local now = os.clock()
local solverEvaluations = 0
local evaluateShot = nil
local function Evaluate(charge,raw)
solverEvaluations = solverEvaluations + 1
local evaluateShot2 = EvaluateShot(arg,charge,raw)
if Better(evaluateShot2,evaluateShot)then
evaluateShot = evaluateShot2
end
end
local MinCharge = tbl7.MinCharge
while MinCharge <= tbl7.MaxCharge + 1e-06 do
Evaluate(math.min(MinCharge,tbl7.MaxCharge),0)
MinCharge = MinCharge + 0.06
end
if arg.Height >= tbl7.LowHeightGuard then
local BackTiltStart = tbl7.BackTiltStart
while BackTiltStart >= tbl7.BackTiltEnd - 1e-06 do
local MinCharge2 = tbl7.MinCharge
while MinCharge2 <= tbl7.MaxCharge + 1e-06 do
Evaluate(math.min(MinCharge2,tbl7.MaxCharge),BackTiltStart)
MinCharge2 = MinCharge2 + 0.06
end
BackTiltStart = BackTiltStart - 0.06
end
end
if evaluateShot then
evaluateShot.SolverEvaluations = solverEvaluations
evaluateShot.SolverMilliseconds =(os.clock()- now)* 1000
evaluateShot.SelectionReason = "CENTER_FIRST_GENERIC_X"
evaluateShot.Reachable = evaluateShot.WithinTarget
end
return evaluateShot
end
local function SolveShot(originalContext)
if tbl6.Family(originalContext.Style)== "Ronin" then
return SolveRonin(originalContext)
end
return SolveGeneric(originalContext)
end
