if not arg or tostring(arg.Style or "")== "" or not IsFiniteNumber(arg.ActualDistance)or not IsFiniteNumber(arg.PredictedDistance)or not IsFiniteNumber(arg.PredictionResidual)or not IsFiniteNumber(arg.Charge)or arg.Charge < tbl7.MinCharge or not IsFiniteNumber(arg.LateralError)or math.abs(arg.LateralError)> 1.25 or(arg.BallHeight or 0)< tbl7.LowHeightGuard or arg.HitIndicatorCaptured ~= true or arg.BadHit == true or math.abs(arg.PredictionResidual)> 3.25 or arg.ActualDistance < 10 or arg.ActualDistance > 80 then
