local ZeroSamples = v2 and(autoCornerV36Bia.ZeroSamples or 0)or(autoCornerV36Bia.BackSamples or 0)
local v36LearnAlpha = math.max(0.035,0.12 /(1 + ZeroSamples * 0.06))
if v2 then
autoCornerV36Bia.Zero = Clamp((autoCornerV36Bia.Zero or 0)+ clamp * v36LearnAlpha,-1.5,1.5)
autoCornerV36Bia.ZeroSamples = ZeroSamples + 1
else
autoCornerV36Bia.Back = Clamp((autoCornerV36Bia.Back or 0)+ clamp * v36LearnAlpha,-1.5,1.5)
autoCornerV36Bia.BackSamples = ZeroSamples + 1
end
arg.V36Learned = true
arg.V36LearnResidual = clamp
arg.V36LearnAlpha = v36LearnAlpha
arg.V36ZeroBias = autoCornerV36Bia.Zero
arg.V36BackBias = autoCornerV36Bia.Back
end
