local function SaveCharacterRotation(player2)
local Character = player2.Character
if not Character then
return
end
local Pivot = Character:GetPivot()
player.Character,player.Rotation = Character,Pivot.Rotation
player.Tilt = Handlers.Values.TiltDirection
player.GameplayTilt = State.get(LocalPlayer,State.Id.Gameplay,"TiltDirection")
player.Charge = Handlers.States.Charge:get()
player.AppliedTilt,player.AppliedCharge = player2.TiltDirection,player2.Charge
player.AppliedLook = player2.LookVector
Character:PivotTo(CFrame.lookAt(Pivot.Position,Pivot.Position + player2.LookVector,Vector3.yAxis))
Handlers.Values.TiltDirection = player2.TiltDirection
State.set(LocalPlayer,State.Id.Gameplay,"TiltDirection",player2.TiltDirection)
Handlers.States.Charge:set(player2.Charge)
end
local function RestoreCharacterRotation()
local Character = LocalPlayer.Character
if Character == player.Character and Character and player.Rotation then
local Pivot = Character:GetPivot()
if player.AppliedLook and Pivot.LookVector:Dot(player.AppliedLook)> 0.99999 then
Character:PivotTo(CFrame.new(Pivot.Position)* player.Rotation)
end
end
if player.AppliedTilt and Handlers.Values.TiltDirection == player.AppliedTilt then
Handlers.Values.TiltDirection = player.Tilt
end
if player.AppliedTilt and State.get(LocalPlayer,State.Id.Gameplay,"TiltDirection")== player.AppliedTilt then
State.set(LocalPlayer,State.Id.Gameplay,"TiltDirection",player.GameplayTilt)
end
if player.AppliedCharge ~= nil and Handlers.States.Charge:get()== player.AppliedCharge then
Handlers.States.Charge:set(player.Charge)
end
table.clear(player)
end
