local Markers ={}
local Hitboxes ={}
tbl2.Markers = Markers
tbl2.Hitboxes = Hitboxes
local current = nil
local function Update()
local current2 = tbl.Current()
if not current2 then
return false
end
for i,def in ipairs(tbl2.Defs)do
local marker = Markers[i]
if marker and marker.Parent then
local v,v2 = tbl.CornerLocal(current2,def)
marker.CFrame = current2.CFrame * CFrame.new(v,current2.Size.Y / 2 + def.SurfaceOffset,v2)
local hitbox = Hitboxes[i]
if hitbox and hitbox.Parent then
hitbox.CFrame = Geo.HitboxCFrame(marker.CFrame)
end
end
end
if current ~= current2 then
current = current2
pcall(function()
local Map = Workspace:FindFirstChild("Map")
local Court = Map and Map:FindFirstChild("Court")
if not(Court and Court:IsA("BasePart"))then
return
end
local list ={}
for _,def in ipairs(tbl2.Defs)do
list[#list + 1] = Court.CFrame * Vector3.new(Court.Size.X * def.XRatio,Court.Size.Y / 2 + def.SurfaceOffset,Court.Size.Z * def.ZRatio)
end
local dedeCornerFloorOffset = 0
for i in ipairs(tbl2.Defs)do
local marker = Markers[i]
if marker and marker.Parent then
local huge = math.huge
for _,value in ipairs(list)do
huge = math.min(huge,(value - marker.Position).Magnitude)
end
dedeCornerFloorOffset = math.max(dedeCornerFloorOffset,huge)
end
end
genv.DedeCornerFloorOffset = dedeCornerFloorOffset
if dedeCornerFloorOffset > 2 then
warn(string.format("[AutoCorner] markers pelo Floor ficaram ate %.1f studs da posicao antiga (Map.Court).",dedeCornerFloorOffset))
end
end)
end
return true
end
