local function IsShotClearOfNet(Position)
local net = GetNet()
if not net then
return false
end
local rootPart = GetRootPart()
local Character = LocalPlayer.Character
local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
local Position2 = HumanoidRootPart and HumanoidRootPart.Position or rootPart and GetPosition(rootPart)
if not Position2 then
return false
end
local flatten = Flatten(net.CFrame.LookVector)
if flatten.Magnitude < 0.001 then
return false
end
return(Position2 - net.Position):Dot(flatten)*(Position - net.Position):Dot(flatten)< 0
end
local function RayHitbox(Position,Unit,inst)
local localPoint = inst.CFrame:PointToObjectSpace(Position)
local delta = inst.CFrame:PointToObjectSpace(Position + Unit)- localPoint
local scaled = inst.Size * 0.5
local value,huge = 0,math.huge
local function SlabOverlap(X,X2,X3)
if math.abs(X2)< 1e-08 then
return math.abs(X)<= X3
end
local value2,value3 =(-X3 - X)/ X2,(X3 - X)/ X2
if value2 > value3 then
value2,value3 = value3,value2
end
value,huge = math.max(value,value2),math.min(huge,value3)
return value <= huge
end
if not SlabOverlap(localPoint.X,delta.X,scaled.X)or not SlabOverlap(localPoint.Y,delta.Y,scaled.Y)or not SlabOverlap(localPoint.Z,delta.Z,scaled.Z)then
return nil
end
return value
end
tbl2.RayHitbox = RayHitbox
local function Selected()
Update()
local CurrentCamera = Workspace.CurrentCamera
if not CurrentCamera then
return nil
end
local Position,Unit
pcall(function()
Position,Unit = CurrentCamera.CFrame.Position,CurrentCamera.CFrame.LookVector.Unit
end)
if Position and Unit then
local v,value
for i,hitbox in ipairs(Hitboxes)do
local marker2 = Markers[i]
if hitbox.Parent and marker2.Parent and IsShotClearOfNet(marker2.Position)then
local rayHitbox = RayHitbox(Position,Unit,hitbox)
if rayHitbox and(not value or rayHitbox < value)then
v,value = i,rayHitbox
end
end
end
if v then
return v
end
end
local ViewportSize = CurrentCamera.ViewportSize
local Vector22 = Vector2.new(ViewportSize.X / 2,ViewportSize.Y / 2)
local n = math.min(tbl2.SelectionRadius,math.min(ViewportSize.X,ViewportSize.Y)* 0.22)
local v2 = nil
local value2 = n
for j,marker in ipairs(Markers)do
if marker and marker.Parent and IsShotClearOfNet(marker.Position)then
local vec,v3 = CurrentCamera:WorldToViewportPoint(marker.Position)
if v3 and vec.Z > 0 then
local Magnitude =(Vector2.new(vec.X,vec.Y)- Vector22).Magnitude
if Magnitude < value2 then
value2 = Magnitude
v2 = j
end
end
end
end
return v2
end
tbl2.Selected = Selected
local function SetTarget(targetIndex)
Update()
local marker = Markers[targetIndex]
local def = tbl2.Defs[targetIndex]
if not marker or not marker.Parent or not def or not IsShotClearOfNet(marker.Position)then
return false
end
tbl2.TargetIndex = targetIndex
tbl2.TargetName = def.Name
tbl2.TargetPosition = marker.Position
genv.AutoCornerV25TargetIndex = targetIndex
genv.AutoCornerV25TargetName = def.Name
genv.AutoCornerV25TargetPosition = marker.Position
return true
end
