Part.Anchored = true
Part.CanCollide = false
Part.CanTouch = false
Part.CanQuery = false
Part.Material = Enum.Material.Neon
Part.Parent = Workspace
end
local value14 = 0
local flag2 = false
TrackConn(RunService.Heartbeat,function()
local now = os.clock()
if now - value14 < 0.05 then
return
end
value14 = now
if not(DEDE_AIM.CornerVisible and DEDE_AIM.CornerVisible())then
if not flag2 then
flag2 = true
for _,marker in ipairs(Markers)do
if marker and marker.Parent then
marker.Transparency = 1
end
end
end
return
end
flag2 = false
local selected = Selected()
if selected then
tbl2.LastHighlightedIndex = selected
tbl2.LastHighlightedAt = os.clock()
end
for i,marker2 in ipairs(Markers)do
if marker2 and marker2.Parent then
marker2.Transparency = i == selected and 0.02 or 0.25
end
end
end)
end
