local function GetBallVelocity(cframe)
if type(cframe)~= "table" then
return nil
end
local Velocity = nil
pcall(function()
Velocity = cframe.State.Ball.Velocity
end)
if typeof(Velocity)== "Vector3" and Velocity.Magnitude > 1 and Velocity.Magnitude < 500 then
return Velocity
end
return nil
end
local function SetPostHitVelocity(logAttempt,vec,arg3)
logAttempt.PostHitVelocity,logAttempt.PostHitVH,logAttempt.PostHitVY = vec,Flatten(vec).Magnitude,vec.Y
logAttempt.VelocitySource,logAttempt.MeasurementMissing = arg3,false
return true
end
local function Finish(logAttempt,Position,arg3)
if not logAttempt or logAttempt.NativeFinalized then
return
end
if logAttempt.Finished and not logAttempt.NativeGroundPosition then
return
end
logAttempt.Finished,logAttempt.FinishReason = true,arg3
genv.AutoCornerV25ActiveShots[logAttempt.Index] = nil
if not AutoCornerV30Native.Vector(Position)then
return
end
logAttempt.EndPosition,logAttempt.FinalBallPosition = Position,Position
logAttempt.InsideMarkedCourt = Geometry.Inside(logAttempt.CourtBounds,Position,0)
local flatten = Flatten(Position - logAttempt.BallStart)
local flatten2 = Flatten(Position - logAttempt.TargetPosition)
local Vector32 = Vector3.new(-logAttempt.TargetDirection.Z,0,logAttempt.TargetDirection.X)
logAttempt.ActualDistance = flatten:Dot(logAttempt.TargetDirection)
logAttempt.RangeError,logAttempt.LateralError,logAttempt.TargetError = flatten2:Dot(logAttempt.TargetDirection),flatten2:Dot(Vector32),flatten2.Magnitude
logAttempt.PredictionResidual = logAttempt.ActualDistance - logAttempt.PredictedDistance
pcall(RecordRoninFeedback,logAttempt)
logAttempt.Under1 = logAttempt.TargetError <= 1
logAttempt.Under2 = logAttempt.TargetError <= 2
logAttempt.WithinAcceptedRadius = logAttempt.TargetError <= 2.5
local inst = tbl2.Markers and tbl2.Markers[logAttempt.TargetIndex]
if inst then
local localPoint = inst.CFrame:PointToObjectSpace(Position)
logAttempt.InsideCornerSquare = math.abs(localPoint.X)<= inst.Size.X * 0.5 and math.abs(localPoint.Z)<= inst.Size.Z * 0.5
end
logAttempt.LandingSource = logAttempt.NativeConfirmed and logAttempt.NativeLandingSource or(logAttempt.HitIndicatorCaptured and "HIT_INDICATOR" or "UNCONFIRMED_VISUAL_OBSERVATION")
logAttempt.ValidHit =(logAttempt.NativeConfirmed == true or logAttempt.HitIndicatorCaptured == true)and logAttempt.BadHit ~= true
if logAttempt.ValidHit then
local tbl = genv.AutoCornerV30Stats[logAttempt.Style] or{
Attempts = 0,
Sent = 0,
Accepted = 0,
Measured = 0,
Under1 = 0,
Within2_5 = 0,
InsideSquare = 0,
}
genv.AutoCornerV30Stats[logAttempt.Style] = tbl
tbl.Measured = tbl.Measured + 1
if logAttempt.Under1 then
tbl.Under1 = tbl.Under1 + 1
end
if logAttempt.WithinAcceptedRadius then
tbl.Within2_5 = tbl.Within2_5 + 1
end
if logAttempt.InsideCornerSquare then
tbl.InsideSquare = tbl.InsideSquare + 1
end
local v = logAttempt.NativeAttemptIndex and genv.AutoCornerV25Attempts[logAttempt.NativeAttemptIndex]
if v then
v.Status = logAttempt.NativeConfirmed and "CONFIRMED_GROUND_CONTACT" or "MEASURED_HIT_INDICATOR"
v.TargetError = logAttempt.TargetError
end
if logAttempt.NativeConfirmed then
AutoCornerV30Native.RememberLanding(logAttempt,Position)
end
end
logAttempt.NativeFinalized = true
if tbl2.CreateMarker then
tbl2.CreateMarker(Position)
end
if genv.AutoCornerV25Debug then
print(string.format("[Auto Corner] %s | C %.3f | tilt %.3f | erro %.2f | %s",logAttempt.Style,logAttempt.Charge,logAttempt.TiltDot,logAttempt.TargetError,logAttempt.LandingSource))
end
end
