function AutoCornerV30Native.JSONValue(vec,value,map)
if IsFiniteNumber(vec)or type(vec)== "boolean" or type(vec)== "string" then
return vec
end
if AutoCornerV30Native.Vector(vec)then
return{X = vec.X,Y = vec.Y,Z = vec.Z}
end
if type(vec)~= "table" or value > 7 or map[vec] then
return nil
end
map[vec] = true
local map2 ={}
for key,v in pairs(vec)do
