local function GetStyleSamples(arg1,value,value2)
local kind = string.lower(arg1.Style or "")
local list = nil
local isRiku = kind == "riku"
local v2 = kind == "rintaro" or kind == "sanju"
if isRiku then
list = tbl2
elseif v2 then
list = tbl3
else
return 0,0,math.huge,nil,0
end
local list2 ={}
local value5 = v2 and 0.3 or 0.34
local value6 = v2 and 0.24 or 0.27
for _,v in ipairs(list)do
local value7 = v2 and 1 or 2.35
local d = math.abs(arg1.Height - v.H)/ value7 + math.abs(arg1.BallAboveCharacter - v.A)/(v2 and 5 or 3.25)+ math.abs(arg1.CharacterVY - v.CVY)/(v2 and 17 or 11)+ math.abs(arg1.IncomingVY - v.IVY)/(v2 and 18 or 11)+ math.abs(arg1.TargetDistance - v.T)/(v2 and 9 or 10)+ math.abs(arg1.NetPath - v.N)/(v2 and 12 or 9)+ math.abs(value - v.C)/ value5 + math.abs(value2 - v.D)/ value6
table.insert(list2,{D = d,B = v.B})
end
table.sort(list2,function(a,b)
return a.D < b.D
end)
while #list2 > 5 do
table.remove(list2)
end
if #list2 == 0 then
return 0,0,math.huge,isRiku and "RIKU" or "SANJU_RINTARO",0
end
local list3 ={}
for _,value3 in ipairs(list2)do
table.insert(list3,value3.B)
end
local median = Median(list3)
local value8 = 0
local value9 = 0
for _,value4 in ipairs(list2)do
local clamp
if isRiku then
clamp = Clamp(value4.B,median - 4,median + 4)
else
clamp = Clamp(value4.B,median - 5.5,median + 5.5)
end
local ratio = 1 /(0.3 + value4.D)^ 2.15
value8 = value8 + clamp * ratio
value9 = value9 + ratio
end
local value10 = value9 > 0 and value8 / value9 or median
local D = list2[1].D
if isRiku then
value10 = Clamp(value10,-7.5,6)
else
value10 = Clamp(value10,-11,14)
end
local clamp2 = Clamp(1.04 - D * 0.07,0.55,1)
if arg1.Height >= 20 and value10 > 0 then
if v2 then
value10 = value10 + 0.7
elseif isRiku then
value10 = value10 + 0.4
end
end
local scaled = value10 * clamp2
return value10,clamp2,D,isRiku and "RIKU" or "SANJU_RINTARO",scaled
end
