local function SetPostHitVelocity(logAttempt,postHitVelocity,velocitySource)
local Magnitude = Flatten(postHitVelocity).Magnitude
local Y = postHitVelocity.Y
logAttempt.PostHitVelocity = postHitVelocity
logAttempt.PostHitVH = Magnitude
logAttempt.PostHitVY = Y
logAttempt.VelocitySource = velocitySource
if Magnitude < value10 then
if velocitySource == "FRAME_FALLBACK" then
logAttempt.MeasurementMissing = true
logAttempt.LearningRejected = "UNRELIABLE_FRAME_VELOCITY"
return false
end
logAttempt.BadHit = true
logAttempt.ValidHit = false
return false
end
logAttempt.ValidHit = true
local v = math.abs(logAttempt.IncomingAlong)<= 40 and logAttempt.IncomingVH <= 45
if not v then
logAttempt.LearningRejected = "HIGH_INCOMING_SPEED"
return true
end
local SampleRef = logAttempt.SampleRef
if not SampleRef then
SampleRef ={
Charge = logAttempt.Charge,
TiltDot = logAttempt.TiltDot,
Height = logAttempt.BallHeight,
BallAboveCharacter = logAttempt.BallAboveCharacter,
CharacterVY = logAttempt.CharacterVY,
IncomingVY = logAttempt.IncomingVY,
IncomingAlong = logAttempt.IncomingAlong,
NetPath = logAttempt.NetPathDistance,
TargetDistance = logAttempt.TargetDistance,
DirectionX = logAttempt.TargetDirection.X,
BaseVH = logAttempt.BaseVH,
BaseVY = logAttempt.BaseVY,
ActualVH = nil,
ActualVY = nil,
LandingResidual = nil,
Time = os.clock(),
}
local sampleBucket = GetSampleBucket(logAttempt.ModelKey)
table.insert(sampleBucket,SampleRef)
while #sampleBucket > value36 do
table.remove(sampleBucket,1)
end
logAttempt.SampleRef = SampleRef
end
SampleRef.ActualVH = Magnitude
SampleRef.ActualVY = Y
return true
end
local function GetPartVelocity(part)
local part2 = GetPart(part)
if part2 then
local ok,result = pcall(function()
return part2.AssemblyLinearVelocity
end)
if ok and typeof(result)== "Vector3" and result.Magnitude > 5 and result.Magnitude < 350 then
return result
end
end
local list ={}
local list2 ={}
local list3 ={}
local position = GetPosition(part)
local now = os.clock()
if not position then
return nil
end
for i = 1,6 do
RunService.Heartbeat:Wait()
local position2 = GetPosition(part)
local now2 = os.clock()
if position2 then
local delta = now2 - now
if delta > 0.001 and delta < 0.12 then
local ratio =(position2 - position)/ delta
if ratio.Magnitude > 5 and ratio.Magnitude < 350 then
table.insert(list,ratio.X)
table.insert(list2,ratio.Y)
table.insert(list3,ratio.Z)
end
end
position = position2
now = now2
end
end
if #list == 0 then
return nil
end
return Vector3.new(Median(list),Median(list2),Median(list3))
end
local function FinishShot(arg1,endPosition,finishReason)
if not arg1 or arg1.Finished then
return
end
arg1.Finished = true
arg1.FinishReason = finishReason
if endPosition then
if not arg1.BadHit then
arg1.ValidHit = true
end
arg1.EndPosition = endPosition
arg1.ActualDistance = GetMagnitude(arg1.BallStart,endPosition)
local Vector32 = Vector3.new(endPosition.X -(arg1.BallStart.X + arg1.TargetDirection.X * arg1.TargetDistance),0,endPosition.Z -(arg1.BallStart.Z + arg1.TargetDirection.Z * arg1.TargetDistance))
arg1.RangeError = Vector32:Dot(arg1.TargetDirection)
local Vector33 = Vector3.new(-arg1.TargetDirection.Z,0,arg1.TargetDirection.X)
arg1.LateralError = Vector32:Dot(Vector33)
arg1.TargetError = Vector32.Magnitude
arg1.Under2 = arg1.TargetError <= value6
arg1.Over2 = arg1.RangeError > value5
arg1.PredictionResidual = arg1.ActualDistance - arg1.PredictedDistance
if arg1.ValidHit and arg1.CalibrationMode and not arg1.CalibrationOutsideData and arg1.NetSide == -1 and math.abs(arg1.LateralError)<= 1.5 and math.abs(arg1.RangeError)<= 18 and IsFiniteNumber(arg1.NetClearance)and arg1.NetClearance >= 0 then
local list = genv.AutoPixelV41Feedback[arg1.CalibrationMode]
if not list then
list ={}
genv.AutoPixelV41Feedback[arg1.CalibrationMode] = list
end
table.insert(list,{
H = arg1.BallHeight,
Z = arg1.RawNetZ,
T = arg1.TargetDistance,
X = arg1.TargetDirection.X,
C = arg1.Charge,
D = arg1.TiltDot,
R = Clamp(arg1.PredictionResidual,-9,9),
})
while #list > 24 do
table.remove(list,1)
end
end
local SampleRef = arg1.SampleRef
if not SampleRef then
SampleRef ={
Charge = arg1.Charge,
TiltDot = arg1.TiltDot,
Height = arg1.BallHeight,
BallAboveCharacter = arg1.BallAboveCharacter,
CharacterVY = arg1.CharacterVY,
IncomingVY = arg1.IncomingVY,
IncomingAlong = arg1.IncomingAlong,
NetPath = arg1.NetPathDistance,
TargetDistance = arg1.TargetDistance,
DirectionX = arg1.TargetDirection.X,
BaseVH = arg1.BaseVH,
BaseVY = arg1.BaseVY,
ActualVH = nil,
ActualVY = nil,
LandingResidual = nil,
Time = os.clock(),
}
local sampleBucket = GetSampleBucket(arg1.ModelKey)
table.insert(sampleBucket,SampleRef)
while #sampleBucket > value36 do
table.remove(sampleBucket,1)
end
arg1.SampleRef = SampleRef
end
local delta = arg1.ActualDistance - arg1.BallisticDistance
arg1.LandingResidual = delta
local ratio = arg1.ActualDistance / math.max(arg1.TargetDistance,1)
local value = 0.45
if string.lower(arg1.Style or "")== "riku" then
value = 0.72
end
local v = math.abs(arg1.LateralError or 0)<= 2.5 and arg1.TargetError <= 25 and arg1.ActualDistance >= 12 and ratio >= value and math.abs(arg1.PredictionResidual or 0)<= 20
if v then
SampleRef.LandingResidual = Clamp(delta,-32,32)
else
SampleRef.LandingResidual = nil
arg1.LearningRejected =(arg1.LearningRejected and arg1.LearningRejected .. "|" or "").. "BAD_LANDING_GEOMETRY_OR_TRAVEL"
end
ShowLastHitMarker(endPosition)
if arg1.SampleRef and IsFiniteNumber(arg1.PostHitVH)and IsFiniteNumber(arg1.PostHitVY)then
local ballisticDistance = BallisticDistance(arg1.BallHeight,arg1.PostHitVH,arg1.PostHitVY)
if IsFiniteNumber(ballisticDistance)then
arg1.ImmediateBallisticDistance = ballisticDistance
arg1.TrajectoryResidual = arg1.ActualDistance - ballisticDistance
arg1.SampleRef.TrajectoryResidual = arg1.TrajectoryResidual
end
end
end
genv.AutoPixelV41ActiveShots[arg1.Index] = nil
end
function Orchestrator.processHitboxCollision(...)
local map = table.pack(...)
local cframe = map[1]
local logAttempt = nil
local v = genv.AutoPixelV41Enabled and genv.AutoPixelV41Armed and type(cframe)== "table"
if v then
local Move = cframe.Move or cframe.ActionName or cframe.Name
if Move == nil or Move == "Spike" then
local AutoPixelV41Snapshot = genv.AutoPixelV41Snapshot
if not AutoPixelV41Snapshot then
AutoPixelV41Snapshot = ComputeAim()
end
if AutoPixelV41Snapshot then
ApplySpecialNormalization(cframe,AutoPixelV41Snapshot.Context.StyleInfo)
SaveCharacterRotation(AutoPixelV41Snapshot)
cframe.Charge = AutoPixelV41Snapshot.Charge
cframe.TiltDirection = AutoPixelV41Snapshot.TiltDirection
cframe.LookVector = AutoPixelV41Snapshot.LookVector
pcall(function()
if cframe.State and cframe.State.Control then
cframe.State.Control.TiltDot = AutoPixelV41Snapshot.TiltDot
end
end)
cframe.ForceInteractBall = true
cframe.IgnoreServer = false
cframe.Duration = math.max(cframe.Duration or 0,0.45)
logAttempt = LogAttempt(AutoPixelV41Snapshot,autoPixelV41RetryBudget - genv.AutoPixelV41RetryBudget + 1)
genv.AutoPixelV41Snapshot = AutoPixelV41Snapshot
end
end
end
local StyleInfo = logAttempt and genv.AutoPixelV41Snapshot and genv.AutoPixelV41Snapshot.Context.StyleInfo or nil
local list = ProcessHitboxPatched(map,cframe,StyleInfo)
if logAttempt then
genv.AutoPixelV41Armed = false
local stateVelocity = GetStateVelocity(cframe)
if stateVelocity then
SetPostHitVelocity(logAttempt,stateVelocity,"STATE_BALL_IMMEDIATE")
else
task.spawn(function()
local partVelocity = GetPartVelocity(logAttempt.Ball)
if partVelocity then
SetPostHitVelocity(logAttempt,partVelocity,"FRAME_FALLBACK")
else
logAttempt.MeasurementMissing = true
logAttempt.LearningRejected = "NO_VELOCITY"
end
end)
end
task.defer(RestoreCharacterRotation)
end
return table.unpack(list,1,list.n)
end
