end
local getconns = grab("getconnections","get_signal_cons")
local getrawmt = grab("getrawmetatable","get_raw_metatable")
local setro = grab("setreadonly","set_readonly")
if not setro then
local writeable,readonly = grab("make_writeable"),grab("make_readonly")
if writeable and readonly then
setro = function(target,state)
if state then readonly(target)else writeable(target)end
end
end
end
local getncm = grab("getnamecallmethod","get_namecall_method")
local hookmm = grab("hookmetamethod")
local newcc = grab("newcclosure")
local setident = grab("setthreadidentity","set_thread_identity","setidentity")
local getident = grab("getthreadidentity","get_thread_identity","getidentity")
local httpRequest = grab("request","http_request")
if not httpRequest then
local lib = grabTable("syn")or grabTable("http")or grabTable("fluxus")
httpRequest = lib and lib.request
end
local nativeFire = grab("firesignal","fire_signal")
local function fireViaConnections(signal,...)
if not getconns then return end
local ok,list = pcall(getconns,signal)
if not ok or type(list)~= "table" then return end
for _,connection in ipairs(list)do
pcall(connection.Fire,connection,...)
end
end
if nativeFire and getconns then
task.spawn(function()
local probe = Instance.new("BindableEvent")
local landed = false
probe.Event:Connect(function()landed = true end)
pcall(nativeFire,probe.Event,true)
task.wait(0.1)
probe:Destroy()
if not landed then nativeFire = nil end
end)
end
local function canFire()
return nativeFire ~= nil or getconns ~= nil
end
local function fire(signal,...)
local fn = nativeFire or fireViaConnections
if not fn or not signal then return false end
local restore = getident and getident()
if setident then pcall(setident,2)end
local ok = pcall(fn,signal,...)
if setident and restore then pcall(setident,restore)end
return ok
end
local function elevate(fn,...)
local restore = getident and getident()
if setident then pcall(setident,2)end
local ok,a,b = pcall(fn,...)
if setident and restore then pcall(setident,restore)end
return ok,a,b
end
local function httpGet(url)
local ok,body = pcall(function()return game:HttpGet(url)end)
if ok and type(body)== "string" and #body > 0 then return body end
if httpRequest then
local sent,response = pcall(httpRequest,{Url = url,Method = "GET"})
if sent and type(response)== "table" and type(response.Body)== "string" then
return response.Body
end
end
return nil
end
