local remoteCache ={}
local function remote(serviceName,kind,name)
local key = serviceName .. "." .. kind .. "." .. name
local cached = remoteCache[key]
if cached and cached.Parent then return cached end
local folder = service(serviceName)
folder = folder and folder:FindFirstChild(kind)
local found = folder and folder:FindFirstChild(name)
remoteCache[key] = found
return found
end
