local function getBallId()
for _,model in ipairs(Workspace:GetChildren())do
if model:IsA("Model")and model.Name:match("^CLIENT_BALL_%d+$")then
local id = model.Name:match("%d+")
if id then return tonumber(id)end
end
end
return nil
end
local function getNearestBall()
local nearestBall,nearestDistance = nil,math.huge
local character = LocalPlayer.Character
local rootPart = character and character:FindFirstChild("HumanoidRootPart")
if not rootPart then return nil,nil end
for _,model in ipairs(Workspace:GetChildren())do
if model:IsA("Model")and model.Name:match("^CLIENT_BALL_%d+$")then
for _,part in ipairs(model:GetDescendants())do
if part:IsA("BasePart")then
local distance =(part.Position - rootPart.Position).Magnitude
if distance < nearestDistance then
nearestDistance = distance
nearestBall = part
end
break
end
end
end
end
return nearestBall,nearestDistance
end
local hooked = false
local function installHook()
if hooked then return true end
if not getncm then return false end
local interact = remote("BallService","RF","Interact")
local serve = remote("GameService","RF","Serve")
if not interact and not serve then return false end
local function build(old)
return function(self,...)
if S.maxServeEnabled and serve and self == serve and getncm()== "InvokeServer" then
local args = table.pack(...)
args[2] = 5
return old(self,table.unpack(args,1,math.max(args.n,2)))
end
if S.sanjuTiltEnabled and interact and self == interact and getncm()== "InvokeServer" then
local data = ...
if type(data)== "table" and data.Move == "Spike" and typeof(data.TiltDirection)== "Vector3" and typeof(data.LookVector)== "Vector3" then
local tiltDir = data.TiltDirection
if math.abs(tiltDir.X)> 0.01 or math.abs(tiltDir.Z)> 0.01 then
local lookVec = data.LookVector
data.LookVector = Vector3.new(lookVec.X + tiltDir.X * 0.3,lookVec.Y,lookVec.Z + tiltDir.Z * 0.3).Unit
data.TiltDirection = Vector3.new(tiltDir.X * 1.35,tiltDir.Y,tiltDir.Z * 1.35)
end
end
end
return old(self,...)
end
end
if hookmm then
local old
local handler = build(function(...)
if old then return old(...)end
end)
local ok,result = pcall(hookmm,game,"__namecall",newcc and newcc(handler)or handler)
if ok and result then
old = result
hooked = true
return true
end
end
if getrawmt and setro then
local ok = pcall(function()
local mt = getrawmt(game)
local old = mt.__namecall
local handler = build(old)
setro(mt,false)
mt.__namecall = handler
setro(mt,true)
end)
hooked = ok
end
return hooked
end
