local function setupShiftLock(character)
local humanoid = character:WaitForChild("Humanoid",10)
local rootPart = character:WaitForChild("HumanoidRootPart",10)
if not humanoid or not rootPart then return end
if S.shiftLockConnection then S.shiftLockConnection:Disconnect()S.shiftLockConnection = nil end
S.shiftLockConnection = humanoid:GetPropertyChangedSignal("Jump"):Connect(function()
if not S.autoShiftLockEnabled then return end
if humanoid.Jump then
task.defer(function()
task.wait(0.03)
local camera = Cam()
if not camera or not rootPart.Parent then return end
local look = Vector3.new(camera.CFrame.LookVector.X,0,camera.CFrame.LookVector.Z)
if look.Magnitude > 0 then
rootPart.CFrame = CFrame.lookAt(rootPart.Position,rootPart.Position + look.Unit)
humanoid.AutoRotate = false
end
end)
else
humanoid.AutoRotate = false
end
end)
end
