if S.autoShiftLockEnabled then setupShiftLock(character)end
end))
end
else
if S.shiftLockConnection then S.shiftLockConnection:Disconnect()S.shiftLockConnection = nil end
local character = LocalPlayer.Character
local humanoid = character and character:FindFirstChildOfClass("Humanoid")
if humanoid then humanoid.AutoRotate = false end
end
end
function RG.AkariDash()
local character = LocalPlayer.Character
local hrp = character and character:FindFirstChild("HumanoidRootPart")
if not hrp then return false,"Sem personagem" end
local direction,distance = nil,10
local ball = getNearestBall()
if ball then
local flat = Vector3.new(ball.Position.X - hrp.Position.X,0,ball.Position.Z - hrp.Position.Z)
if flat.Magnitude > 0.01 then
direction = flat.Unit
distance = math.clamp(flat.Magnitude - 1,0,16)
end
end
if not direction then
local camera = Cam()
local forward = camera and camera.CFrame.LookVector or hrp.CFrame.LookVector
forward = Vector3.new(forward.X,0,forward.Z)
direction = forward.Magnitude > 0.01 and forward.Unit or Vector3.new(0,0,-1)
end
elevate(function()
local Effect = require(ReplicatedStorage.Content.Effect)
Effect:Play("KuraiDashFX")({Player = LocalPlayer,Direction = direction})
end)
TweenService:Create(hrp,TweenInfo.new(0.2,Enum.EasingStyle.Linear),{
CFrame = CFrame.new(hrp.Position + direction * distance)* CFrame.Angles(0,math.rad(hrp.Orientation.Y),0),
}):Play()
return true
end
