local leadFeetLink = nil
function RG.LeadFeet()
local character = LocalPlayer.Character
local root = character and character.PrimaryPart
local humanoid = character and character:FindFirstChildOfClass("Humanoid")
if not root or not humanoid or humanoid.Health <= 0 then return false,"Sem personagem" end
local tuning ={Acceleration = -10000,TerminalVelocity = -300,Duration = 2}
local gameController = nil
elevate(function()
local ability = require(ReplicatedStorage.Content.Ability.LeadFeet)
if type(ability)== "table" and type(ability.Metadata)== "table" then tuning = ability.Metadata end
gameController = require(ReplicatedStorage.Packages.Knit).GetController("GameController")
if gameController then gameController.IsBusy:set(false)end
require(ReplicatedStorage.Content.Effect):Play("LeadFeetFX")({Player = LocalPlayer})
require(ReplicatedFirst.Controllers.GameController.Actions.Move.Jump).stop()
if gameController then gameController.IsBusy:set(true)end
end)
if leadFeetLink then leadFeetLink:Disconnect()leadFeetLink = nil end
local expiry = os.clock()+(tuning.Duration or 2)
leadFeetLink = RunService.Heartbeat:Connect(function(delta)
if not root.Parent or humanoid.FloorMaterial ~= Enum.Material.Air or os.clock()>= expiry then
if gameController then pcall(function()gameController.IsBusy:set(false)end)end
if leadFeetLink then leadFeetLink:Disconnect()leadFeetLink = nil end
return
end
local velocity = root.AssemblyLinearVelocity
local drop = math.max(velocity.Y +(tuning.Acceleration or -10000)* delta,tuning.TerminalVelocity or -300)
root.AssemblyLinearVelocity = Vector3.new(velocity.X,drop,velocity.Z)
end)
return true
end
local function isEnemy(player)
if player == LocalPlayer then return false end
if not player.Team or not LocalPlayer.Team then return false end
return player.Team ~= LocalPlayer.Team
end
local function applyESP(player)
if not player.Character or S.espHighlights[player] then return end
local tone = Color3.fromRGB(255,72,72)
local highlight = Instance.new("Highlight")
highlight.Name = "REALGG_ESP"
highlight.Adornee = player.Character
highlight.FillColor = tone
highlight.FillTransparency = 0.72
highlight.OutlineTransparency = 0
highlight.OutlineColor = tone
highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
highlight.Parent = player.Character
S.espHighlights[player] = highlight
end
local function removeESP(player)
local highlight = S.espHighlights[player]
if highlight then
pcall(function()highlight:Destroy()end)
S.espHighlights[player] = nil
end
end
local espLoop = nil
local espLast = 0
function RG.SetJumpESP(value)
S.espJumpEnabled = value and true or false
if S.espJumpEnabled then
if espLoop then return end
espLoop = track(RunService.Heartbeat:Connect(function()
local now = os.clock()
if now - espLast < 0.05 then return end
espLast = now
for _,player in ipairs(Players:GetPlayers())do
local character = player.Character
local humanoid = character and character:FindFirstChildOfClass("Humanoid")
local jumping = false
if humanoid and isEnemy(player)then
local humanoidState = humanoid:GetState()
jumping = humanoidState == Enum.HumanoidStateType.Jumping or humanoidState == Enum.HumanoidStateType.Freefall
end
if jumping then
local current = S.espHighlights[player]
if current and current.Adornee ~= character then removeESP(player)end
applyESP(player)
else
removeESP(player)
end
end
for player in pairs(S.espHighlights)do
if not player.Parent then removeESP(player)end
end
end))
else
if espLoop then
espLoop:Disconnect()
espLoop = nil
end
for player in pairs(S.espHighlights)do removeESP(player)end
end
end
