end
local list ={}
pcall(function()
if kind == "effects" then
local assets = ReplicatedStorage:FindFirstChild("Assets")
local effectFolder = assets and assets:FindFirstChild("ScoreEffect")
if effectFolder then
for _,child in ipairs(effectFolder:GetChildren())do
if child:IsA("ModuleScript")then list[#list + 1] = child.Name end
end
end
local defaultFolder = assets and assets:FindFirstChild("Effects")
if defaultFolder then
for _,name in ipairs({"GroundHit1","GroundHit2"})do
