end
end
if #list == 0 then list[1] = "SupernovaScoreEffect" end
elseif kind == "cards" then
local entities = ReplicatedStorage.Content.Item:FindFirstChild("Entities")
if entities then
for _,child in ipairs(entities:GetChildren())do
if child:IsA("ModuleScript")and string.match(child.Name,"Card")then list[#list + 1] = child.Name end
end
end
if #list == 0 then list[1] = "ContentCreatorPlayerCard" end
elseif kind == "balls" then
local assets = ReplicatedStorage:FindFirstChild("Assets")
local ballFolder = assets and assets:FindFirstChild("Ball")
if ballFolder then
for _,child in ipairs(ballFolder:GetChildren())do
if child:IsA("Model")then list[#list + 1] = child.Name end
end
end
if #list == 0 then list[1] = "ClassicBall" end
end
end)
table.sort(list)
S.lists[kind] = list
return list
end
