if child.Name == "HitIndicator" and child:IsA("BasePart")and child.Color == green then fireHitRemote(child.Position)end
end)
S.hitConnection2 = Workspace.DescendantAdded:Connect(function(child)
if child.Name == "HitIndicator" and child:IsA("BasePart")and child.Color == green then fireHitRemote(child.Position)end
end)
S.hitRemovedConnection = Workspace.DescendantRemoving:Connect(function(child)
