local HOLDER_NAME = "REALGG_BALLSKIN"
local function sweep()
local assets = ReplicatedStorage:FindFirstChild("Assets")
local ballFolder = assets and assets:FindFirstChild("Ball")
if not ballFolder then return end
local function strip(model)
local holder = S.clones[model]
if holder then
pcall(function()holder:Destroy()end)
S.clones[model] = nil
end
local saved = S.originals[model]
if saved then
for piece,record in pairs(saved)do
if piece.Parent then pcall(function()piece[record.field] = record.value end)end
end
S.originals[model] = nil
end
end
local function isOurs(piece)
return piece:GetAttribute("DEDE_HITBOX_VISUAL")or piece:GetAttribute("DEDE_HITBOX")
or piece:GetAttribute("DEDE_LOCAL_BALL_VISUAL")or piece:GetAttribute("DEDE_IGNORE_BALL_COSMETIC")
end
local function skin(model)
local driver = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
local source = ballFolder:FindFirstChild(S.selectedBallSkin)
if not driver or not source then return end
strip(model)
local saved ={}
local function stash(piece,field,value)
saved[piece] ={field = field,value = piece[field]}
piece[field] = value
end
for _,piece in ipairs(model:GetDescendants())do
if not isOurs(piece)then
if piece:IsA("BasePart")then
stash(piece,"Transparency",1)
elseif piece:IsA("Decal")or piece:IsA("Texture")then
stash(piece,"Transparency",1)
elseif piece:IsA("Trail")or piece:IsA("ParticleEmitter")or piece:IsA("Beam")or piece:IsA("Light")
or piece:IsA("Smoke")or piece:IsA("Fire")or piece:IsA("Sparkles")then
stash(piece,"Enabled",false)
end
end
end
S.originals[model] = saved
local holder = source:Clone()
holder.Name = HOLDER_NAME
holder.Parent = model
local pieces ={}
if holder:IsA("BasePart")then pieces[#pieces + 1] = holder end
for _,candidate in ipairs(holder:GetDescendants())do
if candidate:IsA("BasePart")then pieces[#pieces + 1] = candidate end
end
local anchor = holder:IsA("Model")and holder.PrimaryPart or nil
if not anchor then
local bestScore
for _,candidate in ipairs(pieces)do
local size = candidate.Size
local volume = size.X * size.Y * size.Z
local roundish = math.abs(size.X - size.Y)< 0.5 and math.abs(size.Y - size.Z)< 0.5
local score = volume
if candidate:IsA("Part")and candidate.Shape == Enum.PartType.Ball then
score = score * 6
elseif roundish then
score = score * 3
end
if not bestScore or score > bestScore then
bestScore = score
anchor = candidate
end
end
end
if anchor then
local offset = holder:GetPivot():ToObjectSpace(anchor.CFrame)
holder:PivotTo(driver.CFrame * offset:Inverse())
else
holder:PivotTo(driver.CFrame)
end
for _,part in ipairs(pieces)do
part.Anchored = false
part.CanCollide = false
part.CanQuery = false
part.CanTouch = false
part.Massless = true
local weld = Instance.new("WeldConstraint")
weld.Part0 = driver
weld.Part1 = part
weld.Parent = part
end
S.clones[model] = holder
end
local tracked ={}
for model in pairs(S.clones)do tracked[#tracked + 1] = model end
for _,model in ipairs(tracked)do strip(model)end
if not S.autoApplyBallSkin and not S.RandomState.ball then return end
for _,model in ipairs(Workspace:GetChildren())do
if model:IsA("Model")and model.Name:match("^CLIENT_BALL_")then pcall(skin,model)end
end
if not S.seen.ballHook then
S.seen.ballHook = track(Workspace.ChildAdded:Connect(function(child)
if not(S.autoApplyBallSkin or S.RandomState.ball)or not child:IsA("Model")or not child.Name:match("^CLIENT_BALL_")then return end
task.spawn(function()
for _ = 1,40 do
if child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart")then break end
task.wait(0.05)
end
if(S.autoApplyBallSkin or S.RandomState.ball)and child.Parent then pcall(sweep)end
end)
end))
end
end
