end
return true,"Revert enviado, reentrando..."
end
function RG.ReadLuckies()
local now = os.clock()
if now - S.luckyCache.stamp < 0.3 and S.luckyCache.value ~= nil then return S.luckyCache.value end
local ok,value = pcall(function()
local styleController = controller("StyleController")
if not styleController then return nil end
local lucky = styleController.LuckySpins
if type(lucky)== "table" then
local getOk,getVal = pcall(function()return lucky:get()end)
if getOk and type(getVal)== "number" then return getVal end
if type(lucky._value)== "number" then return lucky._value end
end
if type(lucky)== "number" then return lucky end
return nil
end)
if ok and type(value)== "number" then
S.luckyCache ={value = value,source = "StyleController.LuckySpins",stamp = now}
return value
end
for _,name in ipairs({"LuckySpins","LuckySpin","LuckyStyleSpins"})do
local n = tonumber(LocalPlayer:GetAttribute(name))
if n then
S.luckyCache ={value = n,source = "attr:" .. name,stamp = now}
return n
end
end
local leaderstats = LocalPlayer:FindFirstChild("leaderstats")
if leaderstats then
for _,name in ipairs({"LuckySpins","LuckySpin","LuckyStyleSpins"})do
local obj = leaderstats:FindFirstChild(name)
if obj and tonumber(obj.Value)then
local n = tonumber(obj.Value)
S.luckyCache ={value = n,source = "ls:" .. name,stamp = now}
return n
end
end
end
return S.luckyCache.value
end
function RG.LuckySource()
