end
local function waitForLobbyReady(timeout)
local start = os.clock()
while os.clock()- start <(timeout or 30)do
local styles,abilities = readLobbyText("Styles"),readLobbyText("Abilities")
if styles and styles ~= "" and abilities and abilities ~= "" then return true end
task.wait(0.5)
end
return false
end
function RG.SetRollbackTarget(style)
if type(style)== "string" and style ~= "" and style ~= "(Nenhum)" and style ~= "__none" then
S.AutoRollback.targetStyle = style
else
S.AutoRollback.targetStyle = nil
end
end
function RG.SetRollbackMax(value)
S.AutoRollback.maxLuckies = math.max(0,math.floor(tonumber(value)or 0))
end
local function startAutoRollback()
local AR = S.AutoRollback
if AR.running then return end
AR.running = true
AR.usedCount = 0
AR.nilReads = 0
S.luckyCache ={value = nil,source = nil,stamp = 0}
local function finishStop(reason,kind)
AR.enabled = false
AR.running = false
turnedOff("AutoRollback")
notify(reason or "Auto Revert finalizado",kind)
end
local function triggerDataRollback(reason)
_G.__REAL_AUTO_ROLLBACK_DONE = true
AR.running = false
AR.enabled = false
notify((reason or "Luckies esgotados").. " — Revert disparado","warn")
task.wait(0.4)
RG.DataRollback()
end
task.spawn(function()
notify("Auto Revert: aguardando o lobby carregar...")
if not waitForLobbyReady(30)then
finishStop("Auto Revert: lobby não carregou em 30s","err")
return
end
task.wait(1)
local targetStyle = AR.targetStyle
if not targetStyle then
finishStop("Auto Revert: escolha um estilo alvo","warn")
return
end
notify("Auto Revert: buscando '" .. targetStyle .. "'")
local safety = 0
while AR.enabled and RG.Running and safety < 500 do
safety = safety + 1
local current = readLobbyText("Styles")
if matchesAny(current,{targetStyle})then
finishStop("Estilo obtido: " .. tostring(current),"ok")
return
end
local luckies = RG.ReadLuckies()
if luckies ~= nil and luckies <= 0 then
triggerDataRollback("Lucky Spins esgotados")
return
end
if AR.maxLuckies > 0 and AR.usedCount >= AR.maxLuckies then
triggerDataRollback("Limite de " .. AR.maxLuckies .. " luckies atingido")
return
end
if luckies == nil then
AR.nilReads = AR.nilReads + 1
if AR.nilReads >= 8 then
finishStop("Não foi possível ler os Lucky Spins — parando","err")
return
end
else
AR.nilReads = 0
end
roll("StyleService",true)
AR.usedCount = AR.usedCount + 1
task.wait(0.5)
end
if AR.running then finishStop("Auto Revert concluído")end
end)
end
function RG.SetAutoRollback(value,fromLoad)
local AR = S.AutoRollback
if not value then
AR.enabled = false
AR.running = false
return
end
if not AR.targetStyle then
AR.enabled = false
if not fromLoad then notify("Escolha um estilo alvo antes de ativar","warn")end
turnedOff("AutoRollback")
return
end
AR.enabled = true
if fromLoad then
if _G.__REAL_AUTO_ROLLBACK_DONE then return end
task.delay(3,function()
if AR.enabled and not AR.running and RG.Running then
notify("Auto Revert (autoload): iniciando...")
startAutoRollback()
end
end)
else
startAutoRollback()
end
end
