function RG.RedeemCodes()
local redeem = remote("CodeService","RF","Redeem")
if not redeem then return false,"CodeService não encontrado" end
local data = httpGet("https://beebom.com/haikyuu-legends-codes/")
if not data then return false,"Não consegui baixar a lista de códigos" end
local codes,seen ={},{}
for line in string.gmatch(data,"[^\n]+")do
if string.find(line,"(NEW)",1,true)then
local code = string.match(line,"(%u+[%u%d_]+)")
if code and not seen[code] then
seen[code] = true
codes[#codes + 1] = code
end
end
if #codes >= 3 then break end
end
if #codes == 0 then return "warn","Nenhum código novo encontrado" end
for _,code in ipairs(codes)do
pcall(function()redeem:InvokeServer(code)end)
task.wait(0.01)
end
return true,table.concat(codes,", ")
end
