local Acceleration = typeof(ballById.Acceleration)== "Vector3" and ballById.Acceleration or Vector3.zero
local Jerk = typeof(ballById.Jerk)== "Vector3" and ballById.Jerk or Vector3.zero
local list2 ={}
local list3 ={}
for i = 2,#list do
local inst = list[i - 1]
local inst2 = list[i]
local scaled = inst.Velocity * Vector3.new(1,0,1)
local scaled2 = inst2.Velocity * Vector3.new(1,0,1)
local scaled3 =(scaled + scaled2)* 0.5
local Magnitude = scaled3.Magnitude
if 0.001 < Magnitude then
if(scaled2 - scaled).Magnitude <= Magnitude * 0.08 + 0.1 then
local scaled4 =(inst2.Position - inst.Position)* Vector3.new(1,0,1)
local dot = scaled3:Dot(scaled3)
if 1e-06 < dot then
local ratio = scaled4:Dot(scaled3)/ dot
if 0 < ratio and ratio <= 0.1 then
local ratio2 = -((inst2.Velocity.Y - inst.Velocity.Y)/ ratio -(Acceleration.Y + Jerk.Y * ratio * 0.5))/ ballGravity
if 0.01 < ratio2 and ratio2 < 20 then
list2[#list2 + 1] = ratio2
list3[#list3 + 1] = ratio
end
end
end
end
end
end
if #list2 == 0 then
