ballById = FindBallById(key)
list = TrimToLastImpact(GetRecentHistory(key,now))
if ballById and 2 <= #list then
fit = FitTrajectory(list,ballById)
if fit then
break
end
end
RunService.Heartbeat:Wait()
if deadline <= os.clock()then
break
end
continue
end
return
end
if not ballById or not fit or not list or #list == 0 then
if LandingPredictor.Pending[key] == token then
LandingPredictor.Pending[key] = nil
end
return
end
local v = SimulateTrajectory(ballById,list[#list],fit,list)
if LandingPredictor.Pending[key] == token then
