end
RaycastParams2.FilterDescendantsInstances = FilterDescendantsInstances
RaycastParams2.IgnoreWater = true
local rayResult = Workspace:Raycast(vec + Vector3.new(0,0.2,0),Vector3.new(0,-5.5,0),RaycastParams2)
return rayResult and math.max(0,vec.Y - rayResult.Position.Y)or math.huge
end
