local function DetectVelocityImpulse(arg1,key,inst,vec)
local historyEntry = LandingPredictor.History[key]
local lastSample = historyEntry and historyEntry[#historyEntry]
if not lastSample or typeof(lastSample.Velocity)~= "Vector3" then
return false
end
local delta = vec - lastSample.Velocity
local Magnitude = delta.Magnitude
if Magnitude < 2 then
return false
end
local Magnitude2 = Vector3.new(delta.X,0,delta.Z).Magnitude
local Magnitude3 = lastSample.Velocity.Magnitude
local Magnitude4 = vec.Magnitude
local flag = false
if 4 < Magnitude3 and 4 < Magnitude4 then
flag = lastSample.Velocity.Unit:Dot(vec.Unit)< 0.82
end
if LandingPredictor.MinHorizontalImpulse <= Magnitude2 or LandingPredictor.MinTotalImpulse <= Magnitude or flag and 3.4 <= Magnitude then
if Magnitude2 < LandingPredictor.MinHorizontalImpulse then
