local fillTransparency = math.clamp(tonumber(LandingPredictor.HighlightTransparency)or 0,0,1)
Visual.Highlight.FillTransparency = fillTransparency
Visual.Highlight.OutlineTransparency = fillTransparency
end
return
end
end
