local HitboxVisuals ={Connection = nil,UpdateConnection = nil,Active ={},LastScan = 0}
function HitboxVisuals.GetMesh(part)
if part then
if part:IsA("BasePart")then
if part:GetAttribute("DEDE_LOCAL_BALL_VISUAL")then
return nil
end
return part
end
for _,part2 in ipairs(part:GetDescendants())do
if part2:IsA("BasePart")and not part2:GetAttribute("DEDE_HITBOX")and not part2:GetAttribute("DEDE_LOCAL_BALL_VISUAL")and not part2:GetAttribute("DEDE_IGNORE_BALL_COSMETIC")and not part2:GetAttribute("DEDE_HITBOX_VISUAL")then
return part2
end
end
return
end
return nil
end
function HitboxVisuals.IsWorldBall(model)
if not model or not model.Parent then
return false
end
if model:IsA("Model")or model:IsA("BasePart")then
if model.Name:sub(1,12)== "CLIENT_BALL_" then
local Parent = model.Parent
while Parent and Parent ~= Workspace do
if Parent:IsA("Model")and Parent:FindFirstChildOfClass("Humanoid")then
return false
end
Parent = Parent.Parent
end
return Parent == Workspace
end
return false
end
return false
end
function HitboxVisuals.MakeVisualTemplate(mesh)
if mesh then
local ok,part = pcall(mesh.Clone,mesh)
if not ok or not part then
return nil
end
part.Name = "DEDE_HITBOX_VISUAL_TEMPLATE"
part:SetAttribute("DEDE_HITBOX_VISUAL",true)
part:SetAttribute("DEDE_LOCAL_BALL_VISUAL",true)
part:SetAttribute("DEDE_IGNORE_BALL_COSMETIC",true)
for _,script in ipairs(part:GetDescendants())do
if script:IsA("Script")or script:IsA("LocalScript")or script:IsA("WeldConstraint")then
script:Destroy()
continue
end
if not script:IsA("BasePart")then
continue
end
script:SetAttribute("DEDE_HITBOX_VISUAL",true)
script:SetAttribute("DEDE_LOCAL_BALL_VISUAL",true)
script:SetAttribute("DEDE_IGNORE_BALL_COSMETIC",true)
script.CanCollide = false
script.CanTouch = false
script.CanQuery = false
script.Massless = true
end
if part:IsA("BasePart")then
part.CanCollide = false
part.CanTouch = false
part.CanQuery = false
part.Massless = true
end
part.Parent = nil
return part
end
return nil
end
function HitboxVisuals.DestroyFallbackVisual(entry)
