end
if entry.PartHitbox and entry.PartHitbox.Parent then
return
end
local ok,part = pcall(Instance.new,"Part")
local part2 = part
if not ok or not part2 then
return
end
part2.Name = "DEDE_HITBOX_PART"
part2:SetAttribute("DEDE_HITBOX",true)
part2:SetAttribute("DEDE_IGNORE_BALL_COSMETIC",true)
pcall(function()
part2.Shape = Enum.PartType.Ball
end)
part2.Size = Vector3.new(Config.Size,Config.Size,Config.Size)
part2.Transparency = math.clamp(Config.Transparency,0,1)
part2.Material = Enum.Material[Config.HitBoxMaterialName] or Enum.Material.ForceField
part2.Color = Config.HitBoxColor
part2.Anchored = false
part2.CanCollide = false
part2.CanTouch = true
part2.CanQuery = true
part2.Massless = true
part2.CFrame = entry.Mesh.CFrame
part2.Parent = key
local WeldConstraint = Instance.new("WeldConstraint")
WeldConstraint.Name = "DEDE_HITBOX_PART_WELD"
WeldConstraint.Part0 = entry.Mesh
WeldConstraint.Part1 = part2
WeldConstraint.Parent = part2
entry.PartHitbox = part2
end
function HitboxVisuals.StripVisualObject(decal,activeEntry)
if not decal or not activeEntry or IsLocalBallVisual(decal)then
return
end
if decal:IsA("Decal")or decal:IsA("Texture")or decal:IsA("SurfaceAppearance")then
if activeEntry.DetachedVisuals[decal] == nil and decal.Parent then
activeEntry.DetachedVisuals[decal] = decal.Parent
decal.Parent = nil
end
return
end
if decal:IsA("MeshPart")then
if activeEntry.MeshTextureIds[decal] == nil then
activeEntry.MeshTextureIds[decal] = decal.TextureID
end
decal.TextureID = ""
elseif decal:IsA("SpecialMesh")then
if activeEntry.SpecialMeshTextureIds[decal] == nil then
activeEntry.SpecialMeshTextureIds[decal] = decal.TextureId
end
decal.TextureId = ""
end
end
function HitboxVisuals.StripRealBallVisuals(key,entry)
if not key or not entry then
return
end
HitboxVisuals.StripVisualObject(key,entry)
for _,descendant in ipairs(key:GetDescendants())do
HitboxVisuals.StripVisualObject(descendant,entry)
end
end
function HitboxVisuals.RestoreRealBallVisuals(entry)
if entry then
for key,detachedVisual in pairs(entry.DetachedVisuals or{})do
local inst = key
local inst2 = detachedVisual
if inst and not inst.Parent and inst2 and inst2.Parent then
pcall(function()
inst.Parent = inst2
end)
end
end
for k,meshTextureId in pairs(entry.MeshTextureIds or{})do
local inst3 = k
local textureID = meshTextureId
if inst3 and inst3.Parent then
pcall(function()
inst3.TextureID = textureID
end)
end
end
for key2,specialMeshTextureId in pairs(entry.SpecialMeshTextureIds or{})do
local inst4 = key2
local textureId = specialMeshTextureId
if inst4 and inst4.Parent then
pcall(function()
inst4.TextureId = textureId
end)
end
end
return
end
end
function HitboxVisuals.EnsureFallbackVisual(model,entry)
if not model or not entry or not entry.Mesh then
return
end
local ballOverlay = BallCosmetics.BallOverlays[model]
if ballOverlay and ballOverlay.Clone and ballOverlay.Clone.Parent then
HitboxVisuals.DestroyFallbackVisual(entry)
return
end
if entry.Visual and entry.Visual.Parent then
return
end
if entry.VisualTemplate then
local ok,part1 = pcall(entry.VisualTemplate.Clone,entry.VisualTemplate)
if not ok or not part1 then
return
end
part1.Name = "DEDE_HITBOX_VISUAL"
part1:SetAttribute("DEDE_HITBOX_VISUAL",true)
part1:SetAttribute("DEDE_LOCAL_BALL_VISUAL",true)
part1:SetAttribute("DEDE_IGNORE_BALL_COSMETIC",true)
if part1:IsA("BasePart")then
part1.Anchored = false
part1.CanCollide = false
part1.CanTouch = false
part1.CanQuery = false
part1.Massless = true
part1.CFrame = entry.Mesh.CFrame
part1.Parent = model
local WeldConstraint = Instance.new("WeldConstraint")
WeldConstraint.Name = "DEDE_HITBOX_VISUAL_WELD"
WeldConstraint.Part0 = entry.Mesh
WeldConstraint.Part1 = part1
WeldConstraint.Parent = part1
entry.VisualWelded = true
else
part1.Parent = model
SetInstancePivot(part1,entry.Mesh.CFrame)
entry.VisualWelded = AlignOverlayToBall(part1,model)
end
entry.Visual = part1
return
end
end
function HitboxVisuals.Create(key)
if not HitboxVisuals.IsWorldBall(key)or HitboxVisuals.Active[key] then
return
end
local mesh = HitboxVisuals.GetMesh(key)
if not mesh or not mesh.Parent then
return
end
local ballOverlay = BallCosmetics.BallOverlays[key]
local part = ballOverlay and ballOverlay.Hidden and ballOverlay.Hidden.Parts and ballOverlay.Hidden.Parts[mesh]
local Transparency = part and part.Transparency or mesh.Transparency
local LocalTransparencyModifier = part and part.LocalTransparencyModifier or mesh.LocalTransparencyModifier
local entry ={
Mesh = mesh,
OriginalSize = mesh.Size,
OriginalTransparency = Transparency,
OriginalLocalTransparency = LocalTransparencyModifier,
OriginalCanCollide = mesh.CanCollide,
OriginalCanTouch = mesh.CanTouch,
OriginalCanQuery = mesh.CanQuery,
OriginalMaterial = mesh.Material,
OriginalColor = mesh.Color,
VisualTemplate = HitboxVisuals.MakeVisualTemplate(mesh),
Visual = nil,
VisualWelded = false,
PartHitbox = nil,
Adornment = nil,
DetachedVisuals ={},
MeshTextureIds ={},
SpecialMeshTextureIds ={},
}
if entry.VisualTemplate and entry.VisualTemplate:IsA("BasePart")then
entry.VisualTemplate.Transparency = Transparency
entry.VisualTemplate.LocalTransparencyModifier = LocalTransparencyModifier
end
HitboxVisuals.Active[key] = entry
mesh:SetAttribute("DEDE_REAL_HITBOX",true)
mesh:SetAttribute("DEDE_IGNORE_BALL_COSMETIC",true)
HitboxVisuals.StripRealBallVisuals(key,entry)
mesh.Size = Vector3.new(Config.Size,Config.Size,Config.Size)
mesh.Transparency = math.clamp(Config.Transparency,0,1)
mesh.LocalTransparencyModifier = 0
mesh.Material = Enum.Material[Config.HitBoxMaterialName] or Enum.Material.ForceField
mesh.Color = Config.HitBoxColor
mesh.CanCollide = false
mesh.CanTouch = true
mesh.CanQuery = true
HitboxVisuals.EnsureFallbackVisual(key,entry)
HitboxVisuals.EnsurePartHitbox(key,entry)
end
function HitboxVisuals.Restore(key,entry)
if entry then
local Mesh = entry.Mesh
if Mesh and Mesh.Parent then
pcall(function()
Mesh.Size = entry.OriginalSize
local ballOverlay = BallCosmetics.BallOverlays[key]
if ballOverlay and ballOverlay.Clone and ballOverlay.Clone.Parent then
Mesh.Transparency = 1
Mesh.LocalTransparencyModifier = 1
else
Mesh.Transparency = entry.OriginalTransparency
Mesh.LocalTransparencyModifier = entry.OriginalLocalTransparency
end
Mesh.CanCollide = entry.OriginalCanCollide
Mesh.CanTouch = entry.OriginalCanTouch
Mesh.CanQuery = entry.OriginalCanQuery
Mesh.Material = entry.OriginalMaterial or Enum.Material.Plastic
Mesh.Color = entry.OriginalColor or Mesh.Color
Mesh:SetAttribute("DEDE_REAL_HITBOX",nil)
Mesh:SetAttribute("DEDE_IGNORE_BALL_COSMETIC",nil)
end)
end
HitboxVisuals.RestoreRealBallVisuals(entry)
if entry.Adornment and entry.Adornment.Parent then
entry.Adornment:Destroy()
end
HitboxVisuals.DestroyFallbackVisual(entry)
HitboxVisuals.DestroyPartHitbox(entry)
if entry.VisualTemplate then
entry.VisualTemplate:Destroy()
entry.VisualTemplate = nil
end
HitboxVisuals.Active[key] = nil
return
end
end
function HitboxVisuals.TryObject(model)
if not Config.HitBoxExpander or not model then
return
end
local model2 = nil
if(model:IsA("Model")or model:IsA("BasePart"))and model.Name:sub(1,12)== "CLIENT_BALL_" then
model2 = model
else
pcall(function()
model2 = FindWorkspaceBall(model)
end)
end
if model2 and HitboxVisuals.IsWorldBall(model2)then
local activeEntry = HitboxVisuals.Active[model2]
if activeEntry then
HitboxVisuals.StripVisualObject(model,activeEntry)
else
HitboxVisuals.Create(model2)
end
end
end
function HitboxVisuals.UpdateLive()
local now = os.clock()
local Vector32 = Vector3.new(Config.Size,Config.Size,Config.Size)
for _,value in pairs(HitboxVisuals.Active)do
local Mesh = value and value.Mesh
if not(Mesh and Mesh.Parent)then
continue
end
if Mesh.Size ~= Vector32 then
Mesh.Size = Vector32
end
if not Mesh.CanTouch then
Mesh.CanTouch = true
end
if not Mesh.CanQuery then
Mesh.CanQuery = true
end
if Mesh.CanCollide then
Mesh.CanCollide = false
end
local PartHitbox = value.PartHitbox
if PartHitbox and PartHitbox.Parent then
if PartHitbox.Size ~= Vector32 then
PartHitbox.Size = Vector32
end
if not PartHitbox.CanTouch then
PartHitbox.CanTouch = true
end
if not PartHitbox.CanQuery then
PartHitbox.CanQuery = true
end
if PartHitbox.CanCollide then
PartHitbox.CanCollide = false
end
end
end
local styleSig = tostring(Config.Size).. "|" .. tostring(Config.Transparency).. "|" .. tostring(Config.HitBoxMaterialName).. "|" .. tostring(Config.HitBoxColor)
local styleDue = HitboxVisuals.StyleSig ~= styleSig or not HitboxVisuals.LastStyleTick or 2 <= now - HitboxVisuals.LastStyleTick
HitboxVisuals.StyleSig = styleSig
local motionDue = not HitboxVisuals.LastMotionTick or 0.033 <= now - HitboxVisuals.LastMotionTick
if styleDue then
HitboxVisuals.LastStyleTick = now
end
if motionDue then
HitboxVisuals.LastMotionTick = now
end
if not styleDue and not motionDue and now - HitboxVisuals.LastScan < 0.5 then
return
end
if 0.5 <= now - HitboxVisuals.LastScan then
HitboxVisuals.LastScan = now
for _,model in ipairs(Workspace:GetChildren())do
if(model:IsA("Model")or model:IsA("BasePart"))and model.Name:sub(1,12)== "CLIENT_BALL_" and not HitboxVisuals.Active[model] then
HitboxVisuals.Create(model)
end
end
end
local list ={}
for key,v in pairs(HitboxVisuals.Active)do
local Mesh2 = v and v.Mesh
if not HitboxVisuals.IsWorldBall(key)or not Mesh2 or not Mesh2.Parent then
list[#list + 1] = key
continue
end
if styleDue or v.StyleSig ~= styleSig then
v.StyleSig = styleSig
Mesh2.Size = Vector32
Mesh2.Transparency = math.clamp(Config.Transparency,0,1)
Mesh2.LocalTransparencyModifier = 0
if Mesh2:IsA("MeshPart")and Mesh2.TextureID ~= "" then
Mesh2.TextureID = ""
end
Mesh2.Material = Enum.Material[Config.HitBoxMaterialName] or Enum.Material.ForceField
Mesh2.Color = Config.HitBoxColor
Mesh2.CanCollide = false
Mesh2.CanTouch = true
Mesh2.CanQuery = true
local PartHitbox2 = v.PartHitbox
if PartHitbox2 and PartHitbox2.Parent then
PartHitbox2.Size = Vector32
PartHitbox2.Transparency = math.clamp(Config.Transparency,0,1)
PartHitbox2.Material = Enum.Material[Config.HitBoxMaterialName] or Enum.Material.ForceField
PartHitbox2.Color = Config.HitBoxColor
PartHitbox2.CanCollide = false
PartHitbox2.CanTouch = true
PartHitbox2.CanQuery = true
end
end
if styleDue or not v.Visual or not v.Visual.Parent then
HitboxVisuals.EnsureFallbackVisual(key,v)
end
if styleDue or not v.PartHitbox or not v.PartHitbox.Parent then
HitboxVisuals.EnsurePartHitbox(key,v)
end
if motionDue and v.Visual and v.Visual.Parent and not v.VisualWelded then
SetInstancePivot(v.Visual,Mesh2.CFrame)
end
end
for i = 1,#list do
HitboxVisuals.Restore(list[i],HitboxVisuals.Active[list[i]])
end
end
function HitboxVisuals.Toggle(hitBoxExpander)
Config.HitBoxExpander = hitBoxExpander and true or false
Runtime.ActiveFeatures.HitBox = Config.HitBoxExpander
SafeDisconnect(HitboxVisuals.Connection)
HitboxVisuals.Connection = nil
SafeDisconnect(HitboxVisuals.UpdateConnection)
HitboxVisuals.UpdateConnection = nil
if Config.HitBoxExpander then
HitboxVisuals.LastScan = 0
for _,child in ipairs(Workspace:GetChildren())do
HitboxVisuals.TryObject(child)
end
HitboxVisuals.Connection = TrackConnection(Workspace.DescendantAdded:Connect(function(descendant)
HitboxVisuals.TryObject(descendant)
end))
HitboxVisuals.UpdateConnection = TrackConnection(RunService.Heartbeat:Connect(HitboxVisuals.UpdateLive))
else
local list ={}
for key in pairs(HitboxVisuals.Active)do
list[#list + 1] = key
end
for i = 1,#list do
HitboxVisuals.Restore(list[i],HitboxVisuals.Active[list[i]])
end
end
end
function HitboxVisuals.Update()
HitboxVisuals.LastStyleTick = nil
HitboxVisuals.UpdateLive()
end
local PointMarkers ={}
local map ={}
local PointView ={Conn = nil,LastTick = 0}
local function RemovePointMarker(key)
if PointMarkers[key] then
PointMarkers[key]:Destroy()
PointMarkers[key] = nil
end
end
local function ClearPointMarkers()
local list ={}
for key in pairs(PointMarkers)do
list[#list + 1] = key
end
for i = 1,#list do
RemovePointMarker(list[i])
end
end
local function UpdatePointView()
if not Runtime.Running or not Config.PointView then
return
end
local now = os.clock()
if now - PointView.LastTick < 0.05 then
return
end
PointView.LastTick = now
local ForceField = Enum.Material[Config.PointViewMaterialName] or Enum.Material.ForceField
local presetColor = FindPresetColor(Config.PointViewColorName or "Green")
local map2 ={}
for _,player in ipairs(Players:GetPlayers())do
if not(player ~= LocalPlayer and not map[player.Name] and player.Character)then
continue
end
local Head = player.Character:FindFirstChild("Head")
if not Head then
continue
end
map2[player.Name] = true
local part = PointMarkers[player.Name]
if not part then
part = CreateInstance("Part",{
Name = "DEDE_POINTVIEW",
Anchored = true,
CanCollide = false,
CanQuery = false,
CanTouch = false,
Material = Enum.Material.ForceField,
Color = NamedColors.Green,
Parent = Workspace,
})
PointMarkers[player.Name] = part
end
local PointViewSize = Config.PointViewSize
if part:GetAttribute("DEDE_PV_SIZE")~= PointViewSize then
part.Size = Vector3.new(1,1,PointViewSize)
part:SetAttribute("DEDE_PV_SIZE",PointViewSize)
end
if part.Transparency ~= Config.PointViewTransparency then
part.Transparency = Config.PointViewTransparency
end
if part.Material ~= ForceField then
part.Material = ForceField
end
if part.Color ~= presetColor.Color then
part.Color = presetColor.Color
end
local LookVector = Head.CFrame.LookVector
local Vector32 = Vector3.new(LookVector.X,0,LookVector.Z)
local Unit = 0.01 < Vector32.Magnitude and Vector32.Unit or Vector3.new(0,0,-1)
part.CFrame = CFrame.lookAt(Head.Position,Head.Position + Unit)* CFrame.new(0,0.2,-(0.5 + PointViewSize / 2))
end
local list ={}
for key in pairs(PointMarkers)do
if not map2[key] then
list[#list + 1] = key
end
end
for i = 1,#list do
RemovePointMarker(list[i])
end
end
function PointView.SetEnabled(enabled)
local pointView = enabled and true or false
Config.PointView = pointView
Runtime.ActiveFeatures.PointView = pointView
SafeDisconnect(PointView.Conn)
PointView.Conn = nil
PointView.LastTick = 0
if pointView then
UpdatePointView()
PointView.Conn = RunService.Heartbeat:Connect(UpdatePointView)
return
end
ClearPointMarkers()
end
local Refresher ={Conn = nil}
local function UpdateMovementMods()
if Runtime.Running then
if not Config.SpeedEnable and not Config.RotateInAir and not Config.MoveOnAir then
return
end
local Character = LocalPlayer.Character
local Humanoid = Character and Character:FindFirstChildOfClass("Humanoid")
local HumanoidRootPart = Character and Character:FindFirstChild("HumanoidRootPart")
if not Humanoid or not HumanoidRootPart then
return
end
if Config.SpeedEnable and Humanoid.WalkSpeed ~= Config.Speed then
Humanoid.WalkSpeed = Config.Speed
end
if Config.RotateInAir or Config.MoveOnAir then
local State = Humanoid:GetState()
if State == Enum.HumanoidStateType.Jumping or State == Enum.HumanoidStateType.Freefall then
if Humanoid.AutoRotate ~= Config.RotateInAir then
Humanoid.AutoRotate = Config.RotateInAir
end
if Config.MoveOnAir and 0 < Humanoid.MoveDirection.Magnitude then
local MoveDirection = Humanoid.MoveDirection
local AssemblyLinearVelocity = HumanoidRootPart.AssemblyLinearVelocity
local scaled = MoveDirection.X * Config.Speed
local scaled2 = MoveDirection.Z * Config.Speed
if 0.05 < math.abs(AssemblyLinearVelocity.X - scaled)or 0.05 < math.abs(AssemblyLinearVelocity.Z - scaled2)then
