function AutoSave.Fingerprint(capture)
local list ={capture.Enabled and "1" or "0"}
local Values = capture.Values or{}
local list2 ={}
for key in pairs(Values)do
list2[#list2 + 1] = key
end
table.sort(list2)
for _,key2 in ipairs(list2)do
local value = Values[key2]
if type(value)== "table" and value.__color then
list[#list + 1] = key2 .. "=C:" .. tostring(value.R).. ":" .. tostring(value.G).. ":" .. tostring(value.B)
continue
end
list[#list + 1] = key2 .. "=" .. tostring(value)
end
local Equipped = capture.Equipped or{}
for _,key3 in ipairs({"Ball","ScoreEffect","PlayerCard","Title"})do
list[#list + 1] = "EQ:" .. key3 .. "=" .. tostring(Equipped[key3] or "")
end
if type(Equipped.Emotes)== "table" then
for i = 1,4 do
list[#list + 1] = "EM:" .. i .. "=" .. tostring(Equipped.Emotes[i] or "")
end
end
local Keybinds = capture.Keybinds or{}
local list3 ={}
for k in pairs(Keybinds)do
list3[#list3 + 1] = k
end
table.sort(list3)
for _,key4 in ipairs(list3)do
list[#list + 1] = "KB:" .. key4 .. "=" .. tostring(Keybinds[key4])
end
return table.concat(list,"|")
end
