local function New(className,guiObject)
local Instance2 = Instance.new(className)
local v = nil
if guiObject then
for mode,value in pairs(guiObject)do
if mode == "Parent" then
v = value
continue
end
local ok,result = pcall(SetField,Instance2,mode,value)
if not ok then
local key = className .. "." .. tostring(mode)
if not map[key] then
map[key] = true
warn("[DEDE/UI] " .. key .. ": " .. tostring(result))
end
end
end
end
if v then
Instance2.Parent = v
end
return Instance2
end
