local function Gradient(parent,rotation,list,list2)
local list3 ={}
if list then
for i,value in ipairs(list)do
list3[#list3 + 1] = ColorSequenceKeypoint.new((i - 1)/ math.max(#list - 1,1),value)
end
if #list3 == 1 then
list3[2] = ColorSequenceKeypoint.new(1,list[1])
end
else
list3 ={ColorSequenceKeypoint.new(0,Palette.white),ColorSequenceKeypoint.new(1,Palette.white)}
end
local uIGradient = New("UIGradient",{Rotation = rotation or 0,Color = ColorSequence.new(list3),Parent = parent})
if list2 then
local list4 ={}
for _,map in ipairs(list2)do
list4[#list4 + 1] = NumberSequenceKeypoint.new(map[1],map[2])
end
uIGradient.Transparency = NumberSequence.new(list4)
end
return uIGradient
end
local function MeasureText(Text,y,mono,x)
local ok,result = pcall(function()
return TextService:GetTextSize(Text,y,mono,Vector2.new(x or 10000,10000))
end)
if ok and result then
return result
end
return Vector2.new(#Text * y * 0.55,y)
end
local tweenPresets ={}
local I18n ={lang = "pt",binds = setmetatable({},{__mode = "k"}),hooks ={}}
function I18n.t(key,...)
local tweenPreset = tweenPresets[key]
if tweenPreset then
local v = I18n.lang == "en" and tweenPreset[2] or tweenPreset[1]
if 0 < select("#",...)then
local ok,result = pcall(string.format,v,...)
if ok then
v = result
end
end
return v
end
return tostring(key)
end
function I18n.paint(key)
local bind = I18n.binds[key]
if bind then
local t
if bind[2] then
t = I18n.t(bind[1],bind[2]())
else
t = I18n.t(bind[1])
end
pcall(SetField,key,bind[3],t)
return
end
end
function I18n.bind(key,descKey,args,arg4)
I18n.binds[key] ={descKey,args,arg4 or "Text"}
I18n.paint(key)
return key
end
function I18n.hook(frame,relayout)
I18n.hooks[#I18n.hooks + 1] ={frame,relayout}
end
function I18n.refresh()
for key in pairs(I18n.binds)do
I18n.paint(key)
end
local hooks ={}
for _,hook in ipairs(I18n.hooks)do
if hook[1] and hook[1].Parent then
local ok,result = pcall(hook[2])
if not ok then
warn("[DEDE/UI] i18n hook: " .. tostring(result))
end
hooks[#hooks + 1] = hook
end
end
I18n.hooks = hooks
end
function I18n.set(kind)
local lang = kind == "en" and "en" or "pt"
if lang == I18n.lang then
return false
end
I18n.lang = lang
I18n.refresh()
return true
end
