TextYAlignment = opts.ya or TextYAlignment2.Center,
TextWrapped = opts.wrap or false,
RichText = opts.rich or false,
TextTruncate = opts.trunc or Enum.TextTruncate.None,
TextTransparency = opts.tt or 0,
Position = opts.pos or UDim2.new(),
Size = opts.size or UDim2.new(1,0,0,(opts.s or 13)+ 6),
AnchorPoint = opts.anchor or Vector2.new(0,0),
ZIndex = opts.z or 1,
LayoutOrder = opts.order or 0,
Text = "",
Parent = parent,
}
if opts.name then
inst.Name = opts.name
end
local textLabel = New("TextLabel",inst)
if opts.k then
I18n.bind(textLabel,opts.k,opts.args)
else
textLabel.Text = opts.t or ""
end
return textLabel
end
local Motion ={reduced = false}
local EasingStyle = Enum.EasingStyle
local EasingDirection = Enum.EasingDirection
local map2 ={
micro ={0.12,EasingStyle.Quart,EasingDirection.Out},
hover ={0.18,EasingStyle.Quart,EasingDirection.Out},
base ={0.28,EasingStyle.Quint,EasingDirection.Out},
enter ={0.5,EasingStyle.Quint,EasingDirection.Out},
exit ={0.2,EasingStyle.Quad,EasingDirection.In},
pop ={0.36,EasingStyle.Back,EasingDirection.Out},
swift ={0.24,EasingStyle.Exponential,EasingDirection.Out},
soft ={0.7,EasingStyle.Sine,EasingDirection.InOut},
linear ={0.3,EasingStyle.Linear,EasingDirection.InOut},
}
local map3 ={}
local tweenCache = setmetatable({},{__mode = "k"})
local function GetTweenInfo(key,arg2)
local base = map2[key] or map2.base
local duration = arg2 or base[1]
if Motion.reduced then
duration = math.min(duration,0.08)
end
local key2 = tostring(key).. ":" .. tostring(duration)
local v = map3[key2]
if not v then
v = TweenInfo.new(duration,base[2],base[3])
map3[key2] = v
end
return v
end
function Motion.to(frame,list,key,arg4)
if frame then
local tweenInfo = GetTweenInfo(key or "base",arg4)
local map = tweenCache[frame]
if not map then
map ={}
tweenCache[frame] = map
end
for k,value in pairs(list)do
local key2 = k
local v = map[key2]
if v then
pcall(v.Cancel,v)
end
local ok,result = pcall(TweenService.Create,TweenService,frame,tweenInfo,{[key2] = value})
local result2 = result
if ok and result2 then
map[key2] = result2
result2.Completed:Connect(function()
if map[key2] == result2 then
map[key2] = nil
end
end)
result2:Play()
continue
end
map[key2] = nil
pcall(SetField,frame,key2,value)
end
return
end
end
function Motion.set(frame,list)
if frame then
local map = tweenCache[frame]
for key,value in pairs(list)do
if map and map[key] then
pcall(map[key].Cancel,map[key])
map[key] = nil
end
pcall(SetField,frame,key,value)
end
return
end
end
local Ticker ={subs ={},conn = nil,n = 0}
function Ticker.add(AnimateBootFrame)
Ticker.n = Ticker.n + 1
local key = Ticker.n
Ticker.subs[key] = AnimateBootFrame
if not Ticker.conn then
Ticker.conn = RunService.Heartbeat:Connect(function(dt)
if Runtime.Running then
local now = os.clock()
local list ={}
for key,sub in pairs(Ticker.subs)do
list[#list + 1] ={key,sub}
end
for _,map in ipairs(list)do
local ok,result = pcall(map[2],now,dt)
if not ok or result == false then
Ticker.subs[map[1]] = nil
end
end
if next(Ticker.subs)== nil and Ticker.conn then
Ticker.conn:Disconnect()
Ticker.conn = nil
end
return
end
if Ticker.conn then
Ticker.conn:Disconnect()
Ticker.conn = nil
end
end)
TrackConnection(Ticker.conn)
end
return key
end
function Ticker.remove(key)
if key then
Ticker.subs[key] = nil
end
end
