Frame ={"BackgroundTransparency"},
TextLabel ={"BackgroundTransparency","TextTransparency"},
TextButton ={"BackgroundTransparency","TextTransparency"},
TextBox ={"BackgroundTransparency","TextTransparency"},
ImageLabel ={"BackgroundTransparency","ImageTransparency"},
ImageButton ={"BackgroundTransparency","ImageTransparency"},
ScrollingFrame ={"BackgroundTransparency","ScrollBarImageTransparency"},
CanvasGroup ={"GroupTransparency"},
UIStroke ={"Transparency"},
}
local Fader ={rest = setmetatable({},{__mode = "k"})}
local function CollectFadeTargets(inst,list)
list[#list + 1] = inst
if inst.ClassName == "CanvasGroup" then
return list
end
for _,child in ipairs(inst:GetChildren())do
if child.ClassName == "CanvasGroup" then
list[#list + 1] = child
continue
end
CollectFadeTargets(child,list)
end
return list
end
local function SnapshotProps(inst)
local list = map4[inst.ClassName]
if list then
local map ={}
for _,key in ipairs(list)do
map[key] = inst[key]
end
Fader.rest[inst] = map
return map
end
return nil
end
function Fader.prime(frame)
for _,fadeTarget in ipairs(CollectFadeTargets(frame,{}))do
local list = SnapshotProps(fadeTarget)
if list then
local map ={}
for key in pairs(list)do
map[key] = 1
end
Motion.set(fadeTarget,map)
end
end
end
function Fader.to(frame,value,arg3,value2)
if frame then
for _,fadeTarget in ipairs(CollectFadeTargets(frame,{}))do
local list = Fader.rest[fadeTarget] or SnapshotProps(fadeTarget)
if list then
local map ={}
for key,v in pairs(list)do
map[key] = v +(1 - v)* value
end
if value2 == 0 then
Motion.set(fadeTarget,map)
continue
end
Motion.to(fadeTarget,map,arg3,value2)
end
end
return
end
end
