local function MakeIcon(parent,key,backgroundColor3,arg4,zIndex,arg6)
local width = arg4 or 18
backgroundColor3 = backgroundColor3 or Palette.ash
local glyph = New("Frame",{
BackgroundTransparency = 1,
BorderSizePixel = 0,
Size = UDim2.fromOffset(width,width),
ZIndex = zIndex or 1,
Name = "Glyph",
Parent = parent,
})
local ratio = width / 24
local thickness = arg6 or 2
local zIndex2 = zIndex or 1
(Icons[key] or Icons.spark)(function(x1,y1,x2,y2,thickness2)
local scaled =(x2 - x1)* ratio
local scaled2 =(y2 - y1)* ratio
local value = math.sqrt(scaled * scaled + scaled2 * scaled2)
local height = math.max(1,(thickness2 or thickness)* ratio)
local f = New("Frame",{
BackgroundColor3 = backgroundColor3,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.fromOffset((x1 + x2)/ 2 * ratio,(y1 + y2)/ 2 * ratio),
Size = UDim2.fromOffset(value + height * 0.9,height),
Rotation = math.deg(math.atan2(scaled2,scaled)),
ZIndex = zIndex2,
Name = "F",
Parent = glyph,
})
Corner(f,99)
end,function(cx,cy,radius,thickness2)
local s = New("Frame",{
BackgroundTransparency = 1,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.fromOffset(cx * ratio,cy * ratio),
Size = UDim2.fromOffset(radius * 2 * ratio,radius * 2 * ratio),
ZIndex = zIndex2,
Name = "S",
Parent = glyph,
})
Corner(s,999)
Stroke(s,backgroundColor3,0,math.max(1,(thickness2 or thickness)* ratio))
end,function(cx,cy,radius)
local f = New("Frame",{
BackgroundColor3 = backgroundColor3,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.fromOffset(cx * ratio,cy * ratio),
Size = UDim2.fromOffset(radius * 2 * ratio,radius * 2 * ratio),
ZIndex = zIndex2,
Name = "F",
Parent = glyph,
})
Corner(f,999)
end,function(x,y,w,h,radius,thickness2)
local s = New("Frame",{
BackgroundTransparency = 1,
BorderSizePixel = 0,
Position = UDim2.fromOffset(x * ratio,y * ratio),
Size = UDim2.fromOffset(w * ratio,h * ratio),
ZIndex = zIndex2,
Name = "S",
Parent = glyph,
})
Corner(s,(radius or 2)* ratio)
Stroke(s,backgroundColor3,0,math.max(1,(thickness2 or thickness)* ratio))
end,function(x,y,w,h)
local f = New("Frame",{
BackgroundColor3 = backgroundColor3,
BorderSizePixel = 0,
Position = UDim2.fromOffset(x * ratio,y * ratio),
Size = UDim2.fromOffset(w * ratio,h * ratio),
ZIndex = zIndex2,
Name = "F",
Parent = glyph,
})
Corner(f,1.5 * ratio)
end)
return glyph
end
local function RecolorStrokes(icon,color,arg3)
if icon then
for _,guiObject in ipairs(icon:GetDescendants())do
if guiObject.ClassName == "UIStroke" then
if arg3 then
Motion.to(guiObject,{Color = color},arg3)
continue
end
guiObject.Color = color
continue
end
if guiObject.Name == "F" and guiObject.ClassName == "Frame" then
if arg3 then
Motion.to(guiObject,{BackgroundColor3 = color},arg3)
continue
end
guiObject.BackgroundColor3 = color
end
end
return
end
end
local Prefs ={
lang = nil,
scale = 1,
backdrop = true,
motion = true,
toasts = true,
revertAck = false,
loaded = false,
}
local PrefsFile = "DEDE_INTERFACE.json"
function Prefs.load()
if typeof(readfile)== "function" then
if typeof(isfile)== "function" then
local ok,exists = pcall(isfile,PrefsFile)
if not ok or not exists then
return false
end
end
local ok2,content = pcall(readfile,PrefsFile)
if not ok2 or type(content)~= "string" or content == "" then
return false
end
local ok3,decoded = pcall(HttpService.JSONDecode,HttpService,content)
if not ok3 or type(decoded)~= "table" then
return false
end
if decoded.lang == "pt" or decoded.lang == "en" then
Prefs.lang = decoded.lang
end
if type(decoded.scale)== "number" then
Prefs.scale = math.clamp(decoded.scale,0.7,1.3)
end
if type(decoded.backdrop)== "boolean" then
Prefs.backdrop = decoded.backdrop
end
if type(decoded.motion)== "boolean" then
Prefs.motion = decoded.motion
end
if type(decoded.toasts)== "boolean" then
Prefs.toasts = decoded.toasts
end
if type(decoded.revertAck)== "boolean" then
Prefs.revertAck = decoded.revertAck
end
Prefs.loaded = true
return true
end
return false
end
local value = 0
function Prefs.save()
value = value + 1
local value2 = value
task.delay(0.4,function()
if value2 ~= value or typeof(writefile)~= "function" then
return
end
local ok,encoded = pcall(HttpService.JSONEncode,HttpService,{
lang = Prefs.lang or I18n.lang,
scale = Prefs.scale,
backdrop = Prefs.backdrop,
motion = Prefs.motion,
toasts = Prefs.toasts,
revertAck = Prefs.revertAck,
})
if ok then
pcall(writefile,PrefsFile,encoded)
end
end)
end
local function CreateScreenGui(name,displayOrder)
local ScreenGui = Instance.new("ScreenGui")
ScreenGui.Name = name
ScreenGui.ResetOnSpawn = false
ScreenGui.IgnoreGuiInset = true
ScreenGui.DisplayOrder = displayOrder
ScreenGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
pcall(function()
ScreenGui.ScreenInsets = Enum.ScreenInsets.None
end)
local v,text = SafeSetParent(ScreenGui,GetGuiParent())
if not v then
pcall(function()
ScreenGui:Destroy()
end)
error("gethui parent failed: " .. tostring(text))
end
Runtime.Guis[#Runtime.Guis + 1] = ScreenGui
return ScreenGui
end
local function GetViewportSize()
local CurrentCamera = Workspace.CurrentCamera
return CurrentCamera and CurrentCamera.ViewportSize or Vector2.new(1280,720)
end
local function GetViewportScale(value,value2)
local viewportSize = GetViewportSize()
return math.clamp(math.min(viewportSize.X / 1280,viewportSize.Y / 720),value,value2)
end
local function OnViewportChanged(handler)
handler()
local conn = nil
local function Rebind()
if conn then
conn:Disconnect()
end
local CurrentCamera = Workspace.CurrentCamera
if CurrentCamera then
conn = TrackConnection(CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(handler))
end
end
Rebind()
TrackConnection(Workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
Rebind()
task.defer(handler)
end))
return handler
end
local function BindAutoScale(uIScale,value,value2,value3,value4,value5,callback)
return OnViewportChanged(function()
local viewportSize = GetViewportSize()
local value6 = math.min((viewportSize.X - value3 * 2)/ value,(viewportSize.Y - value3 * 2)/ value2)
uIScale.Scale = math.clamp(value6,value4 or 0.45,value5 or 1.15)*(callback and callback()or 1)
end)
end
local value2 = 14
local function AddGlow(parent,backgroundColor3,width,value,zIndex)
value = value or 0.08
local glow = New("Frame",{
BackgroundTransparency = 1,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.fromScale(0.5,0.5),
Size = UDim2.fromOffset(width,width),
ZIndex = zIndex or 1,
Name = "Glow",
Parent = parent,
})
local function Falloff(ratio)
return value *(1 - ratio)^ 1.7
end
for i = 1,value2 do
local ratio =(i - 1)/ value2
local ratio2 = i / value2
local delta = Falloff(ratio)- Falloff(ratio2)
if i == value2 then
delta = Falloff(ratio)
end
local frame = New("Frame",{
BackgroundColor3 = backgroundColor3,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.fromScale(0.5,0.5),
Size = UDim2.fromScale(ratio2,ratio2),
BackgroundTransparency = 1 - delta,
ZIndex = zIndex or 1,
Parent = glow,
})
Corner(frame,999)
end
return glow
end
local function AddShadow(parent,value,zIndex,value2,value3)
local shadow = New("Frame",{
BackgroundTransparency = 1,
BorderSizePixel = 0,
Size = UDim2.fromScale(1,1),
ZIndex = zIndex or 0,
Name = "Shadow",
Parent = parent,
})
for _,map in ipairs({{6,0.8},{16,0.88},{30,0.94}})do
local scaled = map[1] *(value2 or 1)
local frame = New("Frame",{
BackgroundColor3 = Palette.black,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.new(0.5,0,0.5,math.floor(scaled * 0.45)),
Size = UDim2.new(1,scaled * 2,1,scaled * 2),
BackgroundTransparency = 1 -(1 - map[2])*(value3 or 1),
ZIndex = zIndex or 0,
Parent = shadow,
})
Corner(frame,value + scaled)
end
return shadow
end
local function AddBevel(parent,width,zIndex,backgroundTransparency)
local bevel = New("Frame",{
BackgroundColor3 = Palette.white,
BackgroundTransparency = backgroundTransparency or 0.93,
BorderSizePixel = 0,
Position = UDim2.fromOffset(width or 12,0),
Size = UDim2.new(1,-(width or 12)* 2,0,1),
ZIndex = zIndex or 2,
Name = "Bevel",
Parent = parent,
})
Gradient(bevel,0,nil,{{0,1},{0.5,0},{1,1}})
return bevel
end
local function MakeLogoMark(parent,width,backgroundColor3,zIndex)
local mark = New("Frame",{
BackgroundTransparency = 1,
BorderSizePixel = 0,
Size = UDim2.fromOffset(width,width),
ZIndex = zIndex or 1,
Name = "Mark",
Parent = parent,
})
local scaled = width * 0.7
local frame = New("Frame",{
BackgroundColor3 = Palette.ink1,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.fromScale(0.5,0.5),
Size = UDim2.fromOffset(scaled,scaled),
Rotation = 45,
ZIndex = zIndex or 1,
Parent = mark,
})
Corner(frame,math.max(2,width * 0.09))
local stroke = Stroke(frame,backgroundColor3 or Palette.ember,0,math.max(1.5,width * 0.055))
local frame2 = New("Frame",{
BackgroundColor3 = backgroundColor3 or Palette.ember,
BorderSizePixel = 0,
AnchorPoint = Vector2.new(0.5,0.5),
Position = UDim2.fromScale(0.5,0.5),
Size = UDim2.fromOffset(scaled * 0.36,scaled * 0.36),
Rotation = 45,
ZIndex =(zIndex or 1)+ 1,
Parent = mark,
})
Corner(frame2,math.max(1,width * 0.04))
return mark,frame,frame2,stroke
end
