local UI ={
built = false,
state = "idle",
visible = false,
controls ={},
byId ={},
pages ={},
order ={},
}
local Screens ={}
local Builder ={}
local contentWidth = 498
local sidePadding = 18
local controlGap = 14
local function IsPrimaryInput(input)
return input.UserInputType == UserInputType.MouseButton1 or input.UserInputType == UserInputType.Touch
end
local Toasts ={gui = nil,holder = nil,stack ={}}
function Toasts.ensure()
if Toasts.gui and Toasts.gui.Parent then
return Toasts.gui
end
Toasts.gui = CreateScreenGui("DEDE_TOASTS",10050)
Toasts.holder = New("Frame",{
BackgroundTransparency = 1,
AnchorPoint = Vector2.new(0.5,0),
Position = UDim2.new(0.5,0,0,16),
Size = UDim2.fromOffset(380,240),
Parent = Toasts.gui,
})
local uIScale = New("UIScale",{Parent = Toasts.holder})
BindAutoScale(uIScale,1280,720,0,0.72,1.1)
return Toasts.gui
end
function Toasts.layout()
local height = 0
for _,inst in ipairs(Toasts.stack)do
Motion.to(inst,{Position = UDim2.new(0.5,0,0,height)},"base",0.34)
height = height +(inst.Size.Y.Offset + 8)
end
end
function Toasts.dismiss(frame)
if not frame or not frame.Parent or frame:GetAttribute("Leaving")then
return
end
frame:SetAttribute("Leaving",true)
for i,value in ipairs(Toasts.stack)do
if value == frame then
table.remove(Toasts.stack,i)
break
end
end
Fader.to(frame,1,"exit",0.18)
Motion.to(frame,{Position = frame.Position - UDim2.fromOffset(0,10)},"exit",0.2)
task.delay(0.24,function()
if frame.Parent then
frame:Destroy()
end
end)
Toasts.layout()
end
function Toasts.push(kind,t,t2)
if not Prefs.toasts or not Runtime.Running then
return
end
if pcall(Toasts.ensure)then
local ok = kind == "ok" and Palette.ok or kind == "warn" and Palette.warn or kind == "err" and Palette.err or Palette.ember
local v = kind == "ok" and "check" or(kind == "warn" or kind == "err")and "alert" or "info"
local height = t2 and 58 or 44
local frame = MakeFrame(Toasts.holder,{
BackgroundColor3 = Palette.ink2,
AnchorPoint = Vector2.new(0.5,0),
Position = UDim2.new(0.5,0,0,-22),
Size = UDim2.fromOffset(364,height),
ZIndex = 5,
})
Corner(frame,14)
Stroke(frame,Palette.line2,0.15,1)
local frame2 = MakeFrame(frame,{
BackgroundColor3 = ok,
Position = UDim2.new(0,0,0.5,0),
AnchorPoint = Vector2.new(0,0.5),
Size = UDim2.fromOffset(3,height - 24),
ZIndex = 6,
})
Corner(frame2,2)
local frame3 = MakeFrame(frame,{
BackgroundColor3 = ok,
BackgroundTransparency = 0.86,
AnchorPoint = Vector2.new(0,0.5),
Position = UDim2.new(0,14,0.5,0),
Size = UDim2.fromOffset(30,30),
ZIndex = 6,
})
Corner(frame3,9)
local icon = MakeIcon(frame3,v,ok,16,7)
icon.AnchorPoint = Vector2.new(0.5,0.5)
icon.Position = UDim2.fromScale(0.5,0.5)
MakeLabel(frame,{
t = t or "",
f = Fonts.bold,
s = 13,
c = Palette.bone,
z = 6,
trunc = Enum.TextTruncate.AtEnd,
pos = UDim2.fromOffset(56,t2 and 10 or 0),
size = UDim2.new(1,-70,0,t2 and 18 or height),
})
if t2 then
MakeLabel(frame,{
t = t2,
f = Fonts.body,
s = 12,
c = Palette.smoke,
z = 6,
trunc = Enum.TextTruncate.AtEnd,
pos = UDim2.fromOffset(56,30),
size = UDim2.new(1,-70,0,17),
})
end
Fader.prime(frame)
table.insert(Toasts.stack,1,frame)
while 3 < #Toasts.stack do
Toasts.dismiss(Toasts.stack[#Toasts.stack])
end
Toasts.layout()
Fader.to(frame,0,"base",0.3)
task.delay(2.9,function()
Toasts.dismiss(frame)
end)
return
end
end
local Tooltip ={frame = nil,label = nil,token = 0}
function Tooltip.show(text)
if not text or text == "" then
return
end
if pcall(Toasts.ensure)then
if not Tooltip.frame or not Tooltip.frame.Parent then
Tooltip.frame = MakeFrame(Toasts.gui,{
BackgroundColor3 = Palette.ink3,
Size = UDim2.fromOffset(120,28),
ZIndex = 40,
Visible = false,
})
Corner(Tooltip.frame,8)
Stroke(Tooltip.frame,Palette.line2,0,1)
Tooltip.label = MakeLabel(Tooltip.frame,{
t = "",
f = Fonts.medium,
s = 12,
c = Palette.bone,
z = 41,
wrap = true,
pos = UDim2.fromOffset(10,0),
size = UDim2.new(1,-20,1,0),
})
end
local vec = MeasureText(text,12,Fonts.medium,240)
local width = math.ceil(vec.X)+ 22
local height = math.ceil(vec.Y)+ 14
local MouseLocation = UserInputService:GetMouseLocation()
local viewportSize = GetViewportSize()
local width2 = math.clamp(MouseLocation.X + 14,6,viewportSize.X - width - 6)
local height2 = MouseLocation.Y + 20
if viewportSize.Y - 6 < height2 + height then
height2 = MouseLocation.Y - height - 12
end
Tooltip.label.Text = text
Tooltip.frame.Size = UDim2.fromOffset(width,height)
Tooltip.frame.Position = UDim2.fromOffset(width2,height2 + 4)
Tooltip.frame.Visible = true
Fader.prime(Tooltip.frame)
Fader.to(Tooltip.frame,0,"hover",0.16)
Motion.to(Tooltip.frame,{Position = UDim2.fromOffset(width2,height2)},"hover",0.18)
return
end
end
function Tooltip.hide()
Tooltip.token = Tooltip.token + 1
if Tooltip.frame and Tooltip.frame.Parent and Tooltip.frame.Visible then
local frame = Tooltip.frame
Fader.to(frame,1,"exit",0.1)
local token = Tooltip.token
task.delay(0.11,function()
if token == Tooltip.token and frame.Parent then
frame.Visible = false
end
end)
end
end
function Tooltip.attach(guiButton,callback)
guiButton.MouseEnter:Connect(function()
Tooltip.token = Tooltip.token + 1
local token = Tooltip.token
task.delay(0.42,function()
if token ~= Tooltip.token or not guiButton.Parent or not guiButton.Visible then
return
end
local v = type(callback)== "function" and callback()or t(callback)
Tooltip.show(v)
end)
end)
guiButton.MouseLeave:Connect(Tooltip.hide)
if guiButton:IsA("GuiButton")then
guiButton.MouseButton1Down:Connect(Tooltip.hide)
end
end
