Down = "DOWN",
Left = "LEFT",
Right = "RIGHT",
}
function KeybindManager.label(Key)
if Key then
local Name = Key.Name
local v = map5[Name]
if v then
return v
end
local replaced = Name:gsub("^Keypad","NUM ")
return string.upper(replaced)
end
return t("key_none")
end
function KeybindManager.unregister(entriesByIdEntry)
if not entriesByIdEntry or not entriesByIdEntry.Key then
return
end
local list = Keybinds.ByKey[entriesByIdEntry.Key]
if list then
for i = #list,1,-1 do
if list[i] == entriesByIdEntry then
table.remove(list,i)
end
end
if #list == 0 then
Keybinds.ByKey[entriesByIdEntry.Key] = nil
end
end
entriesByIdEntry.Key = nil
end
function KeybindManager.assign(capturing,key)
if capturing.custom then
if capturing.apply then
local ok,result = pcall(capturing.apply,key)
if not ok then
warn("[DEDE/UI] key: " .. tostring(result))
end
end
if capturing.onChanged then
pcall(capturing.onChanged)
end
return
end
KeybindManager.unregister(capturing)
if key then
capturing.Key = key
local byKeyEntry = Keybinds.ByKey[key]
if not byKeyEntry then
byKeyEntry ={}
Keybinds.ByKey[key] = byKeyEntry
end
byKeyEntry[#byKeyEntry + 1] = capturing
end
if capturing.onChanged then
pcall(capturing.onChanged)
end
if Runtime.MarkAutoSaveDirty then
Runtime.MarkAutoSaveDirty()
end
end
function KeybindManager.register(id,trigger)
local entriesByIdEntry = Keybinds.EntriesById[id]
if entriesByIdEntry then
KeybindManager.unregister(entriesByIdEntry)
end
local entry ={Key = nil,Trigger = trigger,Id = id}
Keybinds.EntriesById[id] = entry
local PendingKeybinds = AutoSave and AutoSave.PendingKeybinds
local key = type(PendingKeybinds)== "table" and PendingKeybinds[id] or nil
if type(key)== "string" then
local ok,result = pcall(function()
return Enum.KeyCode[key]
end)
if ok and result then
entry.Key = result
local byKeyEntry = Keybinds.ByKey[result]
if not byKeyEntry then
byKeyEntry ={}
Keybinds.ByKey[result] = byKeyEntry
end
byKeyEntry[#byKeyEntry + 1] = entry
end
end
return entry
end
function KeybindManager.endCapture()
local capturing = KeybindManager.capturing
KeybindManager.capturing = nil
Keybinds.Capturing = nil
if capturing and capturing.onCaptureEnd then
pcall(capturing.onCaptureEnd)
end
if UI.setHint then
UI.setHint(nil)
end
return capturing
end
function KeybindManager.beginCapture(capturing)
if KeybindManager.capturing == capturing then
KeybindManager.endCapture()
return
end
if KeybindManager.capturing then
KeybindManager.endCapture()
end
KeybindManager.capturing = capturing
Keybinds.Capturing = capturing
if capturing.onCaptureStart then
pcall(capturing.onCaptureStart)
end
if UI.setHint then
UI.setHint("hint_capture")
end
end
TrackConnection(UserInputService.InputBegan:Connect(function(input,gameProcessed)
if input.UserInputType == UserInputType.Keyboard then
local capturing = KeybindManager.capturing
if capturing then
KeybindManager.endCapture()
local KeyCode = input.KeyCode
if KeyCode == Enum.KeyCode.Escape or KeyCode == Enum.KeyCode.Backspace or KeyCode == Enum.KeyCode.Delete then
KeybindManager.assign(capturing,nil)
else
KeybindManager.assign(capturing,KeyCode)
end
return
end
if gameProcessed or UserInputService:GetFocusedTextBox()then
return
end
local list = Keybinds.ByKey[input.KeyCode]
if list then
for _,value in ipairs(table.clone(list))do
if value and type(value.Trigger)== "function" then
task.defer(value.Trigger)
end
end
return
end
return
end
end))
