local delta = height - 1.7 * ratio
local ratio5 =(scaled - ratio4)/ 2
local ratio6 =(delta - scaled2)/ 2
for i = 0,math.floor(delta - scaled2)- 1 do
local scaled3 = 2 * ratio5 *(1 - math.abs(scaled2 + i + 0.5 - ratio3)/ ratio6)
if 0.6 < scaled3 then
New("Frame",{
BackgroundColor3 = backgroundColor32,
BorderSizePixel = 0,
Position = UDim2.fromOffset(ratio2 - scaled3 / 2,scaled2 + i),
Size = UDim2.fromOffset(scaled3,1.05),
