Parent = flagCanvas,
})
end
end
DrawLine(flagCanvas,ratio4,ratio3,ratio2,scaled2,1.3,backgroundColor32,zIndex + 1)
DrawLine(flagCanvas,ratio2,scaled2,scaled,ratio3,1.3,backgroundColor32,zIndex + 1)
DrawLine(flagCanvas,scaled,ratio3,ratio2,delta,1.3,backgroundColor32,zIndex + 1)
DrawLine(flagCanvas,ratio2,delta,ratio4,ratio3,1.3,backgroundColor32,zIndex + 1)
local scaled4 = 3.5 * ratio
