if math.sqrt(((map2[1] + value3)/ 2 - ratio2)^ 2 +((map2[2] + delta3)/ 2 - ratio3)^ 2)< scaled4 - scaled6 * 0.6 then
local inst = DrawLine(flagCanvas,map2[1],map2[2],value3,delta3,scaled6,Palette.white,zIndex + 3)
inst.Size = inst.Size + UDim2.fromOffset(0.6,0)
