local ambient = Screens.ambient
ambient.sweep.Position = UDim2.fromScale(-0.35 + 1.7 *(ratio < 0.62 and ratio / 0.62 or 1),0.5)
for _,mote in ipairs(ambient.motes)do
mote.y = mote.y - mote.v / 30
if mote.y < -0.05 then
mote.y = 1.05
end
mote.f.Position = UDim2.fromScale(mote.x + math.sin(delta * 0.4 + mote.sway)* 0.006,mote.y)
end
