function Screens.hide(callback)
if Screens.gui then
Fader.to(Screens.back,1,"exit",0.32)
Motion.to(Screens.blur,{Size = 0},"exit",0.3)
task.delay(0.34,function()
if Screens.gui and Screens.gui.Parent then
Screens.gui.Enabled = false
end
if callback then
callback()
end
end)
return
end
if callback then
callback()
end
end
local function FinishScreenSwap()
Screens.busy = false
local queued = Screens.queued
if queued then
Screens.queued = nil
Screens.swap(queued)
end
end
function Screens.swap(queued)
if Screens.busy then
Screens.queued = queued
return false
end
Screens.busy = true
Screens.ensure()
local screen = Screens.screen
local function RunQueuedScreen()
local ok,result = pcall(queued,Screens.layer)
if ok then
Screens.screen = result
if result.enter then
result.enter()
end
task.delay(0.25,FinishScreenSwap)
return
end
warn("[DEDE/UI] screen: " .. tostring(result))
Screens.screen = nil
FinishScreenSwap()
end
if screen and screen.leave then
screen.leave(function()
if screen.root and screen.root.Parent then
screen.root:Destroy()
end
RunQueuedScreen()
end)
else
RunQueuedScreen()
end
return true
end
