function bootScreen.run(value)
local now = os.clock()
value5 = 0
for i = 1,(value or 1)- 1 do
value5 = value5 +(bootSteps[i].weight or 1)
end
for j = value or 1,#bootSteps do
local stepIndex = j
if not layer.Parent or not Runtime.Running then
return
end
local step = bootSteps[stepIndex]
label4.Text = t(step.key)
SetStepState(stepIndex,"active")
local now2 = os.clock()
local ok,result,result2 = pcall(step.run,function(arg1,text)
SetProgress(stepIndex,arg1)
if text then
label4.Text = text
end
end)
if not ok then
result2 = tostring(result)
result = step.fatal and "fail" or "warn"
end
local kind = result or "ok"
if kind == "fail" then
ShowBootFailure(stepIndex,result2)
return
end
local elapsed = os.clock()- now2
if elapsed < 0.16 then
task.wait(0.16 - elapsed)
end
SetProgress(stepIndex,1)
value5 = value5 +(step.weight or 1)
SetStepState(stepIndex,(kind == "ok" or kind == "warn" or kind == "skip")and kind or "skip")
SetStatusText(result2 or t(step.key),kind == "warn" and Palette.warn or Palette.smoke)
end
local delta = 1.35 -(os.clock()- now)
if 0 < delta then
task.wait(delta)
end
if layer.Parent then
label4.Text = t("boot_ready")
label5.Text = "100%"
I18n.bind(label,"boot_ready")
Motion.to(frame4,{BackgroundColor3 = Palette.ok,BackgroundTransparency = 0},"hover")
Ticker.remove(bootScreen.spinId)
Motion.to(gradient,{Rotation = gradient.Rotation + 90},"base",0.4)
gradient.Transparency = NumberSequence.new(0)
Motion.to(stroke,{Color = Palette.emberHi},"base",0.3)
Motion.set(frame15,{BackgroundColor3 = Palette.bone})
Motion.to(frame15,{BackgroundColor3 = Palette.ember},"soft",0.6)
PlayRipple(frame5,Palette.ember,142,15)
task.wait(0.45)
if callback then
callback()
end
return
end
end
function bootScreen.leave(arg)
Ticker.remove(bootScreen.spinId)
Motion.to(uIScale,{Scale = 1.12},"exit",0.28)
FadeOutScreen(layer,arg,18)
end
task.delay(0.35,function()
if layer.Parent then
task.spawn(bootScreen.run,1)
end
end)
return bootScreen
end
end
