local function FindColorName(HitBoxColor)
if typeof(HitBoxColor)== "Color3" then
for _,predictorColor in ipairs(PredictorColors)do
if math.abs(HitBoxColor.R - predictorColor.Color.R)+ math.abs(HitBoxColor.G - predictorColor.Color.G)+ math.abs(HitBoxColor.B - predictorColor.Color.B)< 0.006 then
return predictorColor.Name
end
end
return nil
end
return nil
end
local function GetColorOptions()
local list ={}
