local function FormatDuration(elapsed)
local value = math.max(0,math.floor(elapsed))
local value2 = math.floor(value / 3600)
local value3 = math.floor(value / 60)% 60
local v = value % 60
if 0 < value2 then
return string.format("%dh %02dm",value2,value3)
end
if 0 < value3 then
return string.format("%dm %02ds",value3,v)
end
return string.format("%ds",v)
end
