local function ReadLobby(kind)
local ok,text = pcall(function()
return LocalPlayer.PlayerGui.Interface.Lobby[kind].TopPanel.DisplayName.Text
end)
if ok and type(text)== "string" and text ~= "" then
return text
end
return "—"
end
local state ={
model = nil,center = Vector3.zero,distance = 10,height = 5,
yaw = math.rad(20),targetYaw = math.rad(20),velocity = 0,spin = 0,
dragging = false,lastX = 0,lastMove = 0,idle = 0,
dirty = true,dirtyAt = 0,lastBuild = 0,signature = nil,building = false,
camCFrame = nil,
}
local REMOVE ={"BaseScript","Sound","BillboardGui","ForceField","BodyMover","ParticleEmitter","Trail","Beam",
"Highlight","SelectionBox","Animator","AnimationController","Fire","Smoke","Sparkles","Light","ProximityPrompt"}
local function ShouldRemove(inst)
for _,className in ipairs(REMOVE)do
if inst:IsA(className)then
return true
end
end
if inst:IsA("Constraint")and not inst:IsA("WeldConstraint")then
return true
end
return false
end
local function Clean(clone)
for _,inst in ipairs(clone:GetDescendants())do
if inst.Parent then
if ShouldRemove(inst)then
pcall(inst.Destroy,inst)
elseif inst:IsA("BasePart")then
if inst:GetAttribute("DEDE_HITBOX")or inst:GetAttribute("DEDE_HITBOX_VISUAL")or inst:GetAttribute("DEDE_LOCAL_BALL_VISUAL")or inst.Name:sub(1,12)== "CLIENT_BALL_" then
pcall(inst.Destroy,inst)
else
inst.Anchored = true
inst.CanCollide = false
inst.CanTouch = false
inst.CanQuery = false
inst.CastShadow = false
if inst.Name == "HumanoidRootPart" then
inst.Transparency = 1
end
end
end
end
end
local humanoid = clone:FindFirstChildOfClass("Humanoid")
if humanoid then
humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
humanoid.PlatformStand = true
pcall(function()humanoid.EvaluateStateMachine = false end)
end
end
local function Signature(character)
if not character then
return "none"
end
local list ={tostring(character)}
for _,child in ipairs(character:GetChildren())do
if child:IsA("Accessory")then
local handle = child:FindFirstChild("Handle")
local mesh = handle and(handle:IsA("MeshPart")and handle.MeshId or(handle:FindFirstChildOfClass("SpecialMesh")and handle:FindFirstChildOfClass("SpecialMesh").MeshId))or ""
list[#list + 1] = "A:" .. child.Name .. ":" .. tostring(mesh)
elseif child:IsA("Shirt")then
list[#list + 1] = "S:" .. child.ShirtTemplate
elseif child:IsA("Pants")then
list[#list + 1] = "P:" .. child.PantsTemplate
elseif child:IsA("ShirtGraphic")then
list[#list + 1] = "G:" .. child.Graphic
elseif child:IsA("BodyColors")then
list[#list + 1] = "B:" .. tostring(child.TorsoColor3).. tostring(child.HeadColor3)
elseif string.find(child.Name,"Jersey")then
list[#list + 1] = "J:" .. child.Name .. ":" .. #child:GetDescendants()
end
end
table.sort(list)
return table.concat(list,"|")
end
local function Rebuild(force)
if state.building then
return
end
local character = LocalPlayer.Character
local root = character and character:FindFirstChild("HumanoidRootPart")
local signature = Signature(root and character or nil)
state.dirty = false
state.lastBuild = os.clock()
if not force and state.model and signature == state.signature then
return
end
if not character or not root then
if state.model then
pcall(state.model.Destroy,state.model)
state.model = nil
end
state.signature = signature
emptyLabel.Visible = true
return
end
state.building = true
local archivable = character.Archivable
character.Archivable = true
local ok,clone = pcall(character.Clone,character)
character.Archivable = archivable
if not ok or not clone then
state.building = false
emptyLabel.Visible = state.model == nil
return
end
Clean(clone)
clone.Name = "Preview"
local cloneRoot = clone:FindFirstChild("HumanoidRootPart")
if cloneRoot then
clone.PrimaryPart = cloneRoot
pcall(function()
clone:PivotTo(CFrame.new(0,0,0))
end)
end
clone.Parent = worldModel
local old = state.model
state.model = clone
state.signature = signature
if old then
pcall(old.Destroy,old)
end
emptyLabel.Visible = false
local okBox,boxCFrame,boxSize = pcall(clone.GetBoundingBox,clone)
if okBox and boxCFrame then
state.center = boxCFrame.Position
state.height = math.max(boxSize.Y,2)
local fit = math.max(boxSize.Y,boxSize.X * 1.3)* 0.5
state.distance = fit / math.tan(math.rad(camera.FieldOfView * 0.5))+ 1.5
end
nameLabel.Text = LocalPlayer.DisplayName
state.building = false
end
local function MarkDirty(child)
if child == nil or child:IsA("Accessory")or child:IsA("Clothing")or child:IsA("ShirtGraphic")
or child:IsA("BodyColors")or child:IsA("CharacterMesh")or string.find(child.Name,"Jersey")then
state.dirty = true
state.dirtyAt = os.clock()
end
end
Builder.iconButton(refreshHolder,"refresh",8,"tip_avrefresh",function()
Rebuild(true)
end,34)
viewport.InputBegan:Connect(function(input)
if IsPrimaryInput(input)then
state.dragging = true
state.lastX = input.Position.X
state.lastMove = os.clock()
state.velocity = 0
state.input = input
end
end)
TrackConnection(UserInputService.InputChanged:Connect(function(input)
if not state.dragging then
return
end
if input.UserInputType == UserInputType.MouseMovement or(state.input and state.input.UserInputType == UserInputType.Touch and input == state.input)then
local now = os.clock()
local delta =(input.Position.X - state.lastX)* -0.012
local elapsed = math.max(now - state.lastMove,1 / 240)
state.lastX = input.Position.X
state.lastMove = now
state.targetYaw = state.targetYaw + delta
state.velocity = state.velocity * 0.6 +(delta / elapsed)* 0.4
state.idle = now
end
end))
TrackConnection(UserInputService.InputEnded:Connect(function(input)
if state.dragging and IsPrimaryInput(input)then
state.dragging = false
if os.clock()- state.lastMove > 0.08 then
state.velocity = 0
end
state.velocity = math.clamp(state.velocity,-12,12)
state.idle = os.clock()
end
end))
local charConns ={}
local function WatchCharacter(character)
for _,conn in ipairs(charConns)do
pcall(conn.Disconnect,conn)
end
charConns ={}
state.dirty = true
state.dirtyAt = os.clock()
if character then
charConns[1] = character.ChildAdded:Connect(MarkDirty)
charConns[2] = character.ChildRemoved:Connect(MarkDirty)
end
end
TrackConnection(LocalPlayer.CharacterAdded:Connect(function(character)
task.wait(0.6)
WatchCharacter(character)
end))
WatchCharacter(LocalPlayer.Character)
local lastInfo = 0
local loop
loop = TrackConnection(RunService.RenderStepped:Connect(function(dt)
if not panel.Parent then
loop:Disconnect()
for _,conn in ipairs(charConns)do
pcall(conn.Disconnect,conn)
end
return
end
if not panel.Visible or not UI.visible then
return
end
dt = math.min(dt,1 / 20)
local now = os.clock()
if state.dirty and now - state.dirtyAt > 1 and now - state.lastBuild > 1.5 then
state.dirty = false
task.defer(Rebuild,false)
end
if not state.dragging then
if math.abs(state.velocity)> 0.01 then
state.targetYaw = state.targetYaw + state.velocity * dt
state.velocity = state.velocity * math.exp(-dt * 4)
else
state.velocity = 0
end
local wantSpin =(now - state.idle > 2)and 0.35 or 0
state.spin = state.spin +(wantSpin - state.spin)*(1 - math.exp(-dt * 2))
state.targetYaw = state.targetYaw + state.spin * dt
end
state.yaw = state.yaw +(state.targetYaw - state.yaw)*(1 - math.exp(-dt * 14))
local focus = state.center
local orbit = CFrame.new(focus)* CFrame.Angles(0,state.yaw,0)* CFrame.new(0,state.height * 0.08,-state.distance)
local cf = CFrame.lookAt(orbit.Position,focus)
local fastEnough = state.dragging or math.abs(state.targetYaw - state.yaw)> 0.15 or math.abs(state.velocity)> 0.05
if(fastEnough or now -(state.lastCam or 0)>= 1 / 30)and(not state.camCFrame or(cf.Position - state.camCFrame.Position).Magnitude > 1e-4)then
state.lastCam = now
state.camCFrame = cf
camera.CFrame = cf
end
if now - lastInfo > 1 then
lastInfo = now
local styleText,abilityText = ReadLobby("Styles"),ReadLobby("Abilities")
if styleLabel.Text ~= styleText then
styleLabel.Text = styleText
end
if abilityLabel.Text ~= abilityText then
abilityLabel.Text = abilityText
end
end
end))
hint.Visible = true
return panel
end
