ElasticBehavior = Enum.ElasticBehavior.WhenScrollable,
AutomaticCanvasSize = Enum.AutomaticSize.None,
Visible = false,
ZIndex = 7,
Name = def.id,
Parent = UI.view,
})
local grid ={
id = def.id,
def = def,
accent = def.accent,
scroll = scrollingFrame,
sections ={},
colH ={0,0},
wideH = 0,
cols ={},
}
local label = MakeLabel(scrollingFrame,{
t = "",
f = Fonts.medium,
s = 13,
c = Palette.smoke,
xa = TextXAlignment2.Center,
pos = UDim2.fromOffset(0,40),
size = UDim2.new(1,0,0,20),
z = 8,
})
label.Visible = false
grid.empty = label
function grid.recalc()
local height =(grid.wide and grid.wideH + 16 or 0)+ 18
for i,col in ipairs(grid.cols)do
col.Position = UDim2.fromOffset(24 +(i - 1)*(contentWidth + 16),height)
end
local value = math.max(grid.colH[1],grid.colH[2])
scrollingFrame.CanvasSize = UDim2.fromOffset(0,height + value + 28)
end
for i = 1,2 do
local key = i
local frame = MakeFrame(scrollingFrame,{
BackgroundTransparency = 1,
Size = UDim2.fromOffset(contentWidth,0),
ZIndex = 7,
Name = "Col" .. key,
})
VerticalList(frame,16)
grid.cols[key] = frame
Builder.autoStack(frame,16,function(height)
frame.Size = UDim2.fromOffset(contentWidth,height)
grid.colH[key] = height
grid.recalc()
end)
end
grid.recalc()
UI.pages[def.id] = grid
UI.order[#UI.order + 1] = grid
return grid
end
