function UI.refreshActive()
local page = UI.current and UI.pages[UI.current]
if page and UI.activeLabel then
local value = 0
for _,section in ipairs(page.sections)do
for _,opts in ipairs(section.toggles)do
if opts.get()then
value = value + 1
end
end
end
UI.activeLabel.Text = t("active_n",value)
Motion.to(UI.activeDot,{BackgroundColor3 = 0 < value and page.accent or Palette.dim},"hover")
Motion.to(UI.activeLabel,{TextColor3 = 0 < value and Palette.bone or Palette.smoke},"hover")
end
UI.refreshDock()
end
function UI.applySearch(Text)
local page = UI.current and UI.pages[UI.current]
if page then
local query = string.lower((tostring(Text or ""):gsub("^%s+",""):gsub("%s+$","")))
local flag = false
for _,section in ipairs(page.sections)do
local v = query ~= "" and string.find(string.lower(section.titleLabel.Text .. " " .. section.subLabel.Text),query,1,true)~= nil
local value = 0
for _,row in ipairs(section.rows)do
local visible = query == "" or v or row.searchText and string.find(row.searchText(),query,1,true)~= nil or false
if row.shown and not row.shown()then
visible = false
end
row.frame.Visible = visible
if visible then
value = value + 1
end
end
section.card.Visible = query == "" or 0 < value
if section.card.Visible then
flag = true
end
section.refreshDividers()
end
if page.wide then
page.wide.Visible = query == ""
end
page.empty.Visible = query ~= "" and not flag
if page.empty.Visible then
page.empty.Text = t("search_empty",Text)
end
page.recalc()
return
end
end
function UI.select(current,arg2)
local page = UI.pages[current]
if not page or UI.current == current then
return
end
local current2 = UI.current
local nextPage = current2 and UI.pages[current2]
local value2 = 1
if nextPage then
local value3 = 0
local value4 = 0
for i,value in ipairs(UI.order)do
if value == nextPage then
value3 = i
end
if value == page then
value4 = i
end
end
value2 = value3 <= value4 and 1 or -1
end
UI.current = current
UI.accent = page.accent
if UI.activePicker then
UI.activePicker.setOpen(false,true)
UI.activePicker = nil
end
local tabFor = UI.tabFor(current)
for _,tab in ipairs(UI.tabs)do
local v = tab.id == current
Motion.to(tab.label,{TextColor3 = v and Palette.bone or Palette.smoke},"hover")
RecolorStrokes(tab.glyph,v and page.accent or Palette.smoke,"hover")
end
local tbl ={Position = UDim2.fromOffset(tabFor.x,4),Size = UDim2.fromOffset(tabFor.w,32)}
if arg2 or not nextPage then
Motion.set(UI.tabIndicator,tbl)
else
Motion.to(UI.tabIndicator,tbl,"swift",0.34)
end
Motion.to(UI.tabUnderline,{BackgroundColor3 = page.accent},"hover")
I18n.bind(UI.subEyebrow,page.def.eyebrow)
I18n.bind(UI.subTitle,page.def.title)
I18n.bind(UI.subDesc,page.def.desc)
UI.subEyebrow.TextColor3 = page.accent
if not arg2 and nextPage then
for _,inst in ipairs({UI.subEyebrow,UI.subTitle,UI.subDesc})do
local Position = inst.Position
Motion.set(inst,{TextTransparency = 1,Position = Position + UDim2.fromOffset(10 * value2,0)})
Motion.to(inst,{TextTransparency = 0,Position = Position},"enter",0.4)
end
end
local function ShowPage()
if nextPage then
nextPage.scroll.Visible = false
end
page.scroll.Visible = true
UI.applySearch(UI.searchBox and UI.searchBox.Text or "")
end
if arg2 or not nextPage then
ShowPage()
Motion.set(UI.veil,{BackgroundTransparency = 1})
else
Motion.to(UI.veil,{BackgroundTransparency = 0},"micro",0.1)
task.delay(0.1,function()
if UI.current == current then
ShowPage()
page.scroll.Position = UDim2.fromOffset(28 * value2,0)
Motion.to(page.scroll,{Position = UDim2.fromOffset(0,0)},"enter",0.42)
Motion.to(UI.veil,{BackgroundTransparency = 1},"base",0.32)
return
end
end)
end
UI.refreshActive()
end
