UI.revert ={
at = nil,
SAFE = 20,
LATE = 25,
LINGER = 8,
slots ={"hudView","panelView"},
hudOn = false,
}
function UI.revert.phase(now)
local revert = UI.revert
if revert.at then
local delta =(now or os.clock())- revert.at
if delta < revert.SAFE then
local value = math.max(1,math.ceil(revert.SAFE - delta))
return "run",value,1 - delta / revert.SAFE,10 < value and Palette.volt or 5 < value and Palette.warn or Palette.err
end
return delta < revert.LATE and "risk" or "late",0,0,Palette.err
end
return "off",0,0,Palette.dim
end
function UI.revert.texts(kind)
if kind == "run" then
return "rv_run","rv_run_b"
end
if kind == "risk" then
return "rv_risk","rv_risk_b"
end
return "rv_late","rv_late_b"
end
function UI.revert.paint(now)
local revert = UI.revert
local now2 = now or os.clock()
local v,v2,v3,v4 = revert.phase(now2)
for _,key in ipairs(revert.slots)do
local fn = revert[key]
if fn then
local ok,result = pcall(fn,v,v2,v3,v4,now2)
if not ok then
warn("[DEDE/UI] revert view: " .. tostring(result))
end
end
end
return v
end
function UI.revert.leave()
pcall(function()
LocalPlayer:Kick(t("rv_kick"))
end)
end
function UI.revert.rejoin()
local fm = UI.V3("FM")
if not fm or not fm.Rejoin then
return false
end
task.delay(0.3,function()
pcall(fm.Rejoin)
end)
return true
end
function UI.revert.rejoinDelay()
return math.clamp(math.floor(tonumber(Config.RG_RevertRejoinDelay)or 2),1,18)
end
function UI.revert.scheduleRejoin()
local revert = UI.revert
local token =(revert.rejoinToken or 0)+ 1
revert.rejoinToken = token
local startedAt = revert.at
task.delay(revert.rejoinDelay(),function()
if revert.rejoinToken ~= token or not revert.at or revert.at ~= startedAt then
return
end
Toasts.push("info",t("r_autorejoin"),t("r_autorejoin_b"))
if not revert.rejoin()then
Toasts.push("warn",t("c_rejoin"),t("r_v3missing"))
return
end
task.delay(6,function()
if revert.rejoinToken == token and revert.at == startedAt then
revert.rejoin()
end
end)
end)
end
