function UI.revert.toastShift(arg)
if not pcall(Toasts.ensure)or not Toasts.holder then
return
end
local height = arg and 16 + math.floor(86 *(UI.revert.hudScale and UI.revert.hudScale.Scale or 1)+ 0.5)or 16
Motion.to(Toasts.holder,{Position = UDim2.new(0.5,0,0,height)},"base",0.3)
end
function UI.revert.hudShow(enabled)
local revert = UI.revert
local hudOn = enabled and true or false
if hudOn and not(revert.hud and revert.hud.Parent)then
local revert2 = revert
local revert3 = revert
revert2.hud = nil
revert3.hudOn = false
local ok,result = pcall(revert.hudBuild)
if not ok then
warn("[DEDE/UI] revert timer: " .. tostring(result))
return
end
end
if hudOn == revert.hudOn or not revert.hudCard then
return
end
revert.hudOn = hudOn
local hudCard = revert.hudCard
if hudOn then
hudCard.Visible = true
hudCard.Position = UDim2.fromOffset(0,-14)
Motion.to(hudCard,{Position = UDim2.fromOffset(0,0)},"pop",0.36)
else
Motion.to(hudCard,{Position = UDim2.fromOffset(0,-14)},"exit",0.18)
task.delay(0.2,function()
if not revert.hudOn and hudCard.Parent then
hudCard.Visible = false
end
end)
end
revert.toastShift(hudOn)
end
function UI.revert.start()
local revert = UI.revert
revert.at = os.clock()
revert.hudShow(true)
if not revert.tickId then
local value = 0
revert.tickId = Ticker.add(function(value2)
if revert.at then
if value2 - value < 0.1 then
return
end
value = value2
revert.paint(value2)
if revert.LATE + revert.LINGER < value2 - revert.at then
revert.hudShow(false)
revert.tickId = nil
return false
end
return
end
revert.tickId = nil
return false
end)
end
revert.paint()
end
function UI.revert.stop()
local revert = UI.revert
revert.at = nil
if revert.tickId then
Ticker.remove(revert.tickId)
revert.tickId = nil
end
revert.hudShow(false)
revert.paint()
end
function UI.aimAvailable(kind)
local aim = UI.Aim()
if not aim or type(aim.Available)~= "function" then
return false
end
local ok,result = pcall(aim.Available,kind)
return ok and result == true
end
function UI.Aim()
local ok,result = pcall(function()
return genv.DEDE_AIM
end)
if ok then
return result
end
return nil
end
function UI.aimRefresh()
local aim = UI.Aim()
if aim and aim.Refresh then
local ok,result = pcall(aim.Refresh)
if not ok then
warn("[DEDE/UI] aim refresh: " .. tostring(result))
end
return true
end
return false
end
