pcall(SetPredictorHighlightTransparency,Config.PredictorHighlightTransparency)
pcall(HitboxVisuals.Toggle,Config.HitBoxExpander)
pcall(MovementToggle.Toggle,Config.AutoShiftLockJump)
pcall(AutoServe.Toggle,Config.AutoServe)
pcall(Features.ToggleAutoReceive,Config.AutoReceive)
pcall(YLock.Toggle,Config.FastSpike)
pcall(SetViewSpike,Config.ViewSpike)
pcall(Features.ToggleMaxPower,Config.MaxPower)
pcall(Features.ToggleFakeSpike,Config.FakeSpike)
Runtime.ActiveFeatures.FakeSpikeRandomizer = Config.FakeSpike and Config.FakeSpikeRandomizer or false
pcall(Features.ToggleNoAnims,Config.NoAnims)
pcall(Features.ToggleKisukiDive,Config.KisukiDive)
pcall(AutoSave.Toggle,Config.AutoSaveLoad)
Runtime.ActiveFeatures.TimeskipHintoHitEffect = Config.TimeskipHintoHitEffect and true or false
Runtime.ActiveFeatures.HidariHitEffect = Config.HidariHitEffect and true or false
Runtime.ActiveFeatures.OkazuHitEffect = Config.OkazuHitEffect and true or false
pcall(Refresher.Refresh)
pcall(NameChanger.Toggle,Config.NameChanger)
pcall(SetPredictorEnabled,Config.PredictorEnabled)
pcall(PointView.SetEnabled,Config.PointView)
pcall(function()
SetPredictorColor(FindPresetColor(Config.PredictorColorName))
end)
pcall(Features.Performance.SetImpactEffects,Config.AntiLagImpactEffects,true)
pcall(Features.Performance.Toggle,Config.AntiLagApplied,true)
if Config.AutoCornerMode == "hook" and Config.AutoPixelMode == "hook" then
Config.AutoPixelMode = "key"
end
if Config.AutoCornerKey == Config.AutoPixelKey then
Config.AutoPixelKey = Config.AutoCornerKey == "C" and "V" or "C"
end
Runtime.ActiveFeatures.AutoCorner = Config.AutoCornerEnabled and true or false
Runtime.ActiveFeatures.AutoPixel = Config.AutoPixelEnabled and true or false
Runtime.ActiveFeatures.PerfectSet = Config.PerfectSetEnabled and true or false
Runtime.ActiveFeatures.Counter = Config.CounterEnabled and true or false
Config.FarmRevertEnabled = UI.revert.at ~= nil
Runtime.ActiveFeatures.FarmRevert = Config.FarmRevertEnabled
pcall(function()
local api = genv.REAL_GG
if type(api)== "table" and api.ApplyConfig then
api.ApplyConfig(Config)
end
end)
UI.aimRefresh()
StatusCard.force()
UI.syncAll()
end
function UI.syncAll()
for _,control in ipairs(UI.controls)do
if control.render then
pcall(control.render,false)
end
if control.sync then
pcall(control.sync)
end
end
for _,value in ipairs(UI.order)do
for _,section in ipairs(value.sections)do
section.refreshCounter()
end
end
UI.refreshActive()
end
function UI.reconcile()
for _,opts in ipairs(UI.controls)do
if opts.render and opts.get then
local lastRendered = opts.get()and true or false
if lastRendered ~= opts.lastRendered then
opts.lastRendered = lastRendered
pcall(opts.render,true)
if opts.section and opts.section.refreshCounter then
opts.section.refreshCounter()
end
end
end
end
UI.refreshActive()
end
