local str = tostring(status.Target or "?")
if status.Phase == "window" then
liveRow(t("cs_window",str),Palette.warn)
elseif status.Phase == "sent" then
liveRow(t("cs_sent",status.Sends or 0,status.MaxSends or 4,str),page.accent)
elseif v and status.Age < 3 then
local ok = status.Phase == "confirmed" and Palette.ok or status.Phase == "teammate" and Palette.frost or Palette.warn
liveRow(t("cs_" .. status.Phase,str),ok)
else
liveRow(t("cs_idle"),Palette.ok)
end
else
liveRow(t("cs_notouch"),Palette.warn)
end
if Config.CounterTeamCheck then
if not status or not status.TeamName then
liveRow2(t("ts_none"),Palette.warn)
else
liveRow2(t("ts_team",status.TeamName,status.Mates or 0),Palette.ok)
end
else
liveRow2(t("ts_off"),Palette.dim)
end
end
UI.counterStatus()
end)
