descKey = "c_autosave_d",
get = function()
return Config.AutoSaveLoad
end,
set = function(value)
AutoSave.Toggle(value)
end,
})
local inputRow = Builder.inputRow(section,{
titleKey = "c_cfgname",
placeholderKey = "c_cfgname_ph",
get = function()
return UI.cfgName or "MeuSetup"
end,
commit = function(value)
UI.cfgName = value
end,
})
local list ={}
local function RefreshConfigList()
list = Runtime.ListSavedConfigs()
return list
end
RefreshConfigList()
UI.cfgSelected = list[1]
local pickerRow = Builder.pickerRow(section,{
titleKey = "c_cfglist",
descKey = "c_cfglist_d",
style = "chips",
options = function()
if #list == 0 then
return{{name = "__none",labelKey = "cfg_none"}}
end
local list2 ={}
for _,name in ipairs(list)do
list2[#list2 + 1] ={name = name}
end
return list2
end,
current = function()
return #list == 0 and "__none" or(UI.cfgSelected or "__none")
end,
pick = function(value)
if value.name == "__none" then
return
end
UI.cfgSelected = value.name
UI.cfgName = value.name
inputRow.set(value.name)
end,
})
local function SelectConfig(cfgSelected)
RefreshConfigList()
if cfgSelected and table.find(list,cfgSelected)then
UI.cfgSelected = cfgSelected
elseif not UI.cfgSelected or not table.find(list,UI.cfgSelected)then
UI.cfgSelected = list[1]
end
pickerRow.refresh()
end
local function GetSelectedConfig()
local cfgSelected = UI.cfgSelected
if cfgSelected and cfgSelected ~= "__none" and table.find(list,cfgSelected)then
return cfgSelected
end
return nil
end
local function ConfigExists(item)
if typeof(isfile)== "function" then
local ok,exists = pcall(isfile,ConfigFolder .. "/" .. item .. ".json")
return ok and exists == true
end
return table.find(list,item)~= nil
end
local map ={}
local function ConfirmTwice(key,name)
local v = map[key]
local now = os.clock()
if v and v.name == name and now <= v.expires then
map[key] = nil
return true
end
map[key] ={name = name,expires = now + 3}
return false
end
Builder.actionRow(section,{
id = "BUTTON:Create Config",
titleKey = "c_cfgcreate",
descKey = "c_cfgcreate_d",
run = function()
local configName = Runtime.NormalizeConfigName(inputRow.get())
if configName then
if ConfigExists(configName)then
return "warn",t("r_exists",configName)
end
local v,text,v2 = SaveConfig(configName)
if v then
local cfgName = v2 or configName
UI.cfgName = cfgName
inputRow.set(cfgName)
SelectConfig(cfgName)
Toasts.push("ok",t("c_cfgcreate"),t("r_created",cfgName))
return "ok",t("r_created",cfgName)
end
return "err",t("r_savefail",tostring(text))
end
return "warn",t("r_noname")
end,
})
Builder.actionRow(section,{
id = "BUTTON:Delete Config",
titleKey = "c_cfgdelete",
descKey = "c_cfgdelete_d",
run = function()
local selectedConfig = GetSelectedConfig()
if selectedConfig then
if typeof(delfile)== "function" then
if ConfirmTwice("delete",selectedConfig)then
local ok,result = pcall(delfile,ConfigFolder .. "/" .. selectedConfig .. ".json")
if ok then
SelectConfig(nil)
Toasts.push("ok",t("c_cfgdelete"),t("r_deleted",selectedConfig))
return "ok",t("r_deleted",selectedConfig)
end
return "err",t("err_generic",tostring(result))
end
return "warn",t("r_confirm_delete",selectedConfig)
end
return "err",t("r_nodelete")
end
return "warn",t("r_noselect")
end,
})
Builder.actionRow(section,{
id = "BUTTON:Overwrite Config",
titleKey = "c_cfgoverwrite",
descKey = "c_cfgoverwrite_d",
run = function()
local selectedConfig = GetSelectedConfig()
if selectedConfig then
if ConfirmTwice("overwrite",selectedConfig)then
local v,text = SaveConfig(selectedConfig)
if v then
SelectConfig(selectedConfig)
Toasts.push("ok",t("c_cfgoverwrite"),t("r_overwritten",selectedConfig))
return "ok",t("r_overwritten",selectedConfig)
end
return "err",t("r_savefail",tostring(text))
end
return "warn",t("r_confirm_overwrite",selectedConfig)
end
return "warn",t("r_noselect")
end,
})
Builder.actionRow(section,{
id = "BUTTON:Load Settings",
titleKey = "c_cfgload",
descKey = "c_cfgload_d",
run = function()
local configName = GetSelectedConfig()or Runtime.NormalizeConfigName(inputRow.get())
if configName then
local v,text,v2 = LoadConfig(configName)
if v then
local cfgName = v2 or configName
UI.cfgName = cfgName
inputRow.set(cfgName)
UI.applyLoadedConfig()
Toasts.push("ok",t("c_cfgload"),t("r_loaded",cfgName))
return "ok",t("r_loaded",cfgName)
end
Toasts.push("err",t("c_cfgload"),t("r_loadfail",tostring(text or configName)))
return "err",t("r_loadfail",tostring(text or configName))
end
return "warn",t("r_noselect")
end,
})
end)
