f = Fonts.medium,
s = 12,
c = Palette.ash,
pos = UDim2.fromOffset(150,0),
size = UDim2.new(1,-160,1,0),
trunc = Enum.TextTruncate.AtEnd,
z = 5,
})
function customRow.searchText()
return string.lower(label.Text)
end
function UI.ballStatus()
local BallSequence = BallCosmetics and BallCosmetics.BallSequence
local str = nil
local v,warn3
if UnlockState.EnabledTypes.Balls then
if BallSequence and BallSequence.PendingWorkspace then
local str2 = tostring(BallSequence.Generation)
local warn2 = Palette.warn
v = "bs_armed"
str = str2
warn3 = warn2
elseif BallSequence and BallSequence.WorkspaceTarget and BallSequence.WorkspaceTarget.Parent then
local Name = BallSequence.WorkspaceTarget.Name
local ok = Palette.ok
v = "bs_attached"
str = Name
warn3 = ok
elseif BallSequence and BallSequence.HeldTarget and BallSequence.HeldTarget.Parent then
local frost = Palette.frost
v = "bs_held"
warn3 = frost
else
local accent = page.accent
v = "bs_waiting"
warn3 = accent
end
else
local dim = Palette.dim
v = "bs_disabled"
warn3 = dim
end
local text = str and t(v,str)or t(v)
if label.Text ~= text then
label.Text = text
end
if frame2.BackgroundColor3 ~= warn3 then
Motion.to(frame2,{BackgroundColor3 = warn3},"hover")
Motion.to(label,{TextColor3 = warn3:Lerp(Palette.ash,0.4)},"hover")
end
end
UI.ballStatus()
end)
