local RGFilter ={}
local RGPickers ={}
local function RGApi()
local api = genv.REAL_GG
if type(api)== "table" and api.Running then
return api
end
return nil
end
local function RGBindCallbacks()
local api = RGApi()
if not api then
return
end
api.Notify = function(msg,kind)
Toasts.push(kind or "info","Real Hub",tostring(msg))
end
pcall(api.SyncParams,Config)
api.OnListReady = function(kind)
local row = RGPickers[kind]
if row and row.refresh then
pcall(row.refresh)
end
end
api.OnOff = function(key)
Config["RG_" .. tostring(key)] = false
if Runtime.MarkAutoSaveDirty then
Runtime.MarkAutoSaveDirty()
end
if UI.reconcile then
pcall(UI.reconcile)
end
end
end
local function RGMissing(section)
Builder.noteRow(section,{titleKey = "rg_missing",bodyKey = "rg_missing_b",icon = "alert",accent = Palette.warn})
end
local function RGToggle(section,id,titleKey,descKey,key,apply)
return Builder.toggleRow(section,{
id = id,
titleKey = titleKey,
descKey = descKey,
get = function()
return Config[key]
end,
set = function(value)
Config[key] = value and true or false
local api = RGApi()
if api and apply then
local ok,err = pcall(apply,api,Config[key])
if not ok then
warn("[REAL/RG] " .. tostring(err))
end
end
end,
})
end
local function RGSlider(section,titleKey,min,max,decimals,key,apply)
return Builder.sliderRow(section,{
titleKey = titleKey,
min = min,
max = max,
decimals = decimals,
get = function()
return Config[key]
end,
set = function(value)
Config[key] = value
local api = RGApi()
if api and apply then
pcall(apply,api,value)
end
end,
})
end
local function RGAction(section,id,titleKey,descKey,popout,fn)
return Builder.actionRow(section,{
id = id,
titleKey = titleKey,
descKey = descKey,
popout = popout,
run = function(row)
local api = RGApi()
if not api then
return "err",t("rg_missing")
end
local result,msg = fn(api,row)
if result == false then
return "err",msg and tostring(msg)or t("rg_fail")
elseif result == "warn" then
return "warn",msg and tostring(msg)or t("rg_fail")
end
return "ok",msg and tostring(msg)or t("rg_done")
end,
})
end
local function RGChoice(section,titleKey,descKey,items,key,apply)
return Builder.pickerRow(section,{
titleKey = titleKey,
descKey = descKey,
style = "chips",
options = function()
local list ={}
for _,item in ipairs(items)do
list[#list + 1] = type(item)== "table" and item or{name = item}
end
return list
end,
current = function()
return Config[key]
end,
pick = function(value)
Config[key] = value.name
local api = RGApi()
if api and apply then
pcall(apply,api,value.name)
end
end,
})
end
local function RGListPicker(section,titleKey,descKey,kind,key,apply)
local pickerRow = nil
Builder.inputRow(section,{
titleKey = "rg_filter",
placeholderKey = "rg_filter_ph",
get = function()
return RGFilter[kind] or ""
end,
commit = function(value)
RGFilter[kind] = tostring(value or "")
if pickerRow then
pickerRow.refresh()
end
end,
})
pickerRow = Builder.pickerRow(section,{
titleKey = titleKey,
descKey = descKey,
style = "chips",
options = function()
local list ={}
local api = RGApi()
local names = api and api.List(kind)or{}
local filter = string.lower(RGFilter[kind] or "")
local current = Config[key]
if type(current)== "string" and current ~= "" then
list[1] ={name = current}
end
for _,name in ipairs(names)do
if #list >= 24 then
break
end
if name ~= current and(filter == "" or string.find(string.lower(name),filter,1,true))then
list[#list + 1] ={name = name}
end
end
return list
