function UI.build(callback)
if UI.state == "ready" then
return true
end
if UI.state == "building" then
while true do
task.wait()
if UI.state ~= "building" then
break
end
end
if UI.state ~= "ready" then
error("control center build failed",0)
end
return true
end
if UI.gui then
UI.teardown()
end
UI.state = "building"
local ok,result = pcall(function()
UI.buildShell()
for _,bootFlag in ipairs(bootFlags)do
UI.newPage(bootFlag)
end
local pageDefinitions = BuildPageDefinitions()
for i,pageDefinition in ipairs(pageDefinitions)do
local v = UI.pages[pageDefinition.page]
pageDefinition.fn(v,v.cols[pageDefinition.col])
if callback then
callback(i,#pageDefinitions)
end
RunService.Heartbeat:Wait()
end
UI.sectionsBuilt = #pageDefinitions
UI.select("MAIN",true)
UI.syncAll()
UI.paintFooter()
end)
if ok then
UI.state = "ready"
UI.built = true
return true
end
UI.state = "failed"
error(result,0)
end
function UI.paintFooter()
if UI.saveLabel then
local flag = Config.AutoSaveLoad and true or false
UI.saveLabel.Text = t(flag and "autosave_on" or "autosave_off")
UI.saveDot.BackgroundColor3 = flag and Palette.ok or Palette.dim
local X = MeasureText(UI.saveLabel.Text,10,Fonts.mono).X
UI.saveDot.Position = UDim2.new(1,-24 - X - 10,0.5,0)
return
end
end
function UI.applyBackdrop()
if UI.gui then
local backdrop = UI.visible and Prefs.backdrop
Motion.to(UI.dim,{BackgroundTransparency = backdrop and 0.5 or 1},"base",0.35)
Motion.to(UI.blur,{Size = 0},"base",0.35)
return
end
end
function UI.startTicker()
if UI.tickId then
return
end
local value = 0
local value2 = 0
UI.tickId = Ticker.add(function(value3)
if not UI.gui or not UI.gui.Parent then
UI.tickId = nil
return false
end
if UI.visible then
if 0.25 <= value3 - value2 then
value2 = value3
if UI.current == "VISUAL" and UI.ballStatus then
pcall(UI.ballStatus)
end
if UI.current == "MAIN" then
if UI.receiveStatus then
pcall(UI.receiveStatus)
end
if UI.counterStatus then
pcall(UI.counterStatus)
end
end
end
if 1 <= value3 - value then
value = value3
local pingMs = GetPingMs()
UI.pingLabel.Text = tostring(pingMs).. " ms"
RecolorStrokes(UI.pingGlyph,pingMs < 90 and Palette.ok or pingMs < 180 and Palette.warn or Palette.err)
UI.reconcile()
UI.paintFooter()
if UI.current == "FARM" and UI.sessionTick then
pcall(UI.sessionTick)
end
end
return
end
end)
end
function UI.show()
if not UI.built or not UI.gui then
return
end
if UI.visible and UI.mount.Visible then
return
end
UI.visible = true
UI.gui.Enabled = true
local mount = UI.mount
local winVeil = UI.winVeil
if UI.dock.Visible then
local dock = UI.dock
Motion.to(UI.dockScale,{Scale = 0.6},"exit",0.16)
task.delay(0.16,function()
if not UI.dockShown then
dock.Visible = false
end
end)
end
UI.dockShown = false
mount.Visible = true
for _,value in ipairs({UI.top,UI.sub,UI.view,UI.foot})do
value.Visible = true
end
Motion.set(winVeil,{BackgroundTransparency = 0})
Motion.set(UI.animScale,{Scale = 0.94})
Motion.set(UI.shell,{BackgroundTransparency = 1})
Motion.set(UI.shellStroke,{Transparency = 1})
Fader.to(UI.shadow,1,nil,0)
Motion.set(UI.underglow,{BackgroundTransparency = 1})
Motion.to(UI.animScale,{Scale = 1},"pop",0.42)
Motion.to(UI.shell,{BackgroundTransparency = 0},"base",0.2)
Motion.to(UI.shellStroke,{Transparency = 0.2},"base",0.3)
Fader.to(UI.shadow,0,"base",0.4)
Motion.to(UI.underglow,{BackgroundTransparency = 0.92},"soft",0.6)
task.delay(0.12,function()
if UI.visible then
Motion.to(winVeil,{BackgroundTransparency = 1},"base",0.34)
end
end)
UI.applyBackdrop()
UI.syncAll()
UI.startTicker()
end
