end
Motion.to(UI.animScale,{Scale = 0.95},"exit",0.2)
Motion.to(winVeil,{BackgroundTransparency = 1},"exit",0.2)
Motion.to(UI.shell,{BackgroundTransparency = 1},"exit",0.2)
Motion.to(UI.shellStroke,{Transparency = 1},"exit",0.2)
Fader.to(UI.shadow,1,"exit",0.2)
Motion.to(UI.underglow,{BackgroundTransparency = 1},"exit",0.2)
task.delay(0.22,function()
if UI.visible then
return
end
UI.mount.Visible = false
for _,value in ipairs({UI.top,UI.sub,UI.view,UI.foot})do
value.Visible = true
end
if callback then
callback()
end
end)
end)
end
