if part then
if part:IsA("BasePart")then
return part.Position
end
if part:IsA("Model")then
if part.PrimaryPart then
return part.PrimaryPart.Position
end
return part:GetPivot().Position
end
return nil
end
return nil
end
local function GetObjectPart(part)
if part then
if part:IsA("BasePart")then
return part
end
if part:IsA("Model")then
return part.PrimaryPart or part:FindFirstChildWhichIsA("BasePart",true)
end
return part:FindFirstChildWhichIsA("BasePart",true)
end
return nil
end
local function FindNet()
local Map = Workspace:FindFirstChild("Map")
if Map then
local BallCollideOnly = Map:FindFirstChild("BallCollideOnly")
if BallCollideOnly then
return BallCollideOnly:FindFirstChild("Net")
end
return nil
end
return nil
end
local function FindLocalBall()
local Character = LocalPlayer.Character
if Character then
local HumanoidRootPart = Character:FindFirstChild("HumanoidRootPart")
if HumanoidRootPart then
local inst2 = nil
local huge = math.huge
for _,inst in ipairs(CollectionService:GetTagged("Ball"))do
if inst:IsDescendantOf(Workspace)then
local objectPosition = GetObjectPosition(inst)
if objectPosition then
local Magnitude =(objectPosition - HumanoidRootPart.Position).Magnitude
if Magnitude < huge then
huge = Magnitude
inst2 = inst
end
end
end
end
if inst2 then
return inst2
end
for _,child in ipairs(Workspace:GetChildren())do
if child.Name:match("^CLIENT_BALL_")then
local objectPosition2 = GetObjectPosition(child)
if objectPosition2 then
local Magnitude2 =(objectPosition2 - HumanoidRootPart.Position).Magnitude
if Magnitude2 < huge then
huge = Magnitude2
inst2 = child
end
end
end
end
return inst2
end
return nil
end
return nil
end
local function GetSetPowerMultiplier()
local ok,result = pcall(function()
return State.get(LocalPlayer,State.Id.Multiplier,"SetPower",1)
end)
if ok and type(result)== "number" then
return result
end
local Multiplier_SetPower = LocalPlayer:GetAttribute("Multiplier_SetPower")
return type(Multiplier_SetPower)== "number" and Multiplier_SetPower or 1
end
