local net = FindNet()
if not net or not net:IsA("BasePart")then
return nil
end
local localPoint = net.CFrame:PointToObjectSpace(Position)
local Vector32
if net.Size.Z <= net.Size.X then
Vector32 = Vector3.new(math.clamp(localPoint.X,-net.Size.X / 2,net.Size.X / 2),0,0)
else
Vector32 = Vector3.new(0,0,math.clamp(localPoint.Z,-net.Size.Z / 2,net.Size.Z / 2))
end
return net.CFrame:PointToWorldSpace(Vector32)
end
