local function SetDistanceForCharge(ratio,setPowerMultiplier,value)
local value2 = math.clamp(ratio,0,1)
local powerScale = PowerScale(setPowerMultiplier)
local scaled =(value3 + value4 * value2)* powerScale
local value7 = value5 + value6 * value2
local gravity = GetGravity()
local value8 = value7 ^ 2 + 2 * gravity * math.max(value,0)
return scaled *((value7 + math.sqrt(value8))/ gravity)
end
local function SolveChargeForDistance(Magnitude,setPowerMultiplier,height)
local value = SetDistanceForCharge(0,setPowerMultiplier,height)
local value2 = SetDistanceForCharge(1,setPowerMultiplier,height)
if Magnitude <= value then
return 0,value,value2
end
if value2 <= Magnitude then
return 1,value,value2
end
local value3 = 0
local value4 = 1
for i = 1,30 do
local ratio =(value3 + value4)/ 2
if SetDistanceForCharge(ratio,setPowerMultiplier,height)< Magnitude then
value3 = ratio
continue
end
value4 = ratio
end
return(value3 + value4)/ 2,value,value2
end
