local function RestoreBallHighlights(ballHighlights)
for _,value in ipairs(ballHighlights)do
if value.inst and value.inst.Parent then
value.inst.Enabled = value.props.Enabled
continue
end
if not(value.parent and value.parent.Parent)then
continue
end
local Highlight = Instance.new("Highlight")
if value.props.FillColor then
Highlight.FillColor = value.props.FillColor
end
if value.props.OutlineColor then
Highlight.OutlineColor = value.props.OutlineColor
end
if value.props.FillTransparency then
Highlight.FillTransparency = value.props.FillTransparency
end
if value.props.OutlineTransparency then
Highlight.OutlineTransparency = value.props.OutlineTransparency
end
Highlight.Enabled = value.props.Enabled
Highlight.Parent = value.parent
end
end
